/** How a tube is highlighted. */
enum class TubeHighlight { NONE, SELECTED, HINT_FROM, HINT_TO }

/**
 * Sand on its way in or out during a pour: [units] (read while drawing, so it can change every frame) more units
 * of [color] drawn on top of the tube's own layers. A fraction of a unit fills part of a layer.
 */
class PouringSand(val color: SandColor, val units: () -> Float)

/**
 * One candy-glass tube with its sand. Lifts a little as a hint's source (the paw lifts a selected one), glows
 * while selected or hinted, and a finished tube gets a cork that pops on (see [rememberCapPop]).
 * A [hidden] tube keeps its place and still takes taps, but isn't drawn (the pour animation is holding it).
 */
@Composable
fun TubeView(
    tube: Tube,
    highlight: TubeHighlight,
    width: Dp,
    onTap: () -> Unit,
    modifier: Modifier = Modifier,
    pouring: PouringSand? = null,
    hidden: Boolean = false,
) {
    val lift by animateDpAsState(
        when (highlight) {
            TubeHighlight.HINT_FROM -> -width * 0.2f
            else -> 0.dp
        },
    )
    val description = "Tube: " + tube.layers.joinToString(", ") { it.name.lowercase() }.ifEmpty { "empty" }
    val palette = LocalPalette.current
    val arena = LocalArena.current
    val texture = remember(arena) { SandTexture(arena) }
    val finished = tube.isFull && tube.isUniform
    val cap = rememberCapPop(finished)
    val hinted = highlight == TubeHighlight.HINT_FROM || highlight == TubeHighlight.HINT_TO
    val pulse = if (hinted) rememberGlowPulse() else null
    Spacer(
        modifier
            .offset(y = lift)
            .size(width, width * TUBE_ASPECT)
            .semantics { contentDescription = description }
            .clickable(interactionSource = remember { MutableInteractionSource() }, indication = null, onClick = onTap)
            .drawWithCache {
                val glass = TubeGlass(size, palette)
                onDrawBehind {
                    if (hidden) return@onDrawBehind
                    glass.drawBack(this)
                    clipPath(glass.body) { drawSand(tube, texture, palette, pouring) }
                    glass.drawFront(this)
                    when (highlight) {
                        TubeHighlight.SELECTED -> glass.drawOutline(this, palette.selected, glow = 1f)
                        TubeHighlight.HINT_FROM, TubeHighlight.HINT_TO ->
                            glass.drawOutline(this, palette.highlight, glow = 0.35f + 0.65f * (pulse?.value ?: 1f))
                        TubeHighlight.NONE ->
                            if (finished) glass.drawOutline(this, palette.done, glow = 0.45f) else glass.drawOutline(this, palette.glassOutline)
                    }
                    if (finished) drawCap(palette.sand(tube.layers.first()), cap.value)
                }
            },
    )
}

/** The slow breathing of a hint's glow, 0 to 1 and back. */
@Composable
private fun rememberGlowPulse(): State<Float> =
    rememberInfiniteTransition().animateFloat(0f, 1f, infiniteRepeatable(tween(850, easing = FastOutSlowInEasing), RepeatMode.Reverse))

const val TUBE_ASPECT = 3.6f

/** Height of one unit of sand in a tube [width] by [height]. Sand fills from the bottom; the top 8% is the neck. */
internal fun sandUnitHeight(width: Float, height: Float, capacity: Int): Float =
    (height - width * 0.03f - height * 0.08f) / capacity

/** Height above the tube's bottom edge of the sand surface when the tube holds [units] of sand. */
internal fun sandLevel(width: Float, height: Float, capacity: Int, units: Float): Float =
    width * 0.03f + sandUnitHeight(width, height, capacity) * units

/**
 * The tube's sand, layer by layer, then the light and shade that give it depth. In the Desert, two differently
 * colored layers meet in a dune ripple that grows in as the upper one starts to fill.
 */
private fun DrawScope.drawSand(tube: Tube, texture: SandTexture, palette: Palette, pouring: PouringSand?) {
    val unit = sandUnitHeight(size.width, size.height, tube.capacity)
    val base = size.height - size.width * 0.03f
    // Pouring sand: whole layers, then the bottom part of the last one. Its grains don't move as it fills,
    // so the texture runs on seamlessly into the finished layer.
    val poured = (pouring?.units?.invoke() ?: 0f).coerceIn(0f, (tube.capacity - tube.size).toFloat())
    val count = tube.size + ceil(poured).toInt()
    if (count == 0) return
    fun colorAt(k: Int) = if (k < tube.size) tube.layers[k] else pouring!!.color
    fun fillAt(k: Int) = if (k < tube.size) 1f else (poured - (k - tube.size)).coerceAtMost(1f)
    val fullRipple = if (texture.arena == Arena.DESERT) rippleDepth(size.width, unit) else 0f
    fun rippleAt(k: Int) =
        if (fullRipple > 0f && k in 1 until count && colorAt(k) != colorAt(k - 1)) fullRipple * (fillAt(k) / 0.35f).coerceAtMost(1f) else 0f

    for (k in 0 until count) {
        val color = colorAt(k)
        val bottom = base - unit * k
        val top = bottom - unit
        val above = rippleAt(k + 1) / 2
        val below = rippleAt(k)
        val seed = color.ordinal * 31 + k
        val layer: DrawScope.() -> Unit = {
            drawRect(palette.sand(color), topLeft = Offset(0f, top - above), size = Size(size.width, unit + above + below / 2 + 0.5f))
            drawSandTexture(texture, top, unit, seed)
        }
        val rippled: DrawScope.() -> Unit = { if (below > 0f) clipPath(ripplePath(size.width, bottom, below, seed), block = layer) else layer() }
        val fill = fillAt(k)
        if (fill < 1f) clipRect(top = bottom - unit * fill, block = rippled) else rippled()
    }
    val inset = size.width * BODY_INSET
    drawSandDepth(texture.arena, inset, size.width - inset, base - unit * (tube.size + poured), unit)
}
