package io.colorsand.ui.minigame

import kotlin.math.abs
import kotlin.math.roundToInt

/**
 * One band of colored sand in the bottle: the jar [color] it was poured from and its [top] surface, a height (0 at
 * the bottom of the bottle, 1 at its shoulder) for each column across the bottle. The band reaches down to the top
 * of the one under it. [volume] is how much sand went into it, as a share of the whole bottle.
 */
class SandLayer(val color: Int, val top: List<Float>, val volume: Float)

/**
 * A sand art bottle being filled: [columns] columns across it and the [layers] poured so far, bottom to top. Sand
 * poured at a point lands there and runs down to its angle of rest ([REPOSE]), so the surface heaps up under the
 * stream; moving the stream from side to side while pouring lays the classic wavy bands. There is nothing to get
 * wrong: every pour adds sand until the bottle is [isFull]. The state is immutable; [pour] returns the next one.
 */
class SandArt private constructor(val columns: Int, val layers: List<SandLayer>) {
    /** The sand's surface: the top of the last layer, or the empty bottle's floor. */
    val surface: List<Float> = layers.lastOrNull()?.top ?: List(columns) { 0f }

    /** How full the bottle is, 0 to 1: the sand poured as a share of the bottle. */
    val fill: Float = surface.sum() / columns

    /** Whether the bottle is filled up to its shoulder, ready for its cork. */
    val isFull: Boolean get() = fill >= FULL

    /** The bottle's fill toward [FULL] as a whole percentage, 0 to 100. */
    val percent: Int get() = (fill / FULL * 100f).roundToInt().coerceIn(0, 100)

    /**
     * The bottle after pouring [amount] (a share of the whole bottle) of jar [color]'s sand with the stream landing
     * at [at] (0 is the left wall, 1 the right). The sand joins the top layer if it has the same color, unless
     * [fresh] starts a new band, as each new press of the stream does. Pouring into a full bottle does nothing.
     */
    fun pour(color: Int, at: Float, amount: Float, fresh: Boolean = false): SandArt {
        if (isFull || amount <= 0f) return this
        val h = surface.toFloatArray()
        val target = at.coerceIn(0f, 1f) * (columns - 1)
        var left = amount * columns
        while (left > 0f) {
            val chunk = minOf(left, CHUNK)
            left -= chunk
            deposit(h, target, chunk)
            relax(h)
        }
        val added = h.sum() / columns - fill
        // Where sand slid off an old heap, the bands under it slid down with it.
        val below = if (h.indices.any { h[it] < surface[it] }) {
            layers.map { layer -> SandLayer(layer.color, layer.top.mapIndexed { c, t -> minOf(t, h[c]) }, layer.volume) }
        } else {
            layers
        }
        val last = below.lastOrNull()
        val next = when {
            last == null -> listOf(SandLayer(color, h.toList(), added))
            // The same stream going on, or a tap that hardly poured anything: no band of its own.
            (last.color == color && !fresh) || last.volume < THIN -> below.dropLast(1) + SandLayer(color, h.toList(), last.volume + added)
            else -> below + SandLayer(color, h.toList(), added)
        }
        return SandArt(columns, next)
    }

    /**
     * One whole layer of jar [color] poured in one go: [LAYER] of the bottle, landing at the next of a few spots
     * that wander from side to side, so poured layer by layer (by keyboard or screen reader) it still comes out wavy.
     */
    fun pourLayer(color: Int): SandArt = pour(color, layerSpot(layers.size), LAYER, fresh = true)

    /** Drops [chunk] column-heights of sand around [target], into the nearest columns that still have room. */
    private fun deposit(h: FloatArray, target: Float, chunk: Float) {
        val center = target.roundToInt().coerceIn(0, columns - 1)
        val spread = listOf(-1 to 0.25f, 0 to 0.5f, 1 to 0.25f)
        var spill = 0f
        for ((d, share) in spread) {
            val c = center + d
            if (c !in 0 until columns) { spill += chunk * share; continue }
            val room = 1f - h[c]
            val put = minOf(room, chunk * share)
            h[c] += put
            spill += chunk * share - put
        }
        // What didn't fit runs to the nearest column with room.
        while (spill > EPSILON) {
            val c = (0 until columns).filter { h[it] < 1f - EPSILON }.minByOrNull { abs(it - target) } ?: return
            val put = minOf(1f - h[c], spill)
            h[c] += put
            spill -= put
        }
    }

    /** Lets every slope steeper than [REPOSE] slide down until the surface rests. Sand only moves downhill. */
    private fun relax(h: FloatArray) {
        val repose = REPOSE / columns
        repeat(RELAX_PASSES) {
            var moved = false
            for (i in 0 until columns - 1) moved = slide(h, i, i + 1, repose) || moved
            for (i in columns - 1 downTo 1) moved = slide(h, i, i - 1, repose) || moved
            if (!moved) return
        }
    }

    private fun slide(h: FloatArray, a: Int, b: Int, repose: Float): Boolean {
        val d = h[a] - h[b]
        if (abs(d) <= repose) return false
        val move = (abs(d) - repose) / 2
        if (d > 0) { h[a] -= move; h[b] += move } else { h[b] -= move; h[a] += move }
        return true
    }

    companion object {
        /** The fill at which the bottle counts as full and gets its cork. */
        const val FULL = 0.95f

        /** How much of the bottle one [pourLayer] fills. */
        const val LAYER = 0.125f

        /** The steepest the sand rests at: how far it can rise across the whole bottle's width, in bottle heights. */
        const val REPOSE = 0.34f

        /** A band thinner than this (a share of the bottle) is merged with the next pour of the same color. */
        const val THIN = 0.002f

        private const val CHUNK = 0.05f
        private const val RELAX_PASSES = 24
        private const val EPSILON = 1e-5f

        /** Where layer number [index] lands when poured layer by layer: wandering from side to side. */
        fun layerSpot(index: Int): Float = SPOTS[index % SPOTS.size]

        private val SPOTS = listOf(0.5f, 0.18f, 0.82f, 0.32f, 0.7f, 0.12f, 0.88f, 0.45f)

        /** An empty bottle [columns] columns across. */
        fun empty(columns: Int = 40): SandArt = SandArt(columns, emptyList())
    }
}
