import kotlin.random.Random

enum class ConfettiShape { RIBBON, DOT, LEAF, STAR }

/**
 * One piece of confetti. Positions are fractions of the drawing area, times are seconds after the start,
 * so the same pieces fit any screen size.
 */
data class ConfettiPiece(
    val shape: ConfettiShape,
    /** Index into the confetti colors. */
    val colorIndex: Int,
    /** Horizontal center at the start, 0..1 of the width. */
    val x: Float,
    /** Vertical center at the start, 0..1 of the height (negative is above the top edge). */
    val y: Float,
    /** Seconds before the piece shows up. */
    val delay: Float,
    /** Seconds the piece is visible, fade in and fade out included. */
    val life: Float,
    /** Falling speed in heights per second. */
    val fall: Float,
    /** Sideways sway amplitude as a fraction of the width, and its frequency in swings per second. */
    val sway: Float,
    val swayRate: Float,
    val phase: Float,
    /** Starting angle and spin in degrees per second. */
    val angle: Float,
    val spin: Float,
    /** Size in dp. */
    val size: Float,
)

/** Where a piece is at time [t] seconds, as fractions of the area, plus its angle and opacity. */
data class ConfettiPose(val x: Float, val y: Float, val angle: Float, val alpha: Float, val flip: Float)

object ConfettiMath {
    /** The whole shower lasts this long, so the overlay can stop drawing. */
    fun duration(pieces: List<ConfettiPiece>): Float = pieces.maxOfOrNull { it.delay + it.life } ?: 0f

    /**
     * A gentle shower of [count] pieces in [colorCount] colors. The same [seed] always gives the same pieces.
     * Most pieces start above the top edge; a few start lower and fade in so the screen fills quickly
     * without anything bursting.
     */
    fun pieces(seed: Int, count: Int = 64, colorCount: Int = 6): List<ConfettiPiece> {
        require(count >= 0 && colorCount > 0)
        val random = Random(seed)
        fun between(from: Float, to: Float) = from + random.nextFloat() * (to - from)
        return List(count) {
            val roll = random.nextFloat()
            val shape = when {
                roll < 0.45f -> ConfettiShape.RIBBON
                roll < 0.75f -> ConfettiShape.DOT
                roll < 0.9f -> ConfettiShape.LEAF
                else -> ConfettiShape.STAR
            }
            ConfettiPiece(
                shape = shape,
                colorIndex = random.nextInt(colorCount),
                x = between(0.03f, 0.97f),
                y = if (random.nextFloat() < 0.55f) between(-0.12f, 0f) else between(0.05f, 0.5f),
                delay = between(0f, 0.6f),
                life = between(2.2f, 2.9f),
                fall = between(0.12f, 0.26f),
                sway = between(0.01f, 0.03f),
                swayRate = between(0.35f, 0.7f),
                phase = between(0f, 1f),
                angle = between(0f, 360f),
                spin = between(40f, 140f) * if (random.nextBoolean()) 1 else -1,
                size = when (shape) {
                    ConfettiShape.RIBBON -> between(8f, 11f)
                    ConfettiShape.DOT -> between(5f, 7.5f)
                    ConfettiShape.LEAF -> between(9f, 12f)
                    ConfettiShape.STAR -> between(9f, 12f)
                },
            )
        }
    }

    /** The pose of [piece] at [t] seconds, or null while it is not visible. */
    fun pose(piece: ConfettiPiece, t: Float): ConfettiPose? {
        val age = t - piece.delay
        if (age < 0f || age > piece.life) return null
        val fadeIn = min(1f, age / 0.3f)
        val fadeOut = min(1f, (piece.life - age) / 0.8f)
        val swing = sin(2 * PI.toFloat() * (piece.swayRate * age + piece.phase))
        return ConfettiPose(
            x = piece.x + piece.sway * swing,
            y = piece.y + piece.fall * age,
            angle = piece.angle + piece.spin * age + 12f * swing,
            alpha = max(0f, min(fadeIn, fadeOut)),
            // Ribbons turn over slowly, which shows as their width breathing.
            flip = cos(2 * PI.toFloat() * (piece.swayRate * 0.8f * age + piece.phase)),
        )
    }
}

/** Softened sand colors of [palette] for confetti: a little closer to the warm accent so they stay calm. */
fun confettiColors(palette: Palette): List<Color> =
    listOf(SandColor.RED, SandColor.YELLOW, SandColor.GREEN, SandColor.BLUE, SandColor.PINK, SandColor.CYAN)
        .map { lerp(palette.sand(it), palette.accent, 0.3f) }

/**
 * A soft confetti shower that drifts down over the whole area once and fades away. It draws only and takes no
 * input, so taps reach whatever is underneath.
 */
@Composable
fun Confetti(seed: Int, modifier: Modifier = Modifier) {
    val colors = confettiColors(LocalPalette.current)
    val pieces = remember(seed, colors.size) { ConfettiMath.pieces(seed, colorCount = colors.size) }
    val duration = remember(pieces) { ConfettiMath.duration(pieces) }
    val time = remember(seed) { Animatable(0f) }
    LaunchedEffect(seed) {
        time.animateTo(duration, tween((duration * 1000).toInt(), easing = LinearEasing))
    }
    Canvas(modifier) {
        val t = time.value
        if (t >= duration) return@Canvas
        for (piece in pieces) {
            val pose = ConfettiMath.pose(piece, t) ?: continue
            val color = colors[piece.colorIndex].copy(alpha = 0.95f * pose.alpha)
            translate(pose.x * size.width, pose.y * size.height) {
                rotate(pose.angle, pivot = Offset.Zero) {
                    drawPiece(piece.shape, piece.size * density, pose.flip, color)
                }
            }
        }
    }
}

private fun DrawScope.drawPiece(shape: ConfettiShape, s: Float, flip: Float, color: Color) {
    when (shape) {
        ConfettiShape.RIBBON -> {
            val w = s * (0.25f + 0.75f * abs(flip))
            val h = s * 0.55f
            drawRoundRect(color, Offset(-w / 2, -h / 2), Size(w, h), CornerRadius(h * 0.35f))
        }
        ConfettiShape.DOT -> drawCircle(color, radius = s / 2, center = Offset.Zero)
        ConfettiShape.LEAF -> scale(1f, 0.6f + 0.4f * abs(flip), pivot = Offset.Zero) {
            val leaf = Path().apply {
                moveTo(0f, -s / 2)
                quadraticBezierTo(s * 0.45f, 0f, 0f, s / 2)
                quadraticBezierTo(-s * 0.45f, 0f, 0f, -s / 2)
                close()
            }
            drawPath(leaf, color)
        }
        ConfettiShape.STAR -> drawPath(starPath(s / 2), color)
    }
}

/** A plump five-pointed star around the origin. */
private fun starPath(radius: Float): Path = Path().apply {
    val inner = radius * 0.5f
    for (i in 0 until 10) {
        val r = if (i % 2 == 0) radius else inner
        val a = -PI / 2 + i * PI / 5
        val px = (r * cos(a)).toFloat()
        val py = (r * sin(a)).toFloat()
        if (i == 0) moveTo(px, py) else lineTo(px, py)
    }
    close()
}
