// The Playground's toys and the Beach's finds, in the order they are earned. See KeepsakeArt.kt for the box.

internal fun DrawScope.playgroundKeepsake(stage: Int, t: Float, g: SceneGrade) = when (stage) {
    1 -> ball(t, g)
    2 -> rubberDuck(t, g)
    3 -> dumpTruck(t, g)
    4 -> teddyBear(t, g)
    else -> kite(t, g)
}

internal fun DrawScope.beachKeepsake(stage: Int, t: Float, g: SceneGrade) = when (stage) {
    1 -> starfish(t, g)
    2 -> crab(t, g)
    3 -> sandcastle(t, g)
    4 -> beachUmbrella(t, g)
    else -> surfboard(t, g)
}

private val star = starPath(0.45f)
private val roundStar = starPath(0.5f)

/** A red play ball with a yellow star, hopping now and then. */
private fun DrawScope.ball(t: Float, g: SceneGrade) {
    val hop = abs(swing(t, 40)).let { if (it > 0.85f) (it - 0.85f) * 40f else 0f }
    groundShadow(50f, 40f - hop)
    val cy = 73f - hop
    dot(g(0xFFC23338), 50f, cy, 22f)
    dot(g(0xFFE8494E), 48f, cy - 2f, 20f)
    translate(49f, cy - 1f) { rotate(-12f, Offset.Zero) { scale(10f, 10f, Offset.Zero) { drawPath(star, g(0xFFFFD447)) } } }
    oval(Color.White.copy(alpha = 0.55f), 40f, cy - 11f, 6f, 3.5f)
}

/** A yellow rubber duck, rocking gently. */
private fun DrawScope.rubberDuck(t: Float, g: SceneGrade) {
    groundShadow(52f, 52f)
    rotate(swing(t, 30) * 4f, Offset(52f, GROUND)) {
        val shade = g(0xFFE7A91C)
        val yellow = g(0xFFFFD43F)
        drawPath(duckTail, shade)
        oval(shade, 52f, 79f, 27f, 16f)
        oval(yellow, 51f, 77f, 25.5f, 14.5f)
        oval(shade, 45f, 77f, 12f, 7f)
        oval(yellow, 44f, 75.5f, 11f, 5.5f)
        dot(shade, 64f, 55f, 14f)
        dot(yellow, 63f, 54f, 13f)
        oval(g(0xFFF07A28), 79f, 59f, 8.5f, 3.6f)
        oval(g(0xFFFF9A3D), 78.5f, 57.5f, 8f, 3f)
        eye(67f, 50f, 2.6f)
        oval(g(0xFFFF9B8A).copy(alpha = 0.6f), 69f, 58f, 3.5f, 2f)
        oval(Color.White.copy(alpha = 0.5f), 57f, 46f, 4f, 2.5f)
    }
}

private val duckTail = polygon(24f, 64f, 36f, 70f, 34f, 82f)

/** A toy dump truck: red cab, yellow tipper full of sand. */
private fun DrawScope.dumpTruck(t: Float, g: SceneGrade) {
    groundShadow(50f, 80f)
    val idle = swing(t, 90) * 0.6f
    translate(0f, idle) {
        box(g(0xFF5A6270), 14f, 76f, 88f, 84f, 3f)
        oval(g(0xFFE6C38A), 37f, 57f, 21f, 7f)
        dot(g(0xFFF2D7A2), 30f, 54f, 4f)
        drawPath(truckBed, g(0xFFE6A51D))
        drawPath(truckBedLit, g(0xFFFFC93A))
        box(g(0xFFC9363B), 62f, 50f, 89f, 82f, 6f)
        box(g(0xFFE84B4F), 62f, 50f, 86f, 79f, 6f)
        box(g(0xFF9FD6F2), 68f, 55f, 83f, 66f, 3f)
        box(Color.White.copy(alpha = 0.5f), 70f, 57f, 74f, 64f, 2f)
        box(g(0xFFFFE9A6), 84f, 70f, 89f, 75f, 2f)
    }
    for (x in floatArrayOf(28f, 72f)) {
        dot(g(0xFF2E333B), x, 85f, 10.5f)
        dot(g(0xFFBFC7D1), x, 85f, 4.5f)
        dot(g(0xFF8D96A2), x, 85f, 2f)
    }
}

private val truckBed = polygon(10f, 54f, 62f, 58f, 60f, 80f, 18f, 80f)
private val truckBedLit = polygon(12f, 56f, 59f, 60f, 57f, 74f, 19f, 74f)

/** A sitting teddy bear with a red bow, tilting its head now and then. */
private fun DrawScope.teddyBear(t: Float, g: SceneGrade) {
    val fur = g(0xFFB07A4A)
    val dark = g(0xFF8A5A33)
    val light = g(0xFFE6C496)
    groundShadow(50f, 58f)
    oval(dark, 35f, 88f, 12f, 8f)
    oval(dark, 65f, 88f, 12f, 8f)
    dot(light, 30f, 88f, 5.5f)
    dot(light, 70f, 88f, 5.5f)
    oval(dark, 50f, 73f, 21f, 21f)
    oval(fur, 49f, 71f, 19.5f, 19.5f)
    oval(light, 50f, 76f, 11f, 12f)
    oval(dark, 30f, 71f, 7f, 11f)
    oval(fur, 70f, 70f, 7f, 11f)
    rotate(swing(t, 20) * 5f, Offset(50f, 58f)) {
        dot(dark, 35f, 30f, 7.5f)
        dot(dark, 65f, 30f, 7.5f)
        dot(light, 35f, 30f, 3.8f)
        dot(light, 65f, 30f, 3.8f)
        dot(dark, 50f, 45f, 18.5f)
        dot(fur, 49f, 44f, 17.5f)
        oval(light, 50f, 51f, 8.5f, 6.5f)
        oval(g(0xFF3A2618), 50f, 47.5f, 3.6f, 2.6f)
        eye(43f, 40f, 2.4f)
        eye(57f, 40f, 2.4f)
    }
    drawPath(bow, g(0xFFE24A57))
    dot(g(0xFFC23545), 50f, 60f, 2.6f)
}

private val bow = polygon(50f, 60f, 41f, 55f, 41f, 65f, 50f, 60f, 59f, 55f, 59f, 65f)

/** A four-colored kite flying on its string from a peg, bobbing and swaying, its bowed tail fluttering. */
private fun DrawScope.kite(t: Float, g: SceneGrade) {
    val bob = swing(t, 24) * 3f
    val sway = swing(t, 17) * 7f
    val cx = 58f
    val cy = 28f + bob
    groundShadow(28f, 12f)
    box(g(0xFF8A5A33), 26f, 88f, 30f, 96f, 1f)
    stick(Color.White.copy(alpha = 0.85f), 28f, 89f, cx - 2f, cy + 4f, 0.9f)
    // The tail hangs from the kite's bottom point and waves as it goes down.
    var px = cx
    var py = cy + 24f
    for (k in 1..4) {
        val nx = cx - 3f * k + swing(t, 45, k * 0.18f) * 4f
        val ny = cy + 24f + 9f * k
        stick(g(0xFF3A4A6B), px, py, nx, ny, 1.2f)
        oval(if (k % 2 == 0) g(0xFFFFD447) else g(0xFFE8494E), nx - 2.5f, ny, 2.5f, 1.6f)
        oval(if (k % 2 == 0) g(0xFFFFD447) else g(0xFFE8494E), nx + 2.5f, ny, 2.5f, 1.6f)
        px = nx
        py = ny
    }
    translate(cx, cy) {
        rotate(sway, Offset.Zero) {
            drawPath(kiteTopLeft, g(0xFFE8494E))
            drawPath(kiteTopRight, g(0xFFFFC93A))
            drawPath(kiteBottomLeft, g(0xFF3E8EE0))
            drawPath(kiteBottomRight, g(0xFF4DBA6A))
            stick(g(0xFF6B4A2E), 0f, -22f, 0f, 24f, 1.4f)
            stick(g(0xFF6B4A2E), -16f, -2f, 16f, -2f, 1.4f)
        }
    }
}

private val kiteTopLeft = polygon(0f, -22f, 0f, -2f, -16f, -2f)
private val kiteTopRight = polygon(0f, -22f, 16f, -2f, 0f, -2f)
private val kiteBottomLeft = polygon(-16f, -2f, 0f, -2f, 0f, 24f)
private val kiteBottomRight = polygon(0f, -2f, 16f, -2f, 0f, 24f)

/** A coral starfish lying on the sand, breathing a little. */
private fun DrawScope.starfish(t: Float, g: SceneGrade) {
    groundShadow(50f, 50f, 0.16f)
    val s = 22f * (1f + 0.025f * swing(t, 20))
    translate(50f, 80f) {
        scale(s, s * 0.62f, Offset.Zero) {
            drawPath(roundStar, g(0xFFD45A35), style = Stroke(width = 0.28f, join = StrokeJoin.Round))
            drawPath(roundStar, g(0xFFD45A35))
            translate(-0.04f, -0.08f) {
                scale(0.86f, 0.86f, Offset.Zero) {
                    drawPath(roundStar, g(0xFFF47A50), style = Stroke(width = 0.24f, join = StrokeJoin.Round))
                    drawPath(roundStar, g(0xFFF47A50))
                }
            }
        }
    }
    val dots = g(0xFFFFC7A3)
    dot(dots, 50f, 80f, 2.2f)
    dot(dots, 50f, 71f, 1.5f)
    dot(dots, 41f, 78f, 1.5f)
    dot(dots, 59f, 78f, 1.5f)
    dot(dots, 45f, 85f, 1.5f)
    dot(dots, 55f, 85f, 1.5f)
}

/** A red crab scuttling side to side, legs ticking, claws up. */
private fun DrawScope.crab(t: Float, g: SceneGrade) {
    val x = swing(t, 20) * 6f
    val step = swing(t, 240)
    groundShadow(50f + x, 50f)
    translate(x, 0f) {
        val shell = g(0xFFE85A3C)
        val shade = g(0xFFC4412A)
        for (k in 0..2) {
            val lift = if (k % 2 == 0) step * 1.5f else -step * 1.5f
            stick(shade, 38f - k * 2f, 80f + k * 3f, 25f - k * 2f, 92f + lift - k, 3f)
            stick(shade, 62f + k * 2f, 80f + k * 3f, 75f + k * 2f, 92f - lift - k, 3f)
        }
        stick(shade, 36f, 74f, 25f, 64f, 4f)
        stick(shade, 64f, 74f, 75f, 64f, 4f)
        for (side in floatArrayOf(-1f, 1f)) {
            val cx = 50f + side * 29f
            oval(shade, cx, 59f, 8f, 7f)
            oval(shell, cx - side * 0.5f, 58f, 7f, 6f)
            oval(shell, cx + side * 3f, 50f, 4f, 5f)
            stick(shade, cx - side * 1f, 53f, cx + side * 4f, 56f, 1.2f)
        }
        stick(shade, 45f, 70f, 43f, 58f, 2.2f)
        stick(shade, 55f, 70f, 57f, 58f, 2.2f)
        dot(Color.White, 43f, 57f, 3.8f)
        dot(Color.White, 57f, 57f, 3.8f)
        eye(43.5f, 57.5f, 2f)
        eye(56.5f, 57.5f, 2f)
        oval(shade, 50f, 80f, 21f, 12.5f)
        oval(shell, 50f, 78f, 20f, 11f)
        oval(Color.White.copy(alpha = 0.35f), 43f, 73f, 6f, 2.5f)
        drawArc(g(0xFF7A2618), 180f, -180f, false, Offset(46f, 76f), Size(8f, 5f), style = Stroke(1.4f))
    }
}

/** A sandcastle with three towers, a door and a fluttering red flag. */
private fun DrawScope.sandcastle(t: Float, g: SceneGrade) {
    val sand = g(0xFFEBCB8C)
    val shade = g(0xFFCFA866)
    val dark = g(0xFF9A7446)
    groundShadow(50f, 76f)
    stick(g(0xFF6B4A2E), 50f, 34f, 50f, 13f, 1.4f)
    rotate(swing(t, 50) * 8f, Offset(50f, 17f)) { drawPath(flag, g(0xFFE8494E)) }
    box(shade, 40f, 34f, 60f, 72f)
    box(sand, 40f, 34f, 56f, 72f)
    crenels(40f, 34f, 20f, sand)
    box(shade, 23f, 66f, 77f, 95f, 2f)
    box(sand, 23f, 66f, 73f, 95f, 2f)
    for ((l, r) in listOf(14f to 34f, 66f to 86f)) {
        box(shade, l, 48f, r, 95f, 2f)
        box(sand, l, 48f, r - 4f, 95f, 2f)
        crenels(l, 48f, r - l, sand)
        box(dark, l + 7f, 58f, l + 12f, 66f, 2.5f)
    }
    box(dark, 45f, 78f, 55f, 95f, 5f)
    box(dark, 47f, 44f, 52f, 52f, 2.5f)
    oval(g(0xFFF7B3B8), 31f, 82f, 3f, 2.2f)
    oval(g(0xFFFFF4E0), 70f, 86f, 2.6f, 2f)
    for (x in floatArrayOf(20f, 37f, 62f, 78f)) dot(shade, x, 88f, 0.9f)
}

private val flag = polygon(50f, 13f, 65f, 16.5f, 50f, 22f)

/** Three little crenels on a tower [width] wide from [left], whose top is [top]. */
private fun DrawScope.crenels(left: Float, top: Float, width: Float, color: Color) {
    val w = width / 5
    for (k in 0..2) box(color, left + k * 2 * w, top - 4f, left + k * 2 * w + w, top + 1f)
}

/** A red-and-white beach umbrella stuck in the sand, swaying a touch in the breeze. */
private fun DrawScope.beachUmbrella(t: Float, g: SceneGrade) {
    groundShadow(54f, 70f, 0.16f)
    rotate(-8f + swing(t, 15) * 1.5f, Offset(52f, GROUND)) {
        stick(g(0xFFEDEBE6), 52f, 22f, 52f, 96f, 2.6f)
        clipPath(umbrella) {
            drawPath(umbrella, g(0xFFFFF4E6))
            for (k in 0..3) drawPath(umbrellaStripes[k], g(0xFFE8494E))
            box(Color.Black.copy(alpha = 0.12f), 0f, 44f, 100f, 60f)
        }
        dot(g(0xFFE8494E), 52f, 17f, 2.8f)
    }
    oval(g(0xFFF5E2B8), 52f, 95f, 9f, 2.5f)
}

private val umbrella = Path().apply {
    moveTo(12f, 48f)
    quadraticBezierTo(50f, -8f, 92f, 48f)
    for (k in 0 until 5) {
        val x = 92f - 16f * k
        quadraticBezierTo(x - 8f, 41f, x - 16f, 48f)
    }
    close()
}

private val umbrellaStripes = List(4) { k ->
    val x = 12f + 16f * (2 * k)
    polygon(52f, 18f, x, 56f, x + 16f, 56f)
}

/** A turquoise surfboard standing in the sand, a glint running down its side. */
private fun DrawScope.surfboard(t: Float, g: SceneGrade) {
    groundShadow(54f, 34f)
    rotate(-11f, Offset(50f, GROUND)) {
        drawPath(board, g(0xFF1F94A8))
        clipPath(board) {
            translate(-3f, 0f) { drawPath(board, g(0xFF34C2D2)) }
            box(g(0xFFFF9E3D), 0f, 26f, 100f, 33f)
            box(g(0xFFFFE07A), 0f, 33f, 100f, 36f)
        }
        stick(Color.White.copy(alpha = 0.8f), 49f, 12f, 49f, 90f, 1.3f)
        val glint = swing(t, 10)
        if (glint > 0.6f) drawSparkle(Offset(42f, 60f - (glint - 0.6f) * 60f), 4f, Color.White.copy(alpha = (glint - 0.6f) * 2.5f))
    }
    oval(g(0xFFE9D3A2), 50f, 94f, 14f, 3.5f)
}

private val board = Path().apply {
    moveTo(50f, 6f)
    quadraticBezierTo(66f, 20f, 64f, 52f)
    quadraticBezierTo(62f, 86f, 50f, 96f)
    quadraticBezierTo(38f, 86f, 36f, 52f)
    quadraticBezierTo(34f, 20f, 50f, 6f)
    close()
}
