package io.colorsand.ui.hud

import androidx.compose.runtime.Composable
import androidx.compose.runtime.CompositionLocalProvider
import androidx.compose.runtime.remember
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.lerp
import io.colorsand.ui.LocalPalette
import io.colorsand.ui.Palette

/**
 * The palette the HUD is drawn in. The scenery is daylight in every scheme, so the HUD always uses light frosted
 * panels with dark ink: a light [palette] is kept as it is, and a dark one is turned around, with its cream accent
 * as the panel tint and its night colors as the ink and the buttons. That keeps each scheme's two main colors and
 * reads like the light schemes over the bright arenas.
 */
fun hudPalette(palette: Palette): Palette {
    if (palette.isLight) return palette
    val ink = palette.onAccent
    return Palette(
        name = palette.name,
        sand = palette.sand,
        backgroundTop = palette.backgroundTop,
        backgroundBottom = palette.backgroundBottom,
        // Buttons and titles in the scheme's night blue, with its cream on them.
        accent = palette.surface,
        onAccent = palette.accent,
        highlight = palette.highlight,
        done = palette.done,
        surface = lerp(Color.White, palette.accent, PANEL_TINT),
        text = ink,
        dimText = ink.copy(alpha = 0.7f),
        isLight = true,
        glass = palette.glass,
        glassOutline = palette.glassOutline,
        glassShine = palette.glassShine,
        selected = palette.selected,
        scrim = palette.scrim,
    )
}

/** How much of a dark scheme's cream accent tints the white HUD panels. */
private const val PANEL_TINT = 0.4f

/** Runs [content] with [hudPalette] as the palette and the game font, for HUD pieces on the scenery. */
@Composable
fun WithHudLook(content: @Composable () -> Unit) {
    val palette = LocalPalette.current
    val hud = remember(palette) { hudPalette(palette) }
    CompositionLocalProvider(LocalPalette provides hud) { WithGameFont(content) }
}
