package io.colorsand.core

/**
 * Where a level is played. Each arena has its own scenery and sand, and [LEVELS] levels in a row:
 * 1-5 the Playground, 6-10 the Beach, 11-15 the Sea Floor, 16-20 the Desert, 21-25 the Building Site and
 * 26-30 Mars. Past level 30 the arenas repeat in the same order.
 */
enum class Arena(val title: String) {
    PLAYGROUND("Playground"),
    BEACH("Beach"),
    SEA_FLOOR("Sea Floor"),
    DESERT("Desert"),
    BUILDING_SITE("Building Site"),
    MARS("Mars");

    companion object {
        const val LEVELS = 5

        /** The arena that level [number] (1-based) is played in. */
        fun of(number: Int): Arena {
            require(number >= 1) { "Level numbers start at 1, was $number" }
            return entries[(number - 1) / LEVELS % entries.size]
        }

        /** Level [number]'s place in its arena, 1..[LEVELS]. */
        fun stage(number: Int): Int = (number - 1) % LEVELS + 1

        /** True for the first level of an arena, where it is introduced. */
        fun isFirst(number: Int): Boolean = stage(number) == 1

        /** True for the last level of an arena, which clears it. */
        fun isLast(number: Int): Boolean = stage(number) == LEVELS
    }
}
