// What Treasure dig turns up, painted like the keepsakes: in a 100 x 100 box, centered on (50, 55), in the scenes'
// flat two-tone style.

/** Something buried in a Treasure dig: its [name] as it reads in a sentence, and its painting. */
internal class DigFind(val name: String, val draw: DrawScope.(SceneGrade) -> Unit)

/** The Playground sandbox's lost toys. */
internal val sandboxToys = listOf(
    DigFind("toy spade") { g -> toySpade(g) },
    DigFind("toy car") { g -> toyCar(g) },
    DigFind("toy block") { g -> toyBlock(g) },
)

/** The Beach's shells and a message in a bottle. */
internal val beachFinds = listOf(
    DigFind("scallop shell") { g -> scallop(g) },
    DigFind("spiral shell") { g -> spiralShell(g) },
    DigFind("message in a bottle") { g -> bottle(g) },
)

/** Martian ice and fossils. */
internal val marsFinds = listOf(
    DigFind("chunk of Martian ice") { g -> iceCrystal(g) },
    DigFind("ammonite fossil") { g -> ammonite(g) },
    DigFind("trilobite fossil") { g -> trilobite(g) },
)

private fun DrawScope.toySpade(g: SceneGrade) {
    rotate(-32f, Offset(50f, 55f)) {
        stick(g(0xFFE0A21C), 50f, 18f, 50f, 64f, 8f)
        stick(g(0xFFFFD04A), 49f, 18f, 49f, 62f, 5f)
        box(g(0xFFE0A21C), 38f, 10f, 62f, 20f, 5f)
        box(g(0xFFFFD04A), 39f, 10f, 61f, 17f, 4f)
        drawPath(spadeBlade, g(0xFF2F6FC8))
        drawPath(spadeBladeLit, g(0xFF4A92EE))
        oval(Color.White.copy(alpha = 0.45f), 43f, 66f, 3f, 7f)
    }
}

private val spadeBlade = Path().apply {
    moveTo(33f, 56f)
    lineTo(67f, 56f)
    quadraticBezierTo(70f, 84f, 50f, 96f)
    quadraticBezierTo(30f, 84f, 33f, 56f)
    close()
}
private val spadeBladeLit = Path().apply {
    moveTo(36f, 58f)
    lineTo(62f, 58f)
    quadraticBezierTo(63f, 80f, 48f, 90f)
    quadraticBezierTo(34f, 80f, 36f, 58f)
    close()
}

private fun DrawScope.toyCar(g: SceneGrade) {
    oval(Color.Black.copy(alpha = 0.18f), 50f, 86f, 34f, 4f)
    box(g(0xFF7A3FB8), 30f, 34f, 70f, 58f, 10f)
    box(g(0xFF9A5AD8), 31f, 34f, 68f, 54f, 9f)
    box(g(0xFFBFE6FA), 36f, 39f, 48f, 52f, 3f)
    box(g(0xFFBFE6FA), 52f, 39f, 64f, 52f, 3f)
    box(g(0xFF7A3FB8), 14f, 52f, 86f, 78f, 10f)
    box(g(0xFF9A5AD8), 15f, 52f, 85f, 72f, 9f)
    box(Color.White.copy(alpha = 0.35f), 20f, 55f, 52f, 59f, 2f)
    box(g(0xFFFFE27A), 80f, 59f, 86f, 66f, 2f)
    box(g(0xFFFF7A6A), 14f, 59f, 19f, 66f, 2f)
    for (x in floatArrayOf(31f, 69f)) {
