}

private fun DrawScope.toyBlock(g: SceneGrade) {
    drawPath(blockTop, g(0xFF7FD98F))
    drawPath(blockSide, g(0xFF2F8A4C))
    box(g(0xFF46B060), 22f, 38f, 68f, 86f, 5f)
    box(g(0xFF55C46E), 24f, 38f, 66f, 80f, 4f)
    translate(45f, 60f) { scale(14f, 14f, Offset.Zero) { drawPath(blockStar, g(0xFFFFD04A)) } }
}

private val blockTop = polygon(22f, 40f, 36f, 26f, 82f, 26f, 68f, 40f)
private val blockSide = polygon(66f, 40f, 82f, 26f, 82f, 72f, 66f, 86f)
private val blockStar = starPath(0.48f)

private fun DrawScope.scallop(g: SceneGrade) {
    val base = Offset(50f, 86f)
    val fan = Path().apply {
        moveTo(base.x, base.y)
        for (k in 0..12) {
            val a = PI + PI * k / 12
            val bump = if (k % 2 == 0) 40f else 37f
            lineTo(base.x + (cos(a) * bump).toFloat(), base.y + (sin(a) * bump * 1.05f).toFloat())
        }
        close()
    }
    drawPath(fan, g(0xFFE57F68))
    translate(0f, 1.5f) { scale(0.9f, 0.9f, base) { drawPath(fan, g(0xFFF6A58A)) } }
    for (k in 1..5) {
        val a = PI + PI * k / 6
        stick(g(0xFFE57F68), base.x, base.y - 4f, base.x + (cos(a) * 34f).toFloat(), base.y + (sin(a) * 35f).toFloat(), 2.2f)
    }
    box(g(0xFFE57F68), 38f, 80f, 62f, 92f, 4f)
    box(g(0xFFF6A58A), 40f, 80f, 60f, 89f, 3f)
    oval(Color.White.copy(alpha = 0.4f), 38f, 58f, 5f, 8f)
}

private fun DrawScope.spiralShell(g: SceneGrade) {
    rotate(-18f, Offset(50f, 58f)) {
        drawPath(shellBody, g(0xFFD9B48A))
        translate(1f, -1f) { scale(0.92f, 0.92f, Offset(52f, 56f)) { drawPath(shellBody, g(0xFFF4E3C8)) } }
        for (k in 0..3) {
            val y = 30f + k * 12f
            val half = 6f + k * 5f
            drawArc(g(0xFFC9925E), 20f, 140f, false, Offset(50f - half, y - 6f), Size(half * 2, 12f), style = Stroke(2.6f, cap = StrokeCap.Round))
        }
        oval(g(0xFFF2A9A0), 54f, 76f, 11f, 9f)
        oval(g(0xFFFFD0C4), 55f, 75f, 7f, 5.5f)
        oval(Color.White.copy(alpha = 0.45f), 42f, 50f, 3f, 9f)
    }
}

private val shellBody = Path().apply {
    moveTo(50f, 14f)
    quadraticBezierTo(74f, 50f, 72f, 74f)
    quadraticBezierTo(62f, 92f, 44f, 88f)
    quadraticBezierTo(28f, 80f, 30f, 62f)
    quadraticBezierTo(34f, 40f, 50f, 14f)
    close()
}

