private fun DrawScope.iceCrystal(g: SceneGrade) {
    oval(Color.Black.copy(alpha = 0.18f), 50f, 88f, 30f, 4f)
    val shade = g(0xFF7FBDE6)
    val ice = g(0xFFBFE8FF)
    val lit = g(0xFFEFFAFF)
    rotate(-22f, Offset(36f, 86f)) { crystal(30f, 86f, 9f, 40f, shade, ice, lit) }
    rotate(18f, Offset(66f, 86f)) { crystal(66f, 86f, 10f, 46f, shade, ice, lit) }
    crystal(50f, 88f, 12f, 66f, shade, ice, lit)
    dot(Color.White, 56f, 30f, 2.4f)
    stick(Color.White.copy(alpha = 0.8f), 56f, 24f, 56f, 36f, 1.2f)
    stick(Color.White.copy(alpha = 0.8f), 50f, 30f, 62f, 30f, 1.2f)
}

/** A six-sided ice prism [half] wide standing [height] tall on ([cx], [bottom]). */
private fun DrawScope.crystal(cx: Float, bottom: Float, half: Float, height: Float, shade: Color, ice: Color, lit: Color) {
    val top = bottom - height
    drawPath(polygon(cx - half, bottom, cx - half, top + half, cx, top, cx + half, top + half, cx + half, bottom), shade)
    drawPath(polygon(cx - half, bottom, cx - half, top + half, cx, top, cx, bottom), ice)
    drawPath(polygon(cx - half * 0.7f, bottom - 4f, cx - half * 0.7f, top + half + 2f, cx - half * 0.3f, top + half * 0.6f, cx - half * 0.3f, bottom - 4f), lit)
}

private fun DrawScope.ammonite(g: SceneGrade) {
    oval(g(0xFF8C7660), 50f, 58f, 37f, 33f)
    oval(g(0xFFB9A48E), 49f, 56f, 35f, 31f)
    val spiral = Path().apply {
        var first = true
        var a = 0.0
        while (a < 5.6 * PI) {
            val r = 3f + a.toFloat() * 1.55f
            val x = 49f + (cos(a) * r).toFloat()
            val y = 57f + (sin(a) * r * 0.92f).toFloat()
            if (first) moveTo(x, y) else lineTo(x, y)
            first = false
            a += 0.2
        }
    }
    drawPath(spiral, g(0xFF7E6A56), style = Stroke(3.2f, cap = StrokeCap.Round))
    for (k in 0 until 14) {
        val a = 2.2 * PI + k * 0.42
        val r = 3f + a.toFloat() * 1.55f
        val x = 49f + (cos(a) * r).toFloat()
        val y = 57f + (sin(a) * r * 0.92f).toFloat()
        stick(g(0xFF9C8670), x, y, 49f + (cos(a) * (r - 6f)).toFloat(), 57f + (sin(a) * (r - 6f) * 0.92f).toFloat(), 1.6f)
    }
    oval(Color.White.copy(alpha = 0.3f), 36f, 38f, 8f, 4f)
}

private fun DrawScope.trilobite(g: SceneGrade) {
    drawPath(slab, g(0xFF9E8268))
    translate(0f, -2f) { drawPath(slab, g(0xFFCBB08F)) }
    val print = g(0xFF7A5E46)
    val body = g(0xFF9A7C60)
    oval(print, 50f, 38f, 18f, 10f)
    oval(body, 50f, 39f, 15f, 8f)
    for (k in 0 until 6) {
        val y = 50f + k * 5.5f
        val half = 16f - k * 1.8f
        stick(print, 50f - half, y, 50f + half, y, 4.2f)
        stick(body, 50f - half + 1f, y - 0.5f, 50f + half - 1f, y - 0.5f, 2.6f)
    }
    stick(print, 50f, 34f, 50f, 82f, 3f)
    dot(print, 44f, 37f, 1.8f)
    dot(print, 56f, 37f, 1.8f)
}

private val slab = polygon(16f, 30f, 40f, 18f, 80f, 22f, 88f, 60f, 76f, 90f, 30f, 92f, 12f, 66f)
