import io.colorsand.core.Board

// How the paw holds a tube, in tube widths: it lifts the tube by HOLD_LIFT, and grips it GRIP_DOWN below the
// middle of its mouth and GRIP_IN towards the arm. The paw comes from PAW_TRAVEL further out, and the arm rises
// by ARM_RISE degrees on its way to the screen edge when there is no row of tubes above to cover.
internal const val HOLD_LIFT = 0.68f
internal const val GRIP_DOWN = 0.4f
internal const val GRIP_IN = 0.06f
internal const val PAW_TRAVEL = 2.5f
internal const val ARM_RISE = 14f

internal const val GRAB_MILLIS = 260
internal const val RELEASE_MILLIS = 220
internal const val HANDOVER_MILLIS = 140

/** The side of the screen the paw comes from for the tube at [src]: the nearer one, -1 for left, 1 for right. */
internal fun pawSide(src: Rect, boardWidth: Float): Int = if (src.center.x < boardWidth / 2) -1 else 1

/**
 * How many degrees the arm rises on its way out. It stays level when there is a row of tubes above [src] (one of
 * [others] ends above its top), so it runs through the gap between the rows instead of across their sand.
 */
internal fun armRise(src: Rect, others: Iterable<Rect>): Float =
    if (others.any { it != src && it.bottom <= src.top + 1f }) 0f else ARM_RISE

/**
 * The arm's thickness in tube widths. A level arm runs between two rows of tubes, so a big animal's is slimmed
 * down to fit the gap.
 */
internal fun armWidth(kind: PawKind, rise: Float): Float = if (rise == 0f) minOf(kind.arm, LEVEL_ARM) else kind.arm

internal const val LEVEL_ARM = 0.44f

/** Where the paw holds a tube whose mouth's middle is at [pivot], tilted [angle] degrees and scaled by [scale]. */
internal fun gripPoint(pivot: Offset, w: Float, side: Int, angle: Float = 0f, scale: Float = 1f): Offset =
    pivot + (Offset(side * GRIP_IN * w, GRIP_DOWN * w) * scale).rotated(angle)

/** The gap between two rows of tubes, in tube widths (see [BoardView]). */
internal const val ROW_GAP = 0.7f

/**
 * How far below the arm the paw sits, in tube widths, holding from [side]. Under a row of tubes (a level arm,
 * [rise] 0) a big paw held at the arm would reach up into the sand of the tube above, so it slides down the held
 * tube until it clears that tube with a little room to spare.
 */
internal fun pawDrop(kind: PawKind, side: Int, rise: Float): Float {
    if (rise != 0f) return 0f
    val bounds = pawBounds(kind)
    // Turned to hold from the left, the paw's -x side faces up; from the right, its +x side.
    val up = if (side < 0) -bounds.left else bounds.right
    return maxOf(0f, HOLD_LIFT - GRIP_DOWN + up - (ROW_GAP - 0.04f))
}

/** Where the paw's middle is for an arm at [grip], on a tube tilted [angle] degrees and scaled by [scale]. */
internal fun pawCenter(grip: Offset, w: Float, drop: Float, angle: Float = 0f, scale: Float = 1f): Offset =
    grip + Offset(0f, drop * w * scale).rotated(angle)

/** How the paw is turned: toes across the tube, away from the arm, tilting with the tube. */
internal fun pawRotation(side: Int, angle: Float = 0f): Float = -side * 90f + angle

// The grab, as a function of how far it is (0 = paw away, tube down; 1 = tube held up). The paw arrives first,
// then lifts the tube; letting go plays it backwards.

/** How much of [HOLD_LIFT] the tube is lifted. */
internal fun holdLift(r: Float): Float = FastOutSlowInEasing.transform(phase(r, 0.55f, 1f))

/** How much of [PAW_TRAVEL] the paw still has to come in. */
internal fun holdAway(r: Float): Float = 1 - FastOutSlowInEasing.transform(phase(r, 0f, 0.55f))

internal fun holdAlpha(r: Float): Float = phase(r, 0f, 0.35f)

/** What the paw does when the selected tube changes: let go of the tube it holds (or not), then take [grab]. */
internal enum class LetGo { KEEP, PUT_DOWN, DROP }

internal data class HoldPlan(val letGo: LetGo, val grab: Int?)

/**
 * The plan for [held] (the tube in the paw, or null; [heldShown] if it is still on the board as it was when
 * grabbed) when the selection becomes [selected]. A tube that changed under the paw (a pour, undo, restart or a
 * new level) is dropped at once; otherwise it is put down. A new selection is grabbed after letting go.
 */
internal fun planHold(held: Int?, heldShown: Boolean, selected: Int?): HoldPlan {
    val letGo = when {
        held == null -> LetGo.KEEP
        !heldShown -> LetGo.DROP
        held == selected -> LetGo.KEEP
        else -> LetGo.PUT_DOWN
    }
    return HoldPlan(letGo, selected)
}

/**
 * The paw holding the selected tube while the player picks a target. It follows [GameController.selected]: it
 * comes in from the side and lifts the tube, and puts it back when the selection goes. A pour takes the tube over
 * from it (see [PourAnimation]).
 */
@Stable
class PawHold(private val game: GameController) {
    private val reach = Animatable(0f)

    /** The tube in the paw, even while it is being put down; null once the paw has gone. */
    var tube: Int? by mutableStateOf(null)
        private set
    // Compared by identity: a board can come back with the same contents (undo, or pouring back and forth), and
    // the default structural policy would then keep the old board here, which `shown` never matches again.
    private var boardAtGrab: Board? by mutableStateOf(null, referentialEqualityPolicy())

    /** The held tube, if the board is still the one it was taken from (a pour or undo hands it back at once). */
    val shown: Int? get() = tube?.takeIf { game.board === boardAtGrab }

    /** How far the grab is (see [holdLift]). Read it while drawing. */
    internal val progress: Float get() = reach.value

    /** How far the paw had got with tube [index], for a pour that takes it over. */
    internal fun grabbed(index: Int): Float = if (tube == index) reach.value else 0f

    /** Puts tube [index] of the current board in the paw (the grab then lifts it). */
    internal fun take(index: Int) {
        tube = index
        boardAtGrab = game.board
    }

    internal suspend fun follow(selected: Int?) {
        val plan = planHold(tube, tube != null && shown == tube, selected)
        when (plan.letGo) {
            LetGo.KEEP -> Unit
            LetGo.DROP -> {
                reach.snapTo(0f)
                tube = null
            }
            LetGo.PUT_DOWN -> {
                val millis = if (plan.grab != null) HANDOVER_MILLIS else RELEASE_MILLIS
                reach.animateTo(0f, tween((millis * reach.value).toInt(), easing = LinearEasing))
                tube = null
            }
        }
        val grab = plan.grab ?: return
        if (tube == null) take(grab)
        reach.animateTo(1f, tween((GRAB_MILLIS * (1 - reach.value)).toInt(), easing = LinearEasing))
    }
}

@Composable
fun rememberPawHold(game: GameController): PawHold = remember(game) { PawHold(game) }

/** Draws the held tube, lifted, with the paw and its arm. A tap on the tube counts as a tap on it in the board. */
@Composable
internal fun BoxScope.HoldOverlay(hold: PawHold, pours: PourAnimation, board: Board, selected: Int?, tubeWidth: Dp, onTap: (Int) -> Unit) {
    val index = hold.shown ?: return
    if (index !in board.tubes.indices) return
    val src = pours.tubeBounds(index) ?: return
    val kind = LocalPawKind.current
    val look = pawLook(kind, LocalPalette.current)
    val w = src.width
    val side = pawSide(src, pours.boardWidth)
    val rise = armRise(src, board.tubes.indices.mapNotNull(pours::tubeBounds))
    val edge = pours.screenEdge(side)
    val drop = pawDrop(kind, side, rise)
    fun pivot() = Offset(src.center.x, src.top - HOLD_LIFT * w * holdLift(hold.progress))

    Box(Modifier.matchParentSize()) {
        TubeView(
            tube = board.tubes[index],
            highlight = if (selected == index) TubeHighlight.SELECTED else TubeHighlight.NONE,
            width = tubeWidth,
            onTap = { onTap(index) },
            modifier = Modifier.graphicsLayer {
                translationX = src.left
                translationY = pivot().y
            },
        )
        Canvas(Modifier.matchParentSize()) {
            val r = hold.progress
            val grip = gripPoint(pivot(), w, side) + Offset(side * PAW_TRAVEL * w * holdAway(r), 0f)
            withAlpha(holdAlpha(r)) {
                drawForearm(kind, look, grip, w, armWidth(kind, rise) * w, side, rise, edge)
                drawPaw(kind, look, pawCenter(grip, w, drop), w, pawRotation(side))
            }
        }
    }
}
