// The drawing of Catch the grains: the scenery, the keepsake standing by, the falling grains, the container with
// its layered pile, the little puffs as grains drop in and the shimmer once it is full. Sizes are in [CatchLayout]
// units (a hundredth of the field's smaller side), [t] is the round's time in seconds.

private const val TAU = (2 * PI).toFloat()

/** How long the full container shimmers before the round ends, in seconds. */
internal const val SHIMMER_S = 2.2f

/** A grain that just dropped into the container at [x] (0 to 1) at [at] seconds, for its little puff. */
internal class Splash(val x: Float, val at: Float, val color: SandColor)

/** The sky, the far band, the sand underfoot and the scene's own touches, behind everything else. */
internal fun DrawScope.drawCatchScenery(look: CatchLook, layout: CatchLayout, t: Float) {
    val f = layout.field
    val u = layout.unit
    drawRect(Brush.verticalGradient(listOf(look.skyTop, look.skyBottom), f.top, layout.y(0.8f)), f.topLeft, f.size)
    val groundTop = layout.y(GrainCatch.GROUND - 0.05f)
    when (look.scene) {
        CatchScene.BEACH -> {
            val sun = layout.at(0.82f, 0.13f)
            drawGlow(sun, 22f * u, Color(0xFFFFF4C2).copy(alpha = 0.8f))
            drawCircle(Color(0xFFFFE27A), 7.5f * u, sun)
            for (k in 0 until 2) cloud(layout, wrap(0.18f + k * 0.5f + t * 0.006f) * 1.3f - 0.15f, 0.12f + k * 0.13f, (1f - k * 0.25f) * u)
            // The sea, with a foamy edge where it meets the beach.
            val seaTop = layout.y(0.62f)
            drawRect(Brush.verticalGradient(listOf(look.farLight, look.far), seaTop, groundTop), Offset(f.left, seaTop), Size(f.width, groundTop - seaTop + 2f))
            for (k in 0 until 3) {
                val y = seaTop + (groundTop - seaTop) * (0.25f + 0.25f * k)
                wave(layout, y, 1.2f * u, 8f + k * 3, t * (0.3f + 0.1f * k), Color.White.copy(alpha = 0.35f), 0.7f * u)
            }
            sandBank(look, layout, groundTop, t)
            wave(layout, groundTop + 0.6f * u, 1.3f * u, 6f, t * 0.25f, Color.White.copy(alpha = 0.85f), 1.4f * u)
            // The breeze: soft streaks blowing to the right.
            for (k in 0 until 4) {
                val p = wrap(t * 0.09f + k * 0.27f)
                val x = -0.25f + p * 1.5f
                val y = 0.2f + 0.14f * k
                breezeStreak(layout, x, y, u, Color.White.copy(alpha = 0.55f * sin(p * PI.toFloat())))
            }
        }
        CatchScene.DESERT -> {
            val sun = layout.at(0.2f, 0.16f)
            drawGlow(sun, 30f * u, Color(0xFFFFF6D6).copy(alpha = 0.9f))
            drawCircle(Color(0xFFFFF3C8), 9f * u, sun)
            // Far dunes, then a tall dune at the right whose crest the wind blows the sand off.
            dune(layout, 0.6f, listOf(0f to 0.62f, 0.3f to 0.54f, 0.6f to 0.63f, 1f to 0.56f), lerp(look.far, look.skyBottom, 0.35f))
            dune(layout, 0.7f, listOf(0f to 0.7f, 0.45f to 0.64f, 0.75f to 0.7f, 1f to 0.68f), look.far)
            // The near dune: a long windward slope up to a crest, the steep slip face beyond it in shade.
            dune(layout, 0.55f, listOf(0.38f to 0.9f, 0.86f to 0.5f, 1.02f to 0.47f), look.farLight)
            dune(layout, 0.45f, listOf(0.86f to 0.5f, 0.96f to 0.66f, 1.04f to 0.8f), lerp(look.far, look.farLight, 0.35f))
            // Sand streaming off the crest to the left.
            for (k in 0 until 18) {
                val p = wrap(t * 0.3f + k / 18f)
                val x = 0.86f - p * 0.45f
                val y = 0.49f - p * 0.1f + sin(p * 6f + k) * 0.012f
                drawCircle(look.groundShade.copy(alpha = 0.45f * (1f - p)), (0.25f + 0.25f * noise(k)) * u, layout.at(x, y))
            }
            sandBank(look, layout, groundTop, t)
            for (k in 0 until 3) {
                val y = groundTop + (f.bottom - groundTop) * (0.3f + 0.22f * k)
                wave(layout, y, 0.7f * u, 10f, 0f, look.groundShade.copy(alpha = 0.35f), 0.5f * u)
            }
            for (k in 0 until 4) {
                val p = wrap(t * 0.07f + k * 0.25f)
                breezeStreak(layout, 1.2f - p * 1.5f, 0.24f + 0.12f * k, u, Color.White.copy(alpha = 0.45f * sin(p * PI.toFloat())), mirrored = true)
            }
        }
        CatchScene.MARS -> {
            for (k in 0 until 26) {
                val p = layout.at(noise(k * 3 + 1), noise(k * 5 + 2) * 0.55f)
                val twinkle = 0.45f + 0.35f * sin(t * (0.6f + noise(k) * 0.8f) + k)
                drawCircle(Color.White.copy(alpha = twinkle * (1f - noise(k * 5 + 2) * 0.8f)), (0.25f + 0.35f * noise(k * 7)) * u, p)
            }
            // Phobos and Deimos.
            val phobos = layout.at(0.76f, 0.15f)
            drawGlow(phobos, 9f * u, Color(0xFFFFE2C8).copy(alpha = 0.35f))
            drawCircle(Color(0xFFD9C2B0), 3.6f * u, phobos)
            drawCircle(Color(0xFFB59A88), 1f * u, phobos + Offset(1f * u, 0.6f * u))
            drawCircle(Color(0xFFE6D6C6), 1.8f * u, layout.at(0.3f, 0.09f))
            dune(layout, 0.6f, listOf(0f to 0.66f, 0.2f to 0.58f, 0.42f to 0.66f, 0.7f to 0.55f, 1f to 0.64f), lerp(look.far, look.skyTop, 0.35f))
            dune(layout, 0.6f, listOf(0f to 0.76f, 0.35f to 0.7f, 0.65f to 0.77f, 1f to 0.7f), look.far)
            sandBank(look, layout, groundTop, t)
            // Craters and pebbles.
            for ((x, y, r) in listOf(Triple(0.3f, 0.965f, 4.5f), Triple(0.72f, 0.95f, 3f), Triple(0.92f, 0.98f, 5f))) {
                val c = layout.at(x, y)
                drawOval(look.groundShade, c - Offset(r * u, r * 0.32f * u), Size(2 * r * u, 0.64f * r * u))
                drawOval(look.groundLight.copy(alpha = 0.6f), c - Offset(r * u, r * 0.32f * u) + Offset(0f, 0.5f * u), Size(2 * r * u, 0.3f * r * u))
            }
            // A slow haze of dust drifting through.
            for (k in 0 until 10) {
                val p = wrap(t * 0.02f + noise(k * 11))
                val c = layout.at(p * 1.2f - 0.1f, 0.25f + 0.5f * noise(k * 13))
                drawGlow(c, (3f + 3f * noise(k)) * u, look.ground.copy(alpha = 0.18f))
            }
        }
    }
}

/** The keepsake standing in the sand at the side, [height] field heights tall, at scene clock [sceneT]. */
internal fun DrawScope.drawCatchKeepsake(look: CatchLook, layout: CatchLayout, grade: SceneGrade, sceneT: Float) {
    val x = if (look.scene == CatchScene.BEACH) 0.83f else 0.15f
    val height = when (look.scene) {
        CatchScene.BEACH -> 0.36f
        CatchScene.DESERT -> 0.3f
        CatchScene.MARS -> 0.26f
    }
    val size = minOf(layout.field.height * height, layout.field.width * 0.34f)
    val k = size / 100f
    val base = layout.y(GrainCatch.GROUND + 0.02f)
    translate(layout.x(x) - 50f * k, base - 96f * k) {
        scale(k, k, Offset.Zero) { drawKeepsake(look.arena, look.stage, sceneT, grade) }
    }
}

/** The grains that fell into the sand, fading as they settle. */
internal fun DrawScope.drawLanded(layout: CatchLayout, round: GrainCatch, sand: (SandColor) -> Color) {
    val u = layout.unit
    for (l in round.landed) {
        val a = (1f - (round.time - l.at) / GrainCatch.SETTLE).coerceIn(0f, 1f)
        val c = layout.at(l.x, GrainCatch.GROUND + 0.012f + 0.015f * noise((l.x * 997).toInt()))
        drawOval(sand(l.color).copy(alpha = a), c - Offset(1.1f * u, 0.45f * u), Size(2.2f * u, 0.9f * u))
    }
}

/** Every grain in the air: a pinch of sand with a glint, a glow of dust on Mars, a little trail in the desert wind. */
internal fun DrawScope.drawGrains(look: CatchLook, layout: CatchLayout, round: GrainCatch, sand: (SandColor) -> Color) {
    val u = layout.unit
    val r = 0.95f * u
    for (g in round.grains) {
        val y = round.y(g)
        if (y < -0.05f) continue
        val c = layout.at(round.x(g), y)
        val color = sand(g.color)
        val dark = lerp(color, Color.Black, 0.28f)
        if (look.scene == CatchScene.MARS) drawGlow(c, r * 8f, color.copy(alpha = 0.35f))
        // A wisp of finer sand trailing behind, where the grain just was.
        for (k in 1..3) {
            val back = round.time - k * (if (look.scene == CatchScene.MARS) 0.16f else 0.07f)
            val p = layout.at(round.x(g, back), round.y(g, back))
            drawCircle(color.copy(alpha = 0.42f - k * 0.11f), r * (0.75f - k * 0.12f), p)
        }
        // A loose pinch of grains, tumbling slowly as it falls.
        val turn = round.time * (if (look.scene == CatchScene.MARS) 0.8f else 2.2f) + g.id
        for (k in 0 until 5) {
            val a = turn + k * TAU / 5 + noise(g.id * 5 + k)
            val d = if (k == 0) 0f else r * (1.1f + 0.5f * noise(g.id * 7 + k))
            val p = c + Offset(kotlin.math.cos(a) * d, sin(a) * d)
            val rr = r * (if (k == 0) 1.25f else 0.7f + 0.3f * noise(g.id * 3 + k))
            drawCircle(dark, rr, p + Offset(0f, rr * 0.25f))
            drawCircle(color, rr, p)
            drawCircle(Color.White.copy(alpha = 0.55f), rr * 0.35f, p - Offset(rr * 0.3f, rr * 0.3f))
        }
    }
}

/**
 * The container at [bin] with its pile of caught sand in layers, the puffs of grains just dropped in, and once it
 * is full a hop, a glow and sparkles ([shimmer] 0 to 1, or null before it is full).
 */
internal fun DrawScope.drawContainer(
    look: CatchLook,
    layout: CatchLayout,
    round: GrainCatch,
    splashes: List<Splash>,
    sand: (SandColor) -> Color,
    shimmer: Float?,
) {
    val u = layout.unit
    val base = layout.container(round.bin)
    val hop = shimmer?.let { sin((it * 2f).coerceAtMost(1f) * PI.toFloat()) * base.height * 0.12f } ?: 0f
    val r = base.translate(0f, -hop)
    // A soft shadow on the sand, smaller while it hops.
    val shadowW = r.width * (1f - hop / base.height * 0.8f)
    drawOval(Color.Black.copy(alpha = 0.2f), Offset(r.center.x - shadowW * 0.52f, base.bottom - 1.2f * u), Size(shadowW * 1.04f, 2.6f * u))
    if (shimmer != null) drawGlow(r.center, r.width * (1.1f + 0.4f * shimmer), Color(0xFFFFF2B0).copy(alpha = 0.75f * (1f - shimmer * 0.6f)))
    val inside = interior(look.catcher, r)
    // Behind the pile: the bucket's handle, the bag's straps, the inside of the glass.
    when (look.catcher) {
        Catcher.BUCKET -> {
            val handle = Path().apply {
                moveTo(r.left + r.width * 0.06f, r.top + r.height * 0.08f)
                cubicTo(r.left + r.width * 0.1f, r.top - r.height * 0.42f, r.right - r.width * 0.1f, r.top - r.height * 0.42f, r.right - r.width * 0.06f, r.top + r.height * 0.08f)
            }
            drawPath(handle, look.bodyDark, style = Stroke(1.3f * u, cap = StrokeCap.Round))
            drawPath(inside, look.bodyDark.copy(alpha = 0.18f))
        }
        Catcher.SADDLE_BAG -> {
            // The leather strap it hangs from on the camel, looped over the top.
            val strap = Path().apply {
                moveTo(r.left + r.width * 0.16f, r.top + r.height * 0.05f)
                cubicTo(r.left + r.width * 0.2f, r.top - r.height * 0.3f, r.right - r.width * 0.2f, r.top - r.height * 0.3f, r.right - r.width * 0.16f, r.top + r.height * 0.05f)
            }
            drawPath(strap, look.bodyDark, style = Stroke(2.2f * u, cap = StrokeCap.Round))
            drawPath(strap, look.accent.copy(alpha = 0.5f), style = Stroke(0.5f * u, cap = StrokeCap.Round))
            drawPath(inside, Color(0xFF3A2414).copy(alpha = 0.22f))
        }
        Catcher.JAR -> drawPath(inside, look.body.copy(alpha = 0.22f))
    }
    clipPath(inside) { drawPile(look, round, inside.getBounds(), sand, shimmer, u) }
    for (s in splashes) splash(layout, s, round, inside.getBounds(), sand)
    when (look.catcher) {
        Catcher.BUCKET -> bucketFront(look, r, inside, u)
        Catcher.SADDLE_BAG -> bagFront(look, r, inside, u)
        Catcher.JAR -> jarFront(look, r, inside, u, shimmer)
    }
    if (shimmer != null) {
        for (k in 0 until 9) {
            val p = wrap(shimmer * 1.6f + k / 9f)
            val x = r.left + r.width * (noise(k * 17) * 1.3f - 0.15f)
            val y = r.bottom - r.height * (0.2f + p * 1.3f)
            val a = sin(p * PI.toFloat()) * (1f - shimmer * 0.5f)
            drawSparkle(Offset(x, y), (1.6f + 1.4f * noise(k)) * u, (if (k % 2 == 0) Color(0xFFFFE27A) else Color.White).copy(alpha = a))
        }
    }
}

/** The shape the sand piles up in, inside [r]. */
private fun interior(catcher: Catcher, r: Rect): Path = Path().apply {
    when (catcher) {
        Catcher.BUCKET -> {
            val top = r.top + r.height * 0.1f
            val bottom = r.bottom - r.height * 0.08f
            moveTo(r.left + r.width * 0.05f, top)
            lineTo(r.right - r.width * 0.05f, top)
            lineTo(r.right - r.width * 0.16f, bottom)
            lineTo(r.left + r.width * 0.16f, bottom)
            close()
        }
        Catcher.SADDLE_BAG -> addRoundRect(
            RoundRect(
                r.left + r.width * 0.06f, r.top + r.height * 0.16f, r.right - r.width * 0.06f, r.bottom - r.height * 0.05f,
                topLeftCornerRadius = CornerRadius(r.width * 0.03f),
                topRightCornerRadius = CornerRadius(r.width * 0.03f),
                bottomRightCornerRadius = CornerRadius(r.width * 0.3f),
                bottomLeftCornerRadius = CornerRadius(r.width * 0.3f),
            ),
        )
        Catcher.JAR -> addRoundRect(
            RoundRect(r.left + r.width * 0.05f, r.top + r.height * 0.14f, r.right - r.width * 0.05f, r.bottom - r.height * 0.04f, CornerRadius(r.width * 0.16f)),
        )
    }
}

/**
 * The caught sand, in [box]: layer on layer from the bottom, each with a softly wavy top, the top one heaped a
 * little in the middle, a speck for every grain; while it shimmers a band of light sweeps across.
 */
private fun DrawScope.drawPile(look: CatchLook, round: GrainCatch, box: Rect, sand: (SandColor) -> Color, shimmer: Float?, u: Float) {
    val layers = round.layers
    if (layers.isEmpty()) return
    val total = box.height * 0.96f
    val levels = FloatArray(layers.size)
    var count = 0
    for ((i, layer) in layers.withIndex()) {
        count += layer.second
        levels[i] = box.bottom - total * count / round.capacity
    }
    val heap = box.height * 0.05f * round.fill
    fun line(i: Int, x: Float): Float {
        val k = (x - box.left) / box.width
        val wave = sin(k * 5.5f + i * 1.9f) * box.height * 0.018f + sin(k * 11f + i * 0.7f) * box.height * 0.007f
        val mound = if (i == layers.lastIndex) heap * (1f - (2 * k - 1) * (2 * k - 1)) else 0f
        return levels[i] + wave - mound
    }
    // Top layer first, each lower one painted over it up to its own line.
    for (i in layers.indices.reversed()) {
        val color = sand(layers[i].first)
        val path = Path().apply {
            moveTo(box.left - 2f, box.bottom + 2f)
            val steps = 16
            for (s in 0..steps) {
                val x = box.left + box.width * s / steps
                lineTo(x, line(i, x))
            }
            lineTo(box.right + 2f, box.bottom + 2f)
            close()
        }
        val top = levels[i] - box.height * 0.06f
        drawPath(path, Brush.verticalGradient(listOf(lerp(color, Color.White, 0.18f), color, lerp(color, Color.Black, 0.12f)), top, box.bottom))
    }
    // A speck in every grain's place, so the layers read as sand.
    var n = 0
    for ((i, layer) in layers.withIndex()) {
        val below = if (i == 0) box.bottom else levels[i - 1]
        val color = sand(layer.first)
        repeat(layer.second * 2) {
            val x = box.left + box.width * (0.06f + 0.88f * noise(n * 7 + 3))
            val y = below - (below - levels[i]) * (0.15f + 0.7f * noise(n * 13 + 5))
            val light = noise(n * 3) > 0.5f
            drawCircle(if (light) lerp(color, Color.White, 0.45f) else lerp(color, Color.Black, 0.25f), (0.35f + 0.3f * noise(n)) * u, Offset(x, y))
            n++
        }
    }
    if (shimmer != null) {
        val x = box.left - box.width * 0.4f + box.width * 1.8f * shimmer
        drawRect(
            Brush.linearGradient(
                listOf(Color.White.copy(alpha = 0f), Color.White.copy(alpha = 0.5f), Color.White.copy(alpha = 0f)),
                Offset(x - box.width * 0.25f, box.top), Offset(x + box.width * 0.25f, box.bottom),
            ),
            box.topLeft, box.size,
        )
    }
}

/** A grain landing on the pile: a few grains bouncing up and settling back. */
private fun DrawScope.splash(layout: CatchLayout, s: Splash, round: GrainCatch, box: Rect, sand: (SandColor) -> Color) {
    val p = (round.time - s.at) / SPLASH_S
    if (p !in 0f..1f) return
    val u = layout.unit
    val surface = box.bottom - box.height * 0.96f * round.fill
    val x = layout.x(s.x).coerceIn(box.left + 2f * u, box.right - 2f * u)
    val color = sand(s.color)
    for (k in 0 until 4) {
        val dx = (k - 1.5f) * 1.6f * u * p
        val dy = sin(p * PI.toFloat()) * (2.2f + noise(k + s.at.toInt()) * 1.5f) * u
        drawCircle(color.copy(alpha = 1f - p * 0.6f), 0.7f * u, Offset(x + dx, surface - dy))
    }
}

/** How long a grain's puff lasts, in seconds. */
internal const val SPLASH_S = 0.35f

/** A see-through plastic bucket with a thick rim, a solid base and a star sticker. */
private fun DrawScope.bucketFront(look: CatchLook, r: Rect, inside: Path, u: Float) {
    val body = Path().apply {
        moveTo(r.left + r.width * 0.02f, r.top + r.height * 0.06f)
        lineTo(r.right - r.width * 0.02f, r.top + r.height * 0.06f)
        lineTo(r.right - r.width * 0.13f, r.bottom)
        lineTo(r.left + r.width * 0.13f, r.bottom)
        close()
    }
    drawPath(body, look.body.copy(alpha = 0.22f))
    drawPath(body, look.bodyDark.copy(alpha = 0.55f), style = Stroke(0.9f * u))
    // The base and the rim, solid plastic.
    clipPath(body) {
        drawRect(look.body, Offset(r.left, r.bottom - r.height * 0.1f), Size(r.width, r.height * 0.1f))
        drawRect(look.bodyDark.copy(alpha = 0.4f), Offset(r.left, r.bottom - r.height * 0.1f), Size(r.width, 0.5f * u))
    }
    drawRoundRect(look.bodyDark, Offset(r.left - 0.5f * u, r.top + 0.8f * u), Size(r.width + u, r.height * 0.11f), CornerRadius(r.height * 0.05f))
    drawRoundRect(look.body, Offset(r.left - 0.5f * u, r.top), Size(r.width + u, r.height * 0.1f), CornerRadius(r.height * 0.05f))
    drawRoundRect(look.bodyLight.copy(alpha = 0.8f), Offset(r.left + r.width * 0.1f, r.top + r.height * 0.02f), Size(r.width * 0.4f, r.height * 0.025f), CornerRadius(r.height * 0.02f))
    // The shine down the side.
    drawLine(Color.White.copy(alpha = 0.45f), Offset(r.left + r.width * 0.13f, r.top + r.height * 0.2f), Offset(r.left + r.width * 0.2f, r.bottom - r.height * 0.18f), 1.3f * u, StrokeCap.Round)
    // A starfish sticker.
    val c = Offset(r.right - r.width * 0.3f, r.top + r.height * 0.32f)
    translate(c.x, c.y) {
        scale(r.width * 0.075f, r.width * 0.075f, Offset.Zero) {
            drawPath(starPath(0.45f), look.accent.copy(alpha = 0.9f))
        }
    }
}

/** A camel's saddle bag: a kilim flap at the top, a rope net to see the sand through, leather seams and tassels. */
private fun DrawScope.bagFront(look: CatchLook, r: Rect, inside: Path, u: Float) {
    val box = inside.getBounds()
    // The rope net over the sand.
    clipPath(inside) {
        val step = box.width / 3.5f
        val rope = look.accent.copy(alpha = 0.55f)
        var x = box.left - box.height
        while (x < box.right + box.height) {
            drawLine(rope, Offset(x, box.top), Offset(x + box.height, box.bottom), 0.5f * u)
            drawLine(rope, Offset(x + box.height, box.top), Offset(x, box.bottom), 0.5f * u)
            x += step
        }
    }
    drawPath(inside, look.bodyDark, style = Stroke(1.8f * u))
    // The flap: red kilim with a gold zigzag, folded over the mouth.
    val flap = Rect(r.left, r.top, r.right, r.top + r.height * 0.2f)
    drawRoundRect(look.bodyDark, flap.topLeft + Offset(0f, 0.8f * u), flap.size, CornerRadius(1.6f * u))
    drawRoundRect(look.body, flap.topLeft, flap.size, CornerRadius(1.6f * u))
    val zig = Path().apply {
        val y0 = flap.top + flap.height * 0.35f
        val y1 = flap.top + flap.height * 0.7f
        val n = 8
        moveTo(flap.left + 1f * u, y1)
        for (k in 1..n) lineTo(flap.left + 1f * u + (flap.width - 2f * u) * k / n, if (k % 2 == 1) y0 else y1)
    }
    drawPath(zig, look.accent, style = Stroke(0.9f * u))
    drawRoundRect(look.bodyLight.copy(alpha = 0.6f), flap.topLeft + Offset(flap.width * 0.08f, 0.5f * u), Size(flap.width * 0.4f, 0.7f * u), CornerRadius(0.4f * u))
    // Tassels at the bottom corners.
    for (side in listOf(0.14f, 0.86f)) {
        val x = r.left + r.width * side
        val y = r.bottom - r.height * 0.12f
        drawLine(look.accent, Offset(x, y), Offset(x, y + r.height * 0.14f), 1.4f * u, StrokeCap.Round)
        drawCircle(look.body, 1.3f * u, Offset(x, y))
    }
}

/** A glass jar with a metal screw ring; once [shimmer] begins its lid drops on. */
private fun DrawScope.jarFront(look: CatchLook, r: Rect, inside: Path, u: Float, shimmer: Float?) {
    val glass = RoundRect(r.left, r.top + r.height * 0.1f, r.right, r.bottom, CornerRadius(r.width * 0.18f))
    val path = Path().apply { addRoundRect(glass) }
    drawPath(path, look.body.copy(alpha = 0.18f))
    drawPath(path, Color.White.copy(alpha = 0.75f), style = Stroke(1.1f * u))
    drawLine(Color.White.copy(alpha = 0.6f), Offset(r.left + r.width * 0.14f, r.top + r.height * 0.3f), Offset(r.left + r.width * 0.14f, r.bottom - r.height * 0.22f), 1.6f * u, StrokeCap.Round)
    drawLine(Color.White.copy(alpha = 0.35f), Offset(r.right - r.width * 0.13f, r.top + r.height * 0.36f), Offset(r.right - r.width * 0.13f, r.top + r.height * 0.5f), 1f * u, StrokeCap.Round)
    // The screw ring around the neck.
    val ring = Rect(r.left + r.width * 0.06f, r.top, r.right - r.width * 0.06f, r.top + r.height * 0.13f)
    drawRoundRect(look.bodyDark, ring.topLeft + Offset(0f, 0.6f * u), ring.size, CornerRadius(1.2f * u))
    drawRoundRect(look.accent, ring.topLeft, ring.size, CornerRadius(1.2f * u))
    for (k in 1..5) {
        val x = ring.left + ring.width * k / 6f
        drawLine(look.bodyDark.copy(alpha = 0.5f), Offset(x, ring.top + 0.6f * u), Offset(x, ring.bottom - 0.6f * u), 0.5f * u)
    }
    drawRoundRect(Color.White.copy(alpha = 0.6f), ring.topLeft + Offset(ring.width * 0.08f, 0.5f * u), Size(ring.width * 0.35f, 0.6f * u), CornerRadius(0.3f * u))
    if (shimmer != null) {
        // The lid drops on, with a little bounce.
        val p = (shimmer * 3f).coerceAtMost(1f)
        val drop = (1f - openCurve(p)) * r.height * 0.6f
        val lid = Rect(ring.left - 0.6f * u, ring.top - r.height * 0.09f - drop, ring.right + 0.6f * u, ring.top + r.height * 0.03f - drop)
        drawRoundRect(look.bodyDark, lid.topLeft + Offset(0f, 0.6f * u), lid.size, CornerRadius(1.4f * u))
        drawRoundRect(Color(0xFFE8494E), lid.topLeft, lid.size, CornerRadius(1.4f * u))
        drawRoundRect(Color.White.copy(alpha = 0.45f), lid.topLeft + Offset(lid.width * 0.1f, 0.5f * u), Size(lid.width * 0.4f, 0.7f * u), CornerRadius(0.3f * u))
    }
}

/** The near sand: a soft, gently wavy bank from [top] down to the bottom of the field. */
private fun DrawScope.sandBank(look: CatchLook, layout: CatchLayout, top: Float, t: Float) {
    val f = layout.field
    val u = layout.unit
    val bank = Path().apply {
        moveTo(f.left, f.bottom)
        val steps = 12
        for (s in 0..steps) {
            val x = f.left + f.width * s / steps
            lineTo(x, top + sin(s * 0.9f) * 0.8f * u)
        }
        lineTo(f.right, f.bottom)
        close()
    }
    drawPath(bank, Brush.verticalGradient(listOf(look.groundLight, look.ground, look.groundShade), top, f.bottom))
}

/** A ridge of dunes, [points] (across, down) joined by smooth curves, filled down to the bottom of the field. */
private fun DrawScope.dune(layout: CatchLayout, smooth: Float, points: List<Pair<Float, Float>>, color: Color) {
    val f = layout.field
    val path = Path().apply {
        moveTo(layout.x(points.first().first), f.bottom)
        lineTo(layout.x(points.first().first), layout.y(points.first().second))
        for (i in 1 until points.size) {
            val (x0, y0) = points[i - 1]
            val (x1, y1) = points[i]
            val mx = x0 + (x1 - x0) * smooth
            cubicTo(layout.x(mx), layout.y(y0), layout.x(x1 - (x1 - x0) * smooth), layout.y(y1), layout.x(x1), layout.y(y1))
        }
        lineTo(layout.x(points.last().first), f.bottom)
        close()
    }
    drawPath(path, color)
}

/** A line of little waves across the field at [y]. */
private fun DrawScope.wave(layout: CatchLayout, y: Float, amp: Float, count: Float, phase: Float, color: Color, width: Float) {
    val f = layout.field
    val path = Path().apply {
        val steps = 40
        for (s in 0..steps) {
            val x = f.left + f.width * s / steps
            val yy = y + sin((s.toFloat() / steps * count + phase) * TAU) * amp
            if (s == 0) moveTo(x, yy) else lineTo(x, yy)
        }
    }
    drawPath(path, color, style = Stroke(width, cap = StrokeCap.Round))
}

/** A puffy cloud at ([x], [y]) in field coordinates, [u] its unit. */
private fun DrawScope.cloud(layout: CatchLayout, x: Float, y: Float, u: Float) {
    val c = layout.at(x, y)
    val white = Color.White.copy(alpha = 0.85f)
    drawOval(white, c - Offset(9f * u, 2.5f * u), Size(18f * u, 5f * u))
    drawCircle(white, 4f * u, c + Offset(-3f * u, -1.5f * u))
    drawCircle(white, 5f * u, c + Offset(2.5f * u, -2.5f * u))
}

/** A curled streak of breeze at ([x], [y]), blowing right (or left when [mirrored]). */
private fun DrawScope.breezeStreak(layout: CatchLayout, x: Float, y: Float, u: Float, color: Color, mirrored: Boolean = false) {
    val c = layout.at(x, y)
    val m = if (mirrored) -1f else 1f
    val path = Path().apply {
        moveTo(c.x - 12f * u * m, c.y)
        cubicTo(c.x - 4f * u * m, c.y - 1.5f * u, c.x + 4f * u * m, c.y + 1.5f * u, c.x + 9f * u * m, c.y - 0.5f * u)
        quadraticBezierTo(c.x + 12f * u * m, c.y - 2f * u, c.x + 10f * u * m, c.y - 3.5f * u)
    }
    drawPath(path, color, style = Stroke(0.8f * u, cap = StrokeCap.Round))
}

/** [v] wrapped into 0 until 1. */
private fun wrap(v: Float): Float = v - floor(v)
