package io.colorsand.ui.arena

import androidx.compose.foundation.layout.Spacer
import androidx.compose.runtime.Composable
import androidx.compose.runtime.State
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.drawWithCache
import androidx.compose.ui.geometry.CornerRadius
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Rect
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Paint
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.clipPath
import androidx.compose.ui.graphics.drawscope.drawIntoCanvas
import androidx.compose.ui.graphics.drawscope.rotate
import androidx.compose.ui.graphics.drawscope.scale
import androidx.compose.ui.graphics.drawscope.translate
import androidx.compose.ui.graphics.lerp
import kotlin.math.abs
import kotlin.math.cos
import kotlin.math.min
import kotlin.math.sin

/**
 * The Sea Floor: the bottom of a sunny, shallow sea. Rays of light fall from the rippling surface far above
 * through water going from bright teal to deep blue, onto a pale sandy floor where caustics drift. Coral and
 * kelp grow at the sides, sea grass sways, bubbles rise, a school of fish crosses high up and a turtle glides
 * by far away.
 */
@Composable
internal fun SeaFloorScene(grade: SceneGrade, modifier: Modifier = Modifier) {
    val clock = rememberSceneClock()
    Spacer(
        modifier.drawWithCache {
            val art = SeaFloorArt(size, grade)
            onDrawBehind { art.draw(this, clock) }
        },
    )
}

/** Everything the Sea Floor draws, built once per size and grade; [draw] only moves it. */
private class SeaFloorArt(size: Size, private val g: SceneGrade) {
    private val w = size.width
    private val h = size.height
    private val u = min(w, h * 0.6f)

    private val floorY = h * 0.8f
    private val surfaceY = h * 0.035f

    /** The color of the water far off: distant things fade into it. */
    private val water = Color(0xFF2E86AE)
    private fun far(c: Long, amount: Float) = g(lerp(Color(c), water, amount))

    private val sea = Brush.verticalGradient(
        0f to g(0xFF5CC6D4), 0.1f to g(0xFF3AA8C6), 0.38f to g(0xFF2A8FBA), 0.62f to g(0xFF2479AC), 0.82f to g(0xFF1F6C9E),
        startY = 0f, endY = h,
    )

    // The surface seen from below, and the sun shining through it.
    private val sunAt = Offset(w * 0.64f, -u * 0.04f)
    private val sunGlow = g(0xFFE6FFF4)
    private val surfaceLight = g(0xFFC8F6F2)
    private val surface = Path()
    private val surfaceLine = Path()

    // Rays of light fanning out from the sun, each a long soft wedge pointing down from its top.
    private class Ray(val x: Float, val tilt: Float, val path: Path, val brush: Brush, val cycles: Int, val phase: Float)

    private val rays = SceneRandom(61).let { r ->
        listOf(-0.32f, -0.12f, 0.02f, 0.2f, 0.38f, 0.55f).map { f ->
            val x = sunAt.x + w * f
            val length = h * r.next(0.55f, 0.85f)
            val top = u * r.next(0.04f, 0.08f)
            val bottom = u * r.next(0.16f, 0.3f)
            val path = Path().apply {
                moveTo(-top / 2, 0f)
                lineTo(top / 2, 0f)
                lineTo(bottom / 2, length)
                lineTo(-bottom / 2, length)
                close()
            }
            val brush = Brush.verticalGradient(0f to g(Color(0x44F2FFF8)), 0.55f to g(Color(0x18F2FFF8)), 1f to Color.Transparent, startY = 0f, endY = length)
            Ray(x, (sunAt.x - x) / w * 34f, path, brush, 5 + (r.next() * 5).toInt(), r.next())
        }
    }

    // Specks drifting down through the water.
    private class Speck(val x: Float, val radius: Float, val laps: Int, val start: Float, val alpha: Float)

    private val specks = SceneRandom(67).let { r ->
        List(34) { Speck(w * r.next(), u * r.next(0.002f, 0.005f), 2 + (r.next() * 3).toInt(), r.next(), r.next(0.18f, 0.45f)) }
    }
    private val speckColor = g(0xFFE6FBFF)

    // Far reefs fading into the blue, then a nearer bank.
    private val farReef = Ridge(w, h * 0.79f, u * 0.09f, 2.4f, 0.3f).fill(h)
    private val farReefColor = far(0xFF3F7894, 0.55f)
    private val midReef = Ridge(w, h * 0.81f, u * 0.05f, 1.7f, 0.65f).fill(h)
    private val midReefColor = far(0xFF5A8E9C, 0.35f)

    // The sandy floor with caustics playing over it.
    private val floorRidge = Ridge(w, h * 0.83f, u * 0.025f, 1.3f, 0.1f)
    private val floor = floorRidge.fill(h)
    private val floorBrush = Brush.verticalGradient(
        0f to g(0xFFA8CBC7), 0.18f to g(0xFFD6D8C0), 0.6f to g(0xFFE6DFC2), 1f to g(0xFFD8CCA8), startY = h * 0.8f, endY = h,
    )
    private val caustics = causticNet(SceneRandom(71), w, floorY - u * 0.02f, h, u * 0.13f)
    private val causticColor = g(Color(0x2EFFFFF0))
    private val ripples = Path().apply {
        val r = SceneRandom(73)
        repeat(10) {
            val x = w * r.next(-0.1f, 0.95f)
            val y = h * r.next(0.86f, 0.99f)
            moveTo(x, y)
            quadraticTo(x + u * 0.07f, y - u * 0.01f, x + u * r.next(0.12f, 0.22f), y)
        }
    }
    private val rippleColor = g(Color(0x2A5B7C80))
    private val pebbles = SceneRandom(79).let { r ->
        List(7) { Offset(w * r.next(), h * r.next(0.86f, 0.99f)) to u * r.next(0.007f, 0.013f) }
    }
    private val pebbleColor = g(0xFF9AA6A0)

    // Reef rocks with coral at both sides.
    private val rock = blob(SceneRandom(83), 11, 0.75f)
    private val rockLit = g(0xFF6F93A2)
    private val rockShade = g(0xFF41617A)
    private val leftReef = Offset(w * 0.09f, h * 0.835f)
    private val rightReef = Offset(w * 0.9f, h * 0.84f)
    private val coral = branches(SceneRandom(89))
    private val coralColor = g(0xFFFF7B8E)
    private val coralTip = g(0xFFFFB3BC)
    private val fanColor = g(0xFFC070E8)
    private val fan = fanPath()
    private val spongeColor = g(0xFFFFA449)
    private val spongeHole = g(0xFFB0532A)
    private val bubbleCoral = g(0xFFF2C14E)
    private val bubbleCoralShade = g(0xFFC98A2E)
    private val anemoneColor = g(0xFFFF8FC7)
    private val anemoneBase = g(0xFFC4508E)

    // Kelp swaying at both sides, behind the reefs.
    private class Kelp(val x: Float, val base: Float, val height: Float, val phase: Float, val lean: Float)

    private val kelps = listOf(
        Kelp(w * 0.03f, h * 0.84f, h * 0.44f, 0f, 1f),
        Kelp(w * 0.14f, h * 0.83f, h * 0.31f, 0.3f, 0.7f),
        Kelp(w * 0.86f, h * 0.83f, h * 0.36f, 0.55f, -0.7f),
        Kelp(w * 0.97f, h * 0.84f, h * 0.48f, 0.8f, -1f),
    )
    private val kelpStem = g(0xFF3C7A4E)
    private val kelpLeaf = g(0xFF5AA35A)
    private val kelpLeafDark = g(0xFF3E8650)
    private val leaf = Path().apply {
        moveTo(0f, 0f)
        cubicTo(0.3f, -0.22f, 0.75f, -0.2f, 1f, 0f)
        cubicTo(0.75f, 0.12f, 0.3f, 0.14f, 0f, 0f)
        close()
    }
    private val kelpPath = Path()
    private val kelpPoints = Array(KELP_STEPS + 1) { Offset.Zero }

    // Sea grass tufts on the floor near the reefs.
    private val tufts = listOf(w * 0.2f, w * 0.25f, w * 0.75f, w * 0.79f).map { Offset(it, floorRidge.y(it) + u * 0.012f) }
    private val grassColor = g(0xFF5E9E62)
    private val grassPath = Path()

    // Bubbles rising from the reefs, and a few strays.
    private class Bubble(val x: Float, val from: Float, val radius: Float, val laps: Int, val start: Float)

    private val bubbles = SceneRandom(101).let { r ->
        val streams = listOf(leftReef + Offset(u * 0.05f, -u * 0.09f), rightReef + Offset(-u * 0.06f, -u * 0.06f))
        streams.flatMap { s -> List(6) { Bubble(s.x, s.y, u * r.next(0.006f, 0.012f), 3, it / 6f + r.next(0f, 0.05f)) } } +
            List(5) { Bubble(w * r.next(0.25f, 0.75f), floorY, u * r.next(0.004f, 0.008f), 2, r.next()) }
    }
    private val bubbleColor = g(0xFFF0FFFF)

    // Fish: a bright school crossing high up, a faint far one lower down.
    private class Fish(val dx: Float, val dy: Float, val size: Float, val phase: Float)

    private val school = SceneRandom(103).let { r -> List(8) { Fish(u * r.next(-0.12f, 0.12f), u * r.next(-0.05f, 0.05f), u * r.next(0.03f, 0.04f), r.next()) } }
    private val farSchool = SceneRandom(107).let { r -> List(10) { Fish(u * r.next(-0.1f, 0.1f), u * r.next(-0.035f, 0.035f), u * r.next(0.016f, 0.022f), r.next()) } }
    private val fishBody = Path().apply {
        moveTo(0.5f, 0f)
        cubicTo(0.35f, -0.36f, -0.25f, -0.32f, -0.4f, 0f)
        cubicTo(-0.25f, 0.3f, 0.35f, 0.34f, 0.5f, 0f)
        close()
    }
    private val fishTail = Path().apply {
        moveTo(0f, 0f)
        lineTo(-0.28f, -0.22f)
        quadraticTo(-0.2f, 0f, -0.28f, 0.22f)
        close()
    }
    private val fishYellow = g(0xFFFFD447)
    private val fishBlue = g(0xFF2E7DD8)
    private val fishFar = far(0xFF8FD0E0, 0.45f)

    // The turtle far off is the keepsake turtle, half lost in the blue.
    private val turtleHaze = Paint().apply { alpha = 0.62f }

    private val shade = vignette(w, h, g(Color(0x46062848)))

    fun draw(scope: DrawScope, clock: State<Float>) = with(scope) {
        val t = clock.value
        drawRect(sea)
        drawGlow(sunAt, u * 0.9f, sunGlow.copy(alpha = 0.45f))
        drawSurface(t)
        for (ray in rays) {
            val a = 0.65f + 0.35f * swing(t, ray.cycles, ray.phase)
            translate(ray.x, -u * 0.02f) {
                rotate(ray.tilt + 1.5f * swing(t, 4, ray.phase), Offset.Zero) { drawPath(ray.path, ray.brush, alpha = a) }
            }
        }
        drawTurtle(t)
        drawFish(t, farSchool, drift(t, 1, 0.6f), h * 0.6f, toRight = false, far = true)

        drawPath(farReef, farReefColor)
        drawPath(midReef, midReefColor)
        for (k in kelps) drawKelp(t, k)

        drawPath(floor, floorBrush)
        clipPath(floor) {
            translate(u * 0.02f * swing(t, 7), u * 0.006f * swing(t, 5, 0.3f)) { drawPath(caustics, causticColor, style = Stroke(u * 0.005f, cap = StrokeCap.Round)) }
            translate(-u * 0.025f * swing(t, 6, 0.4f), u * 0.008f * swing(t, 9)) { drawPath(caustics, causticColor, alpha = 0.6f, style = Stroke(u * 0.003f, cap = StrokeCap.Round)) }
        }
        drawPath(ripples, rippleColor, style = Stroke(u * 0.003f, cap = StrokeCap.Round))
        for ((at, r) in pebbles) {
            drawOval(Color.Black.copy(alpha = 0.1f), Offset(at.x - r * 1.1f, at.y - r * 0.2f), Size(r * 2.2f, r * 0.9f))
            drawOval(pebbleColor, Offset(at.x - r, at.y - r * 0.7f), Size(r * 2f, r * 1.2f))
        }
        for (tuft in tufts) drawGrass(t, tuft)
        drawLeftReef(t)
        drawRightReef()
        drawBubbles(t)
        drawFish(t, school, drift(t, 2, 0.15f), h * 0.19f, toRight = true, far = false)
        drawRect(shade)
    }

    /** The underside of the surface: a bright band with a slowly rolling edge. */
    private fun DrawScope.drawSurface(t: Float) {
        surface.reset()
        surfaceLine.reset()
        surface.moveTo(-1f, -1f)
        val steps = 40
        for (i in 0..steps) {
            val x = w * i / steps
            val y = surfaceY + u * 0.01f * sin(TAU * (x / (u * 0.5f)) + TAU * t * 14) + u * 0.006f * swing(t, 9, x / w * 1.7f)
            surface.lineTo(x, y)
            if (i == 0) surfaceLine.moveTo(x, y) else surfaceLine.lineTo(x, y)
        }
        surface.lineTo(w + 1f, -1f)
        surface.close()
        drawPath(surface, surfaceLight, alpha = 0.35f)
        drawPath(surfaceLine, surfaceLight, alpha = 0.55f, style = Stroke(u * 0.005f, cap = StrokeCap.Round))
        translate(0f, u * 0.018f) { drawPath(surfaceLine, surfaceLight, alpha = 0.18f, style = Stroke(u * 0.003f)) }
        for (s in specks) {
            val y = surfaceY + drift(t, s.laps, s.start) * (floorY - surfaceY)
            val x = s.x + u * 0.015f * swing(t, 11, s.start)
            drawCircle(speckColor.copy(alpha = s.alpha), s.radius, Offset(x, y))
        }
    }

    private fun DrawScope.drawKelp(t: Float, k: Kelp) {
        kelpPath.reset()
        for (i in 0..KELP_STEPS) {
            val f = i / KELP_STEPS.toFloat()
            val sway = u * 0.07f * f * f * swing(t, 8, k.phase + f * 0.18f) + u * 0.05f * k.lean * f
            kelpPoints[i] = Offset(k.x + sway, k.base - k.height * f)
            if (i == 0) kelpPath.moveTo(kelpPoints[i].x, kelpPoints[i].y) else kelpPath.lineTo(kelpPoints[i].x, kelpPoints[i].y)
        }
        drawPath(kelpPath, kelpStem, style = Stroke(u * 0.009f, cap = StrokeCap.Round))
        for (i in 1..KELP_STEPS) {
            val p = kelpPoints[i]
            val f = i / KELP_STEPS.toFloat()
            val side = if (i % 2 == 0) 1f else -1f
            val length = u * (0.09f - 0.04f * f)
            val angle = (if (side > 0) -38f else -142f) + 14f * swing(t, 8, k.phase + f * 0.18f + 0.1f)
            rotate(angle, p) {
                translate(p.x, p.y) {
                    scale(length, length * if (side > 0) 1f else -1f, Offset.Zero) { drawPath(leaf, if (i % 3 == 0) kelpLeafDark else kelpLeaf) }
                }
            }
        }
    }

    private fun DrawScope.drawGrass(t: Float, at: Offset) {
        grassPath.reset()
        for (b in 0 until 5) {
            val x = at.x + u * (b - 2) * 0.008f
            val height = u * (0.04f + 0.025f * ((b * 7) % 3))
            val bend = u * 0.02f * swing(t, 10, at.x / w + b * 0.07f) + u * (b - 2) * 0.006f
            grassPath.moveTo(x - u * 0.003f, at.y)
            grassPath.quadraticTo(x + bend * 0.3f, at.y - height * 0.6f, x + bend, at.y - height)
            grassPath.quadraticTo(x + bend * 0.3f + u * 0.004f, at.y - height * 0.55f, x + u * 0.004f, at.y)
            grassPath.close()
        }
        drawPath(grassPath, grassColor)
    }

    /** A reef rock on the left with branching coral, tube sponges and a swaying anemone. */
    private fun DrawScope.drawLeftReef(t: Float) {
        val s = u * 0.11f
        drawRock(leftReef, s)
        translate(leftReef.x - s * 0.15f, leftReef.y - s * 0.55f) {
            scale(s * 0.9f, s * 0.9f, Offset.Zero) {
                drawPath(coral.first, coralColor, style = Stroke(0.11f, cap = StrokeCap.Round))
            }
        }
        coralTips(leftReef.x - s * 0.15f, leftReef.y - s * 0.55f, s * 0.9f)
        // Tube sponges.
        for ((dx, tall) in listOf(0.55f to 0.75f, 0.78f to 1f, 0.98f to 0.6f)) {
            val x = leftReef.x + s * dx
            val top = leftReef.y - s * (0.2f + 0.5f * tall)
            val r = s * 0.1f
            drawRoundRect(spongeColor, Offset(x - r, top), Size(r * 2, leftReef.y - top), CornerRadius(r * 0.6f))
            drawOval(spongeHole, Offset(x - r * 0.75f, top + r * 0.1f), Size(r * 1.5f, r * 0.6f))
            drawLine(Color.White.copy(alpha = 0.25f), Offset(x - r * 0.45f, top + r), Offset(x - r * 0.45f, leftReef.y - r), r * 0.3f, StrokeCap.Round)
        }
        drawAnemone(t, leftReef + Offset(-s * 0.55f, -s * 0.28f), s * 0.42f)
    }

    /** A reef rock on the right with a sea fan and a brain coral. */
    private fun DrawScope.drawRightReef() {
        val s = u * 0.12f
        translate(rightReef.x + s * 0.05f, rightReef.y - s * 0.45f) {
            scale(s * 1.5f, s * 1.5f, Offset.Zero) {
                drawPath(fan.first, fanColor, alpha = 0.3f)
                drawPath(fan.second, fanColor, style = Stroke(0.03f, cap = StrokeCap.Round))
            }
        }
        drawRock(rightReef, s)
        // A cluster of round bubble coral at the rock's foot.
        for ((dx, dy, r) in BUBBLE_CORAL) {
            val c = Offset(rightReef.x + s * dx, rightReef.y + s * dy)
            drawCircle(bubbleCoralShade, s * r, c)
            drawCircle(bubbleCoral, s * r * 0.86f, c - Offset(s * r * 0.1f, s * r * 0.12f))
            drawCircle(Color.White.copy(alpha = 0.4f), s * r * 0.25f, c - Offset(s * r * 0.35f, s * r * 0.4f))
        }
    }

    private fun DrawScope.drawRock(base: Offset, s: Float) {
        drawOval(Color.Black.copy(alpha = 0.14f), Offset(base.x - s * 1.2f, base.y - s * 0.12f), Size(s * 2.4f, s * 0.3f))
        translate(base.x, base.y - s * 0.3f) {
            scale(s, s * 0.6f, Offset.Zero) {
                drawPath(rock, rockLit)
                clipPath(rock) { translate(0.12f, 0.22f) { drawPath(rock, rockShade) } }
            }
        }
    }

    private fun DrawScope.coralTips(x: Float, y: Float, s: Float) {
        for (tip in coral.second) drawCircle(coralTip, s * 0.07f, Offset(x + tip.x * s, y + tip.y * s))
    }

    private fun DrawScope.drawAnemone(t: Float, at: Offset, s: Float) {
        for (i in 0 until 9) {
            val a = -150f + i * 15f + 8f * swing(t, 10, i * 0.06f)
            val rad = a * PI_F / 180f
            val end = at + Offset(cos(rad), sin(rad)) * s
            drawLine(anemoneColor, at, end, s * 0.13f, StrokeCap.Round)
        }
        drawOval(anemoneBase, Offset(at.x - s * 0.35f, at.y - s * 0.12f), Size(s * 0.7f, s * 0.4f))
    }

    private fun DrawScope.drawBubbles(t: Float) {
        val top = surfaceY + u * 0.02f
        for (b in bubbles) {
            val p = drift(t, b.laps, b.start)
            val y = b.from - p * (b.from - top)
            val x = b.x + u * 0.012f * swing(t, 40, b.start) * p
            val r = b.radius * (0.7f + 0.6f * p)
            val a = min(1f, p * 8f) * min(1f, (1f - p) * 5f)
            if (a <= 0f) continue
            val c = Offset(x, y)
            drawCircle(bubbleColor.copy(alpha = 0.12f * a), r, c)
            drawCircle(bubbleColor.copy(alpha = 0.6f * a), r, c, style = Stroke(r * 0.2f))
            drawCircle(Color.White.copy(alpha = 0.8f * a), r * 0.25f, c + Offset(-r * 0.35f, -r * 0.35f))
        }
    }

    private fun DrawScope.drawFish(t: Float, fish: List<Fish>, p: Float, y: Float, toRight: Boolean, far: Boolean) {
        val span = u * 0.2f
        val cx = if (toRight) -span + p * (w + 2 * span) else w + span - p * (w + 2 * span)
        val cy = y + u * 0.03f * swing(t, 6, if (far) 0.5f else 0f)
        for (f in fish) {
            val at = Offset(cx + f.dx, cy + f.dy + u * 0.006f * swing(t, 30, f.phase))
            translate(at.x, at.y) {
                scale(if (toRight) f.size else -f.size, f.size, Offset.Zero) {
                    rotate(18f * swing(t, 260, f.phase), Offset(-0.38f, 0f)) {
                        translate(-0.36f, 0f) { drawPath(fishTail, if (far) fishFar else fishBlue) }
                    }
                    if (far) {
                        drawPath(fishBody, fishFar, alpha = 0.7f)
                    } else {
                        drawPath(fishBody, fishYellow)
                        drawLine(fishBlue, Offset(-0.05f, -0.24f), Offset(0.02f, 0.24f), 0.1f)
                        drawLine(Color.White.copy(alpha = 0.45f), Offset(-0.15f, -0.12f), Offset(0.25f, -0.13f), 0.06f, StrokeCap.Round)
                        drawCircle(Color(0xFF1E2A3A), 0.055f, Offset(0.28f, -0.05f))
                    }
                }
            }
        }
    }

    /** A sea turtle gliding across, far off and faded into the blue: the keepsake turtle, facing left. */
    private fun DrawScope.drawTurtle(t: Float) {
        val s = u * 0.07f
        val p = drift(t, 1, 0.35f)
        val x = w + s * 2 - p * (w + s * 4)
        val y = h * 0.36f + u * 0.04f * swing(t, 3)
        // The keepsake's box is 100 across; its turtle is about 75 long, nose to tail.
        val k = s * 2.2f / 75f
        drawIntoCanvas { it.saveLayer(Rect(x - s * 2f, y - s * 1.6f, x + s * 2f, y + s * 1.6f), turtleHaze) }
        translate(x, y) {
            scale(-k, k, Offset.Zero) {
                translate(-53f, -64f) { seaTurtle(t, g, swimming = true) }
            }
        }
        drawIntoCanvas { it.restore() }
    }
}

private const val KELP_STEPS = 12

/** The bubble coral's balls: offset from the reef's base and radius, in reef sizes. */
private val BUBBLE_CORAL = listOf(Triple(-0.95f, -0.1f, 0.17f), Triple(-0.7f, -0.16f, 0.2f), Triple(-0.78f, -0.42f, 0.15f), Triple(-0.48f, -0.08f, 0.14f), Triple(-1.08f, -0.32f, 0.11f))
private const val PI_F = kotlin.math.PI.toFloat()

/** A branching coral growing up from the origin, about one unit tall, forking as it turns; with its tips. */
private fun branches(r: SceneRandom): Pair<Path, List<Offset>> {
    val tips = mutableListOf<Offset>()
    val path = Path()
    fun grow(from: Offset, angle: Float, length: Float, depth: Int) {
        val rad = angle * PI_F / 180f
        val to = from + Offset(cos(rad), sin(rad)) * length
        path.moveTo(from.x, from.y)
        path.quadraticTo(from.x + (to.x - from.x) * 0.5f + length * 0.08f, from.y + (to.y - from.y) * 0.5f, to.x, to.y)
        if (depth == 0) {
            tips += to
            return
        }
        grow(to, angle - r.next(18f, 32f), length * r.next(0.62f, 0.78f), depth - 1)
        grow(to, angle + r.next(18f, 32f), length * r.next(0.62f, 0.78f), depth - 1)
    }
    grow(Offset(0f, 0.6f), -90f, 0.38f, 3)
    return path to tips
}

/** A sea fan: a soft fan shape (first) and the branching ribs that hold it (second), rising from the origin. */
private fun fanPath(): Pair<Path, Path> {
    val shape = Path().apply {
        moveTo(0f, 0.3f)
        cubicTo(-0.8f, 0.0f, -0.75f, -0.78f, 0f, -0.82f)
        cubicTo(0.75f, -0.78f, 0.8f, 0.0f, 0f, 0.3f)
        close()
    }
    val ribs = Path().apply {
        // Main ribs fanning out from the stalk, each forking once near its end.
        for (i in 0..6) {
            val a = (-165f + i * 25f) * PI_F / 180f
            val reach = 1f - 0.25f * abs(i - 3) / 3f
            val mid = Offset(cos(a) * 0.36f * reach, 0.3f + sin(a) * 0.62f * reach)
            val end = Offset(cos(a) * 0.62f * reach, 0.3f + sin(a) * 1.05f * reach)
            moveTo(0f, 0.3f)
            quadraticTo(mid.x * 0.7f, mid.y, end.x, end.y)
            for (fork in listOf(-0.22f, 0.22f)) {
                moveTo(mid.x, mid.y)
                lineTo(end.x + fork * 0.3f, end.y + 0.05f)
            }
        }
        // A cross-weave of fine arcs.
        for (k in 1..4) {
            val rr = k * 0.2f
            moveTo(-rr * 0.75f, 0.3f - rr * 0.65f)
            quadraticTo(0f, 0.3f - rr * 1.3f, rr * 0.75f, 0.3f - rr * 0.65f)
        }
    }
    return shape to ribs
}

/** A lumpy round outline of [points] points around the origin, radius about 1, flattened at the bottom by [flat]. */
internal fun blob(r: SceneRandom, points: Int, flat: Float): Path = Path().apply {
    val pts = List(points) { i ->
        val a = TAU * i / points
        val radius = r.next(0.82f, 1.05f)
        Offset(cos(a) * radius, min(sin(a) * radius, flat))
    }
    val first = (pts.last() + pts[0]) / 2f
    moveTo(first.x, first.y)
    for (i in pts.indices) {
        val p = pts[i]
        val next = (p + pts[(i + 1) % points]) / 2f
        quadraticTo(p.x, p.y, next.x, next.y)
    }
    close()
}

/**
 * A net of wobbly light lines like the caustics on a sunlit sea floor, covering [width] from [top] to [bottom]
 * in cells about [cell] wide, squashed in depth.
 */
private fun causticNet(r: SceneRandom, width: Float, top: Float, bottom: Float, cell: Float): Path {
    val rowH = cell * 0.45f
    val cols = (width / cell).toInt() + 3
    val rows = ((bottom - top) / rowH).toInt() + 2
    val grid = List(rows) { j ->
        List(cols) { i -> Offset((i - 1 + r.next(-0.42f, 0.42f)) * cell, top + (j + r.next(-0.42f, 0.42f)) * rowH) }
    }
    return Path().apply {
        for (j in 0 until rows) {
            for (i in 0 until cols) {
                val p = grid[j][i]
                if (i + 1 < cols) {
                    val q = grid[j][i + 1]
                    moveTo(p.x, p.y)
                    quadraticTo((p.x + q.x) / 2 + cell * r.next(-0.2f, 0.2f), (p.y + q.y) / 2 + rowH * r.next(-0.6f, 0.6f), q.x, q.y)
                }
                if (j + 1 < rows) {
                    val q = grid[j + 1][i]
                    moveTo(p.x, p.y)
                    quadraticTo((p.x + q.x) / 2 + cell * r.next(-0.45f, 0.45f), (p.y + q.y) / 2, q.x, q.y)
                }
            }
        }
    }
}
