package io.colorsand.ui.fx

import androidx.compose.runtime.Composable
import androidx.compose.runtime.DisposableEffect
import androidx.compose.runtime.remember
import kotlinx.browser.window
import org.w3c.dom.events.Event

@Composable
internal actual fun rememberSoundPlayer(): SoundPlayer {
    val player = remember { WebSoundPlayer() }
    DisposableEffect(player) { onDispose { player.close() } }
    return player
}

@Composable
internal actual fun rememberHaptics(): Haptics = NoHaptics

/**
 * Plays sounds with Web Audio: each sound is one AudioBuffer, and each play a new buffer source. Browsers only
 * let a page make sound after the user has interacted with it, so the AudioContext is made (and resumed) on the
 * first tap or key press; sounds before that are skipped.
 */
private class WebSoundPlayer : SoundPlayer {
    private var context: dynamic = null
    private val buffers = HashMap<Sound, dynamic>()
    private val playing = HashMap<Sound, dynamic>()
    private val unlock: (Event) -> Unit = { start() }

    init {
        Sounds.all.forEach { it.samples } // render now rather than on the first tap
        GESTURES.forEach { window.addEventListener(it, unlock, true) }
    }

    private fun start() {
        if (context == null) {
            val ctx: dynamic = runCatching { newAudioContext() }.getOrNull()
            if (ctx == null) {
                stopListening()
                return
            }
            for (sound in Sounds.all) {
                val pcm = sound.samples
                val buffer = ctx.createBuffer(1, pcm.size, SAMPLE_RATE)
                // A Kotlin FloatArray is a Float32Array in JS, so it copies straight in.
                buffer.getChannelData(0).set(pcm)
                buffers[sound] = buffer
            }
            context = ctx
        }
        if (context.state == "running") stopListening() else runCatching { context.resume() }
    }

    private fun stopListening() = GESTURES.forEach { window.removeEventListener(it, unlock, true) }

    override fun play(sound: Sound) {
        val ctx: dynamic = context
        val buffer: dynamic = buffers[sound]
        if (ctx == null || buffer == null) return
        runCatching {
            val source = ctx.createBufferSource()
            source.buffer = buffer
            source.connect(ctx.destination)
            source.start()
            playing[sound] = source
        }
    }

    override fun stop(sound: Sound) {
        val source: dynamic = playing.remove(sound)
        if (source != null) runCatching { source.stop() }
    }

    fun close() {
        stopListening()
        if (context != null) runCatching { context.close() }
    }

    private companion object {
        val GESTURES = listOf("pointerdown", "touchend", "mousedown", "keydown")
    }
}

private fun newAudioContext(): dynamic =
    js("new (window.AudioContext || window.webkitAudioContext)({ latencyHint: 'interactive' })")
