package io.colorsand.ui

import androidx.compose.animation.core.Animatable
import androidx.compose.animation.core.LinearEasing
import androidx.compose.animation.core.tween
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.State
import androidx.compose.runtime.remember
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.withTransform
import androidx.compose.ui.graphics.lerp
import io.colorsand.ui.arena.drawSparkle
import kotlin.math.PI
import kotlin.math.cos
import kotlin.math.exp
import kotlin.math.sin

/**
 * Watches one tube for the moment it gets finished, so its cork pops on then and only then: not for a tube that
 * is already finished when it is first seen, and not again while it stays finished.
 */
internal class CapWatch {
    private var last: Boolean? = null

    /** Notes whether the tube is [finished] now. True when it has just become finished after being seen unfinished. */
    fun justFinished(finished: Boolean): Boolean {
        val popped = last == false && finished
        last = finished
        return popped
    }
}

internal const val CAP_POP_MILLIS = 950

/**
 * How far the cork has popped on, 0 to 1, for a tube that is [finished] or not. It runs from 0 when the tube
 * has just been finished, rests at 1 on a tube that was finished when first shown, and drops to 0 on undo.
 * Read it while drawing.
 */
@Composable
internal fun rememberCapPop(finished: Boolean): State<Float> {
    val watch = remember { CapWatch() }
    val pop = remember { Animatable(if (finished) 1f else 0f) }
    LaunchedEffect(finished) {
        if (watch.justFinished(finished)) {
            pop.snapTo(0f)
            pop.animateTo(1f, tween(CAP_POP_MILLIS, easing = LinearEasing))
        } else {
            pop.snapTo(if (finished) 1f else 0f)
        }
    }
    return pop.asState()
}

/** The cork's size relative to its resting size at pop progress [p]: it springs on, overshoots and settles. */
internal fun capScale(p: Float): Float = when {
    p <= 0f -> 0f
    p >= 1f -> 1f
    else -> 1f - exp(-6.5f * p) * cos(13f * p)
}

/** How far above its seat the cork is at pop progress [p], in tube widths: it drops in during the first part. */
internal fun capDrop(p: Float): Float {
    val q = 1f - (p / 0.28f).coerceIn(0f, 1f)
    return 0.5f * q * q
}

internal const val CAP_SPARKLES = 11

/**
 * Sparkle [i] of the burst at pop progress [p]: where it is relative to the top of the cork (in tube widths),
 * its size (in tube widths) and alpha. They fly out from the cork once it lands and fade by the end.
 */
internal fun capSparkle(i: Int, p: Float): Triple<Offset, Float, Float> {
    val q = if (p >= 1f) 1f else ((p - 0.14f) / 0.86f).coerceIn(0f, 1f)
    if (q <= 0f) return Triple(Offset.Zero, 0f, 0f)
    val jitter = ((i * 37 + 11) % 17) / 16f // a fixed 0..1 per sparkle
    val angle = (190f + 160f * i / (CAP_SPARKLES - 1) + (jitter - 0.5f) * 16f) * PI.toFloat() / 180f
    val out = 1f - (1f - q) * (1f - q) * (1f - q)
    val dist = (0.12f + 0.7f * out) * (0.75f + 0.5f * jitter)
    val size = 0.2f * (0.75f + 0.5f * jitter) * (1f - 0.55f * q)
    // Written from the end so it reaches exactly 0 at q = 1 (in Float, 1 - (1 - 0.6) / 0.4 is not quite 0).
    val alpha = ((1f - q) / 0.4f).coerceIn(0f, 1f)
    return Triple(Offset(cos(angle), sin(angle)) * dist, size, alpha)
}

/**
 * Draws the cork in the mouth of a finished tube of sand [sand] at pop progress [p], with its burst of sparkles
 * while it pops on. Draws nothing at 0.
 */
internal fun DrawScope.drawCap(sand: Color, p: Float) {
    if (p <= 0f) return
    val w = size.width
    val cx = w / 2
    val seat = w * 0.12f
    val scale = capScale(p)
    if (p < 1f) {
        // A ring of light where it lands, then the sparkles.
        val ring = ((p - 0.14f) / 0.4f).coerceIn(0f, 1f)
        if (ring in 0.001f..0.999f) {
            drawCircle(lerp(sand, Color.White, 0.6f).copy(alpha = 0.55f * (1 - ring)), w * (0.3f + 0.6f * ring), Offset(cx, seat - w * 0.1f), style = Stroke(w * 0.05f * (1 - ring)))
        }
        val light = lerp(sand, Color.White, 0.3f)
        for (i in 0 until CAP_SPARKLES) {
            val (at, r, alpha) = capSparkle(i, p)
            if (alpha > 0f) drawSparkle(Offset(cx, seat - w * 0.12f) + at * w, r * w, if (i % 3 == 0) Color.White else light, alpha)
        }
    }
    withTransform({
        translate(top = -capDrop(p) * w)
        scale(scale, scale, Offset(cx, seat))
    }) {
        val top = -w * 0.14f
        val bottom = w * 0.2f
        val wTop = w * 0.33f
        val wBottom = w * 0.27f
        val body = Path().apply {
            moveTo(cx - wTop, top)
            lineTo(cx + wTop, top)
            lineTo(cx + wBottom, bottom - w * 0.04f)
            quadraticBezierTo(cx + wBottom, bottom, cx + wBottom - w * 0.04f, bottom)
            lineTo(cx - wBottom + w * 0.04f, bottom)
            quadraticBezierTo(cx - wBottom, bottom, cx - wBottom, bottom - w * 0.04f)
            close()
        }
        drawPath(
            body,
            Brush.horizontalGradient(
                0f to Color(0xFF9C6A3C),
                0.3f to Color(0xFFDDAE74),
                0.55f to Color(0xFFC99359),
                1f to Color(0xFF85552E),
                startX = cx - wTop,
                endX = cx + wTop,
            ),
        )
        // Pores in the cork.
        for (k in 0 until 7) {
            val x = cx + (((k * 53) % 11) / 10f - 0.5f) * wBottom * 1.5f
            val y = top + w * 0.05f + ((k * 29) % 7) / 6f * (bottom - top - w * 0.1f)
            drawOval(Color(0xFF7A4E2A).copy(alpha = 0.55f), Offset(x, y), Size(w * 0.045f, w * 0.028f))
        }
        val lid = w * 0.075f
        drawOval(Color(0xFFB17C47), Offset(cx - wTop, top - lid), Size(2 * wTop, 2 * lid))
        drawOval(Color(0xFFE9C08A), Offset(cx - wTop + w * 0.02f, top - lid + w * 0.012f), Size(2 * wTop - w * 0.04f, 2 * lid - w * 0.03f))
        drawOval(Color.White.copy(alpha = 0.45f), Offset(cx - wTop * 0.6f, top - lid * 0.55f), Size(wTop * 0.6f, lid * 0.45f))
    }
}
