package io.colorsand.ui.minigame

import io.colorsand.core.Arena
import kotlin.math.cbrt
import kotlin.math.ceil
import kotlin.math.pow
import kotlin.math.sqrt
import kotlin.random.Random

/** A color as sRGB channels, each 0 to 1. The mixer's own color type, so its math needs no UI. */
data class Rgb(val r: Float, val g: Float, val b: Float) {
    /** As 0xFFRRGGBB, for the UI. */
    val argb: Long
        get() {
            fun c(v: Float) = (v.coerceIn(0f, 1f) * 255f + 0.5f).toLong()
            return (0xFFL shl 24) or (c(r) shl 16) or (c(g) shl 8) or c(b)
        }

    companion object {
        val WHITE = Rgb(1f, 1f, 1f)
    }
}

/** A color in OKLab: [l]ightness 0 to 1 and the two opponent axes [a] (green to red) and [b] (blue to yellow). */
data class Lab(val l: Float, val a: Float, val b: Float) {
    /** The perceptual distance to [other]: about 0.02 is just noticeable, 0.3 or more is a different color. */
    fun distance(other: Lab): Float {
        val dl = l - other.l
        val da = a - other.a
        val db = b - other.b
        return sqrt(dl * dl + da * da + db * db)
    }

    fun toRgb(): Rgb {
        val l1 = l + 0.3963377774f * a + 0.2158037573f * b
        val m1 = l - 0.1055613458f * a - 0.0638541728f * b
        val s1 = l - 0.0894841775f * a - 1.2914855480f * b
        val l3 = l1 * l1 * l1
        val m3 = m1 * m1 * m1
        val s3 = s1 * s1 * s1
        return Rgb(
            encode(4.0767416621f * l3 - 3.3077115913f * m3 + 0.2309699292f * s3),
            encode(-1.2684380046f * l3 + 2.6097574011f * m3 - 0.3413193965f * s3),
            encode(-0.0041960863f * l3 - 0.7034186147f * m3 + 1.7076147010f * s3),
        )
    }

    companion object {
        fun of(c: Rgb): Lab {
            val r = decode(c.r)
            val g = decode(c.g)
            val b = decode(c.b)
            val l = cbrt(0.4122214708f * r + 0.5363325363f * g + 0.0514459929f * b)
            val m = cbrt(0.2119034982f * r + 0.6806995451f * g + 0.1073969566f * b)
            val s = cbrt(0.0883024619f * r + 0.2817188376f * g + 0.6299787005f * b)
            return Lab(
                0.2104542553f * l + 0.7936177850f * m - 0.0040720468f * s,
                1.9779984951f * l - 2.4285922050f * m + 0.4505937099f * s,
                0.0259040371f * l + 0.7827717662f * m - 0.8086757660f * s,
            )
        }

        /** sRGB to linear light. */
        private fun decode(c: Float): Float = if (c <= 0.04045f) c / 12.92f else ((c + 0.055f) / 1.055f).pow(2.4f)

        /** Linear light to sRGB, clamped into gamut. */
        private fun encode(c: Float): Float {
            val v = c.coerceIn(0f, 1f)
            return if (v <= 0.0031308f) v * 12.92f else 1.055f * v.pow(1f / 2.4f) - 0.055f
        }
    }
}

/** The four pots by the bowl: the three primaries, and white to lighten. */
enum class Ink(val title: String) {
    RED("red"), YELLOW("yellow"), BLUE("blue"), WHITE("white");

    /** The pot's own color, as a mix of one scoop of it. */
    val color: Rgb get() = Scoops.of(this).color!!
}

/**
 * The scoops in the bowl, so many of each [Ink]. Mixing works like paint: only the proportions matter (two red and
 * two yellow is the same orange as one of each), yellow and blue make green, all three make brown, and white turns
 * any of them into a softer tint.
 */
data class Scoops(val red: Int = 0, val yellow: Int = 0, val blue: Int = 0, val white: Int = 0) {
    val total: Int get() = red + yellow + blue + white

    val isEmpty: Boolean get() = total == 0

    operator fun get(ink: Ink): Int = when (ink) {
        Ink.RED -> red
        Ink.YELLOW -> yellow
        Ink.BLUE -> blue
        Ink.WHITE -> white
    }

    operator fun plus(ink: Ink): Scoops = when (ink) {
        Ink.RED -> copy(red = red + 1)
        Ink.YELLOW -> copy(yellow = yellow + 1)
        Ink.BLUE -> copy(blue = blue + 1)
        Ink.WHITE -> copy(white = white + 1)
    }

    /** The mixed color, or null for an empty bowl. */
    val color: Rgb?
        get() {
            if (isEmpty) return null
            val hues = red + yellow + blue
            if (hues == 0) return Rgb.WHITE
            val most = maxOf(red, yellow, blue).toFloat()
            val pure = ryb(red / most, yellow / most, blue / most)
            if (white == 0) return pure
            // White tints in OKLab, so a pink stays a pink rather than going gray on the way to white.
            val w = white.toFloat() / total
            val p = Lab.of(pure)
            val c = Lab.of(Rgb.WHITE)
            return Lab(p.l + (c.l - p.l) * w, p.a + (c.a - p.a) * w, p.b + (c.b - p.b) * w).toRgb()
        }

    /** Read out for screen readers: "2 red, 1 yellow", or "empty". */
    fun describe(): String =
        Ink.entries.filter { this[it] > 0 }.joinToString(", ") { "${this[it]} ${it.title}" }.ifEmpty { "empty" }

    companion object {
        fun of(ink: Ink): Scoops = Scoops() + ink

        /**
         * The paint color of red, yellow and blue amounts (each 0 to 1): a trilinear blend of the RYB cube's corners,
         * after Gosset and Chen, with the corners tuned to the game's bright, friendly paints.
         */
        private fun ryb(r: Float, y: Float, b: Float): Rgb {
            fun blend(channel: (Rgb) -> Float): Float {
                fun corner(i: Int) = channel(CORNERS[i])
                fun lerp(a: Float, z: Float, t: Float) = a + (z - a) * t
                val c00 = lerp(corner(0), corner(4), r)
                val c01 = lerp(corner(1), corner(5), r)
                val c10 = lerp(corner(2), corner(6), r)
                val c11 = lerp(corner(3), corner(7), r)
                return lerp(lerp(c00, c01, b), lerp(c10, c11, b), y)
            }
            return Rgb(blend { it.r }, blend { it.g }, blend { it.b })
        }

        /** The RYB cube's corners, indexed r * 4 + y * 2 + b. Never all zero: an empty bowl has no color. */
        private val CORNERS = listOf(
            Rgb(1f, 1f, 1f), // none
            Rgb(0.16f, 0.42f, 0.86f), // blue
            Rgb(1f, 0.86f, 0.12f), // yellow
            Rgb(0.18f, 0.68f, 0.30f), // yellow + blue: green
            Rgb(0.90f, 0.16f, 0.18f), // red
            Rgb(0.52f, 0.22f, 0.66f), // red + blue: purple
            Rgb(0.98f, 0.52f, 0.10f), // red + yellow: orange
            Rgb(0.40f, 0.26f, 0.15f), // all three: brown
        )
    }
}

/** A color to mix: its [name] and a [recipe] that makes it exactly, a few scoops at most. */
data class MixTarget(val name: String, val recipe: Scoops) {
    val color: Rgb get() = recipe.color!!
    val lab: Lab get() = Lab.of(color)
}

/** How near the mix is to the target, in words. */
enum class Nearness { EMPTY, FAR, WARMER, CLOSE, VERY_CLOSE, MATCH }

/**
 * A round of Color mixer: three [targets] to mix one after another, [done] of them mixed so far, and the [bowl] of
 * the one being mixed now. Scoops are unlimited and nothing is ever wrong: the bowl can be emptied any time, and
 * [hint] always knows a way there. The state is immutable; every move returns the next one.
 */
data class ColorMixer(
    val targets: List<MixTarget>,
    val done: Int = 0,
    val bowl: Scoops = Scoops(),
    /** Scoops added since the last match or empty. */
    val scoops: Int = 0,
) {
    val isDone: Boolean get() = done == targets.size

    /** The color being mixed now, or null once all are mixed. */
    val target: MixTarget? get() = targets.getOrNull(done)

    /** How near the bowl is to [target], 0 (far off, or empty) to 1 (spot on). */
    val closeness: Float get() = target?.let { closeness(bowl, it) } ?: 0f

    val nearness: Nearness
        get() {
            if (bowl.isEmpty) return Nearness.EMPTY
            val t = target ?: return Nearness.MATCH
            val d = distance(bowl, t)
            return when {
                d <= MATCH -> Nearness.MATCH
                d <= 0.10f -> Nearness.VERY_CLOSE
                d <= 0.17f -> Nearness.CLOSE
                d <= 0.28f -> Nearness.WARMER
                else -> Nearness.FAR
            }
        }

    /** Whether the bowl is near enough the target to count. */
    val isMatch: Boolean get() = nearness == Nearness.MATCH

    /** The round after one scoop of [ink]. Does nothing once every color is mixed. */
    fun add(ink: Ink): ColorMixer = if (isDone) this else copy(bowl = bowl + ink, scoops = scoops + 1)

    /** The round with the bowl emptied. */
    fun empty(): ColorMixer = if (isDone || bowl.isEmpty) this else copy(bowl = Scoops(), scoops = 0)

    /** The round after the matching bowl is poured off: on to the next target with an empty bowl. */
    fun next(): ColorMixer = if (!isMatch || isDone) this else copy(done = done + 1, bowl = Scoops(), scoops = 0)

    /**
     * The next scoop that leads to the target, or null when the bowl holds an ink the target has none of and the
     * way there is to empty it. Following the hints from any bowl reaches a match in a few scoops.
     */
    fun hint(): Ink? {
        val recipe = target?.recipe ?: return null
        if (Ink.entries.any { bowl[it] > 0 && recipe[it] == 0 }) return null
        // The smallest batch of the recipe that holds what is in the bowl already.
        val batch = Ink.entries.filter { recipe[it] > 0 }.maxOf { ceil(bowl[it].toFloat() / recipe[it]).toInt() }.coerceAtLeast(1)
        return Ink.entries.firstOrNull { bowl[it] < recipe[it] * batch }
    }

    companion object {
        /** The farthest a mix may be from its target, in OKLab, and still count. Generous on purpose. */
        const val MATCH = 0.06f

        /** The distance at which the closeness meter reads zero. */
        private const val FAR_OFF = 0.45f

        /** Scoops before the game starts to show [hint]s. */
        const val HINT_AFTER = 5

        fun distance(bowl: Scoops, target: MixTarget): Float = bowl.color?.let { Lab.of(it).distance(target.lab) } ?: Float.MAX_VALUE

        fun closeness(bowl: Scoops, target: MixTarget): Float =
            if (bowl.isEmpty) 0f else (1f - distance(bowl, target) / FAR_OFF).coerceIn(0f, 1f)

        /**
         * A new round in [arena]: three of its colors, the same for the same [seed], easiest (fewest scoops) first.
         * Arenas without a Color mixer get the Sea Floor's.
         */
        fun start(arena: Arena, seed: Int): ColorMixer {
            val list = targetsOf(arena)
            val picked = list.shuffled(Random(seed)).take(3).sortedBy { it.recipe.total }
            return ColorMixer(picked)
        }

        fun targetsOf(arena: Arena): List<MixTarget> = if (arena == Arena.BUILDING_SITE) siteColors else seaColors

        /** The octopus's inks: the colors of the reef. */
        val seaColors = listOf(
            MixTarget("Sea green", Scoops(yellow = 1, blue = 1)),
            MixTarget("Coral", Scoops(red = 2, white = 1)),
            MixTarget("Lavender", Scoops(red = 1, blue = 1, white = 1)),
            MixTarget("Lagoon blue", Scoops(blue = 1, white = 1)),
            MixTarget("Sea-urchin purple", Scoops(red = 1, blue = 1)),
            MixTarget("Kelp", Scoops(yellow = 2, blue = 1)),
            MixTarget("Deep teal", Scoops(yellow = 1, blue = 2)),
        )

        /** The cement mixer's colors: the paints, bricks and stones of the site. */
        val siteColors = listOf(
            MixTarget("Safety orange", Scoops(red = 1, yellow = 1)),
            MixTarget("Brick red", Scoops(red = 2, yellow = 1, blue = 1)),
            MixTarget("Sandstone", Scoops(yellow = 1, red = 1, white = 2)),
            MixTarget("Hard-hat yellow", Scoops(yellow = 2, red = 1)),
            MixTarget("Clay", Scoops(red = 1, yellow = 1, blue = 1)),
            MixTarget("Concrete", Scoops(red = 1, yellow = 1, blue = 1, white = 2)),
            MixTarget("Pipe green", Scoops(yellow = 1, blue = 1, white = 1)),
        )
    }
}
