package io.colorsand.ui.hud

import androidx.compose.foundation.Canvas
import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.size
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.Path
import androidx.compose.ui.graphics.StrokeJoin
import androidx.compose.ui.graphics.drawscope.DrawScope
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.translate
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.dp
import io.colorsand.core.Stars
import kotlin.math.PI
import kotlin.math.cos
import kotlin.math.sin

/** Gold of an earned star, top to bottom, and its outline. */
private val GoldTop = Color(0xFFFFF2A0)
private val Gold = Color(0xFFFFC52E)
private val GoldDeep = Color(0xFFE88A12)
private val GoldEdge = Color(0xFFB2600A)

/** A plump five-pointed star around [center] whose points reach [radius]. */
fun starPath(center: Offset, radius: Float): Path = Path().apply {
    val inner = radius * 0.5f
    for (i in 0 until 10) {
        val r = if (i % 2 == 0) radius else inner
        val a = -PI / 2 + i * PI / 5
        val p = Offset(center.x + (r * cos(a)).toFloat(), center.y + (r * sin(a)).toFloat())
        if (i == 0) moveTo(p.x, p.y) else lineTo(p.x, p.y)
    }
    close()
}

/**
 * Draws one star filling this scope: shiny gold when [earned], otherwise an empty slot in [emptyColor].
 * The rounded outline keeps the points soft, like a sticker.
 */
fun DrawScope.drawStar(earned: Boolean, emptyColor: Color) {
    val r = size.minDimension / 2 * 0.9f
    val path = starPath(center, r)
    val edge = Stroke(r * 0.2f, join = StrokeJoin.Round)
    if (earned) {
        translate(top = r * 0.1f) { drawPath(path, Color.Black.copy(alpha = 0.22f), style = edge) }
        drawPath(path, GoldEdge, style = edge)
        drawPath(path, Brush.verticalGradient(listOf(GoldTop, Gold, GoldDeep), center.y - r, center.y + r))
        // A small shine on the upper left point.
        drawCircle(Color.White.copy(alpha = 0.7f), r * 0.13f, Offset(center.x - r * 0.25f, center.y - r * 0.3f))
    } else {
        drawPath(path, emptyColor.copy(alpha = emptyColor.alpha * 0.55f), style = edge)
        drawPath(path, emptyColor.copy(alpha = emptyColor.alpha * 0.3f))
    }
}

/** [earned] of three stars in a row, each [size] wide. */
@Composable
fun StarRow(earned: Int, emptyColor: Color, modifier: Modifier = Modifier, size: Dp = 14.dp, gap: Dp = 1.dp) {
    Row(modifier, horizontalArrangement = Arrangement.spacedBy(gap)) {
        repeat(Stars.MAX) { i ->
            Canvas(Modifier.size(size)) { drawStar(i < earned, emptyColor) }
        }
    }
}
