package io.colorsand.core

/** What [GameSession.hint] suggests. */
sealed interface Hint {
    /** Make this pour next. */
    data class Pour(val move: Move) : Hint

    /** The level is already solved. */
    data object Solved : Hint

    /** The level can no longer be won from here; the player needs to undo or restart. */
    data object DeadEnd : Hint

    /** The solver gave up before finding a way forward. */
    data object Unknown : Hint
}

/**
 * One play-through of a [Level]: the current board, the move history and undo.
 *
 * This is the only mutable type in the core; frontends hold one per level being played.
 */
class GameSession(val level: Level) {
    private val history = ArrayDeque<Board>()
    private val moveLog = ArrayDeque<Move>()

    // The solution behind the last hint: planBoards[i] is the board on which planMoves[i] is played.
    private var planBoards: List<Board> = emptyList()
    private var planMoves: List<Move> = emptyList()

    var board: Board = level.board
        private set

    val moves: List<Move> get() = moveLog.toList()
    val moveCount: Int get() = moveLog.size
    val canUndo: Boolean get() = history.isNotEmpty()
    val isSolved: Boolean get() = board.isSolved

    /**
     * True when no pour is possible at all. A board can also be lost while pours remain;
     * [hint] reports that as [Hint.DeadEnd].
     */
    val isStuck: Boolean get() = !isSolved && board.legalMoves().isEmpty()

    /** Pours from tube [from] into tube [to]. Returns the move made, or null if the pour is not allowed. */
    fun pour(from: Int, to: Int): Move? {
        if (isSolved) return null
        val (next, move) = board.pour(from, to) ?: return null
        history.addLast(board)
        moveLog.addLast(move)
        board = next
        return move
    }

    /** Takes back the last pour. Returns false if there was nothing to undo. */
    fun undo(): Boolean {
        val previous = history.removeLastOrNull() ?: return false
        moveLog.removeLast()
        board = previous
        return true
    }

    /** Starts the level over. This clears the history, so a restart cannot be undone. */
    fun restart() {
        history.clear()
        moveLog.clear()
        board = level.board
    }

    /**
     * Suggests the next pour. Hints follow one stored solution for as long as the player stays on it
     * (or undoes back onto it), so following hints always reaches the end. Leaving the path plans anew.
     *
     * Plans are near-shortest ([Planner]), so hints take the direct route a player would; when that search
     * runs out of budget, the faster [Solver] still finds a way or proves there is none.
     */
    fun hint(): Hint {
        if (isSolved) return Hint.Solved
        val step = planBoards.indexOf(board)
        if (step >= 0) return Hint.Pour(planMoves[step])
        val moves = Planner.plan(board) ?: when (val result = Solver.search(board)) {
            is SolveResult.Solution -> result.moves
            SolveResult.Unsolvable -> return Hint.DeadEnd
            SolveResult.GaveUp -> return Hint.Unknown
        }
        planMoves = moves
        planBoards = moves.runningFold(board) { b, m -> b.pour(m.from, m.to)!!.first }.dropLast(1)
        return Hint.Pour(moves.first())
    }
}
