// The drawing of the sand art bottle: its base and the keepsake beside it, the glass, the bands of sand with their
// grains, the funnel and its stream, and the cork and shine once it is full. Sizes follow a [BottleLayout].

/** What moves in the bottle this frame: the pour, the cork and the finishing turn. */
internal class BottleMotion(
    /** Seconds since the game began, for the stream's grains and the glints. */
    val time: Float,
    /** Where the stream lands, 0 to 1 across the bottle. */
    val at: Float,
    /** How strongly sand is running, 0 (none) to 1. */
    val stream: Float,
    /** The cork dropping into the neck, 0 to 1 (with a little overshoot). */
    val cork: Float,
    /** The finishing turn and shine, 0 to 1. */
    val turn: Float,
)

/** The whole bottle at this frame. */
internal fun DrawScope.drawSandBottle(arena: Arena, look: SandArtLook, grade: SceneGrade, l: BottleLayout, art: SandArt, color: Int, m: BottleMotion) {
    drawBase(look, l)
    drawSideKeepsake(arena, look, grade, l, m.time)
    // The turn: a gentle rock on the base, settling as it ends.
    val tilt = if (m.turn > 0f) sin(m.turn * 2 * PI.toFloat() * 1.5f) * 3.2f * (1f - m.turn) else 0f
    rotate(tilt, Offset(l.cx, l.bottom)) {
        val outer = bottlePath(l, 0f)
        val inner = bottlePath(l, l.glassWall)
        // The back of the glass, seen through the bottle.
        drawPath(outer, look.glass.copy(alpha = 0.22f))
        drawPath(inner, Brush.horizontalGradient(listOf(Color.White.copy(alpha = 0.22f), look.glass.copy(alpha = 0.18f), Color.Black.copy(alpha = 0.06f)), l.left, l.right))
        clipPath(inner) {
            drawSand(look, l, art)
            if (m.stream > 0.01f && m.cork <= 0f) drawStream(look.jars[color], l, art, m)
            // The bottle is round: the sand darkens toward the sides of the glass.
            drawRect(
                Brush.horizontalGradient(
                    0f to Color.Black.copy(alpha = 0.2f), 0.18f to Color.Transparent, 0.62f to Color.Transparent, 1f to Color.Black.copy(alpha = 0.26f),
                    startX = l.left, endX = l.right,
                ),
                Offset(l.left, l.top), Size(l.right - l.left, l.bottom - l.top),
            )
        }
        // The cork sits in the neck, behind the glass of its lip and under the cord.
        if (m.cork > 0f) drawCork(l, m.cork)
        drawGlassFront(look, l, outer, inner)
        if (m.turn > 0f && m.turn < 1f) drawShine(l, outer, m.turn)
        drawTie(look, l, m.time)
    }
    if (m.cork <= 0f) drawFunnel(look.jars[color], l, m)
    if (m.turn > 0f) drawFinishSparkles(l, m)
}

/** The outline of the bottle, [inset] inside its glass: a narrow neck, a rounded shoulder and a round-cornered body. */
private fun bottlePath(l: BottleLayout, inset: Float): Path = Path().apply {
    val nl = l.cx - l.neckWidth / 2 + inset
    val nr = l.cx + l.neckWidth / 2 - inset
    val bl = l.cx - l.bodyWidth / 2 + inset
    val br = l.cx + l.bodyWidth / 2 - inset
    val neckBottom = l.top + l.neckHeight
    val bottom = l.bottom - inset
    val r = (l.corner - inset).coerceAtLeast(1f)
    moveTo(nl, l.top + inset * 0.2f)
    lineTo(nl, neckBottom)
    cubicTo(nl, neckBottom + l.shoulderHeight * 0.5f, bl, neckBottom + l.shoulderHeight * 0.35f, bl, l.shoulder)
    lineTo(bl, bottom - r)
    quadraticBezierTo(bl, bottom, bl + r, bottom)
    lineTo(br - r, bottom)
    quadraticBezierTo(br, bottom, br, bottom - r)
    lineTo(br, l.shoulder)
    cubicTo(br, neckBottom + l.shoulderHeight * 0.35f, nr, neckBottom + l.shoulderHeight * 0.5f, nr, neckBottom)
    lineTo(nr, l.top + inset * 0.2f)
    close()
}

/** The bands of sand, top band first so each older one covers the lower part of the newer ones above it. */
private fun DrawScope.drawSand(look: SandArtLook, l: BottleLayout, art: SandArt) {
    val n = art.columns
    // Bands of one color in a row alternate a shade, so a new press of the same jar still shows a faint seam.
    val tones = IntArray(art.layers.size)
    for (k in 1 until art.layers.size) if (art.layers[k].color == art.layers[k - 1].color) tones[k] = tones[k - 1] + 1
    val grainR = (l.right - l.left) / n * 0.2f
    val tops = art.layers.map { smooth(it.top) }
    for (k in art.layers.indices.reversed()) {
        val layer = art.layers[k]
        val jar = look.jars[layer.color]
        val surface = surfacePath(l, tops[k], n)
        val band = Path().apply {
            addPath(surface)
            lineTo(l.right + l.glassWall, l.floor + l.glassWall * 2)
            lineTo(l.left - l.glassWall, l.floor + l.glassWall * 2)
            close()
        }
        drawPath(band, jar.band(tones[k]))
        // Grains in the band: dark and light flecks on a fixed grid, so they stay put while the band grows.
        val below = if (k > 0) tops[k - 1] else null
        val dark = ArrayList<Offset>()
        val light = ArrayList<Offset>()
        for (c in 0 until n) {
            val lo = below?.get(c) ?: 0f
            val hi = tops[k][c]
            if (hi - lo < GRAIN_STEP * 0.3f) continue
            var j = floor(lo / GRAIN_STEP).toInt()
            while (j * GRAIN_STEP <= hi) {
                val seed = c * 977 + j * 131 + k * 7
                val h = (j + noise(seed)) * GRAIN_STEP
                if (h in lo..hi) {
                    val p = Offset(l.x(c + noise(seed + 3) - 0.5f, n), l.y(h))
                    val pick = noise(seed + 11)
                    if (pick < 0.42f) dark += p else if (pick > 0.7f) light += p
                }
                j++
            }
        }
        drawPoints(dark, PointMode.Points, jar.dark.copy(alpha = 0.7f), strokeWidth = grainR * 1.1f, cap = StrokeCap.Round)
        drawPoints(light, PointMode.Points, jar.light.copy(alpha = 0.85f), strokeWidth = grainR, cap = StrokeCap.Round)
        // The seam on top of the band: a fine dark line with a lit edge just under it.
        drawPath(surface, jar.dark.copy(alpha = 0.45f), style = Stroke(grainR * 0.9f))
        translate(0f, grainR * 1.1f) { drawPath(surface, jar.light.copy(alpha = 0.35f), style = Stroke(grainR * 0.7f)) }
    }
}

/**
 * [top] softened for drawing, so single columns don't show as spikes: a small weighted average over each column's
 * neighbors. The weights are all positive, so a band drawn this way never crosses the one under it.
 */
private fun smooth(top: List<Float>): List<Float> = List(top.size) { c ->
    var sum = 0f
    var weight = 0f
    for (d in -2..2) {
        val i = (c + d).coerceIn(0, top.size - 1)
        val w = 3f - kotlin.math.abs(d)
        sum += top[i] * w
        weight += w
    }
    sum / weight
}

/** The smooth top of a band whose column heights are [top], from wall to wall (an open path, left to right). */
private fun surfacePath(l: BottleLayout, top: List<Float>, n: Int): Path = Path().apply {
    moveTo(l.left - l.glassWall, l.y(top[0]))
    lineTo(l.x(0f, n), l.y(top[0]))
    for (c in 0 until n - 1) {
        val x0 = l.x(c.toFloat(), n)
        val x1 = l.x(c + 1f, n)
        quadraticBezierTo(x0, l.y(top[c]), (x0 + x1) / 2, l.y((top[c] + top[c + 1]) / 2))
    }
    lineTo(l.x(n - 1f, n), l.y(top[n - 1]))
    lineTo(l.right + l.glassWall, l.y(top[n - 1]))
}

/** Sand running from the funnel's spout down to where it lands, grains tumbling along it and a puff where it lands. */
private fun DrawScope.drawStream(jar: SandColor, l: BottleLayout, art: SandArt, m: BottleMotion) {
    val n = art.columns
    val tip = l.spout(m.at)
    val c = (m.at * (n - 1)).coerceIn(0f, n - 1f)
    val land = Offset(l.x(c, n), l.y(smooth(art.surface)[c.toInt()]))
    val w = (l.right - l.left) * 0.03f * m.stream
    val wobble = sin(m.time * 23f) * w * 0.3f
    drawLine(jar.base.copy(alpha = 0.9f * m.stream), tip, land + Offset(wobble, 0f), w, StrokeCap.Round)
    drawLine(jar.light.copy(alpha = 0.6f * m.stream), tip + Offset(-w * 0.2f, 0f), land + Offset(wobble - w * 0.2f, 0f), w * 0.35f, StrokeCap.Round)
    // Grains falling along the stream, a few loose ones beside it.
    val grains = ArrayList<Offset>()
    for (k in 0 until 14) {
        val v = m.time * 2.6f + k / 14f
        val f = v - floor(v)
        val side = (noise(k * 13) - 0.5f) * w * 2.2f
        grains += Offset(tip.x + (land.x - tip.x) * f + side, tip.y + (land.y - tip.y) * f)
    }
    drawPoints(grains, PointMode.Points, jar.dark.copy(alpha = 0.8f * m.stream), strokeWidth = w * 0.55f, cap = StrokeCap.Round)
    // A little puff where the stream lands, grains hopping out to the sides.
    for (k in 0 until 6) {
        val v = m.time * 3.4f + k / 6f
        val f = v - floor(v)
        val dir = if (k % 2 == 0) 1f else -1f
        val p = land + Offset(dir * (0.4f + noise(k)) * w * 3.2f * f, -w * 2.2f * f * (1f - f) * 4f)
        drawCircle(jar.base.copy(alpha = (1f - f) * m.stream), w * 0.32f, p)
    }
    drawOval(jar.light.copy(alpha = 0.35f * m.stream), land - Offset(w * 2.2f, w * 0.6f), Size(w * 4.4f, w * 1.2f))
}

/** The glass over the sand: its rim, the lip at the mouth, the long highlight down the left and a glint on the right. */
private fun DrawScope.drawGlassFront(look: SandArtLook, l: BottleLayout, outer: Path, inner: Path) {
    val rim = lerp(look.glass, Color(0xFF2E5560), 0.45f)
    drawPath(outer, rim.copy(alpha = 0.55f), style = Stroke(l.glassWall * 0.55f))
    drawPath(inner, Color.White.copy(alpha = 0.35f), style = Stroke(l.glassWall * 0.3f))
    val bh = l.bottom - l.shoulder
    // The long highlight down the left side, and a slimmer one on the right.
    drawRoundRect(
        Brush.verticalGradient(listOf(Color.White.copy(alpha = 0.0f), Color.White.copy(alpha = 0.55f), Color.White.copy(alpha = 0.12f)), l.shoulder, l.bottom),
        Offset(l.left + l.glassWall * 0.9f, l.shoulder + bh * 0.04f), Size(l.glassWall * 1.5f, bh * 0.84f), CornerRadius(l.glassWall),
    )
    drawRoundRect(
        Color.White.copy(alpha = 0.22f),
        Offset(l.left + l.glassWall * 3.2f, l.shoulder + bh * 0.1f), Size(l.glassWall * 0.55f, bh * 0.5f), CornerRadius(l.glassWall),
    )
    drawRoundRect(
        Color.White.copy(alpha = 0.3f),
        Offset(l.right - l.glassWall * 2.2f, l.shoulder + bh * 0.18f), Size(l.glassWall * 0.7f, bh * 0.28f), CornerRadius(l.glassWall),
    )
    // The shoulder catches the light.
    val neckBottom = l.top + l.neckHeight
    drawPath(
        Path().apply {
            moveTo(l.cx - l.neckWidth / 2 - l.glassWall * 0.2f, neckBottom + l.shoulderHeight * 0.18f)
            quadraticBezierTo(l.cx - l.bodyWidth * 0.42f, neckBottom + l.shoulderHeight * 0.38f, l.cx - l.bodyWidth * 0.43f, l.shoulder + l.shoulderHeight * 0.2f)
        },
        Color.White.copy(alpha = 0.55f),
        style = Stroke(l.glassWall * 0.8f, cap = StrokeCap.Round),
    )
    // The lip round the mouth.
    val lip = Rect(l.cx - l.neckWidth / 2 - l.glassWall * 0.6f, l.top - l.glassWall * 0.4f, l.cx + l.neckWidth / 2 + l.glassWall * 0.6f, l.top + l.glassWall * 1.3f)
    drawRoundRect(look.glass.copy(alpha = 0.75f), lip.topLeft, lip.size, CornerRadius(l.glassWall * 0.8f))
    drawRoundRect(rim.copy(alpha = 0.55f), lip.topLeft, lip.size, CornerRadius(l.glassWall * 0.8f), style = Stroke(l.glassWall * 0.4f))
    drawRoundRect(Color.White.copy(alpha = 0.7f), lip.topLeft + Offset(l.glassWall * 0.6f, l.glassWall * 0.3f), Size(lip.width * 0.4f, l.glassWall * 0.35f), CornerRadius(l.glassWall))
    // The bottom of the glass, thick and bright.
    drawRoundRect(Color.White.copy(alpha = 0.3f), Offset(l.left + l.corner * 0.4f, l.bottom - l.glassWall * 1.1f), Size(l.right - l.left - l.corner * 0.8f, l.glassWall * 0.5f), CornerRadius(l.glassWall))
}

/** A band of light sweeping across the glass as the bottle turns, at [turn] (0 to 1). */
private fun DrawScope.drawShine(l: BottleLayout, outer: Path, turn: Float) {
    clipPath(outer) {
        val x = l.cx - l.bodyWidth + turn * l.bodyWidth * 2.2f
        val band = l.bodyWidth * 0.22f
        drawRect(
            Brush.linearGradient(
                listOf(Color.White.copy(alpha = 0f), Color.White.copy(alpha = 0.55f), Color.White.copy(alpha = 0f)),
                start = Offset(x - band, l.top), end = Offset(x + band, l.top + band * 0.6f),
            ),
            Offset(l.cx - l.bodyWidth, l.top - l.glassWall), Size(l.bodyWidth * 2, l.bottom - l.top + l.glassWall * 2),
        )
    }
}

/** The cord tied round the neck, and its charm: a pink scallop shell on the Beach, a golden tassel in the Desert. */
private fun DrawScope.drawTie(look: SandArtLook, l: BottleLayout, t: Float) {
    val y = l.top + l.neckHeight * 0.62f
    val w = l.neckWidth + l.glassWall * 0.6f
    val cord = l.glassWall * 1.1f
    drawRoundRect(look.tie, Offset(l.cx - w / 2, y - cord / 2), Size(w, cord), CornerRadius(cord / 2))
    drawRoundRect(look.tieLight, Offset(l.cx - w / 2 + cord * 0.4f, y - cord * 0.4f), Size(w * 0.5f, cord * 0.3f), CornerRadius(cord / 2))
    // The knot on the right, the charm hanging from it on two short ends and swaying a little.
    val knot = Offset(l.cx + w / 2 - cord * 0.3f, y)
    drawCircle(look.tie, cord * 0.85f, knot)
    val sway = sin(t * 1.6f) * 6f
    rotate(sway, knot) {
        val end = knot + Offset(cord * 0.5f, cord * 4.2f)
        drawLine(look.tie, knot, end, cord * 0.5f, StrokeCap.Round)
        drawLine(look.tie, knot, end + Offset(-cord * 1.2f, -cord * 0.6f), cord * 0.45f, StrokeCap.Round)
        val s = cord * 2.1f
        when (look.base) {
            SandBase.MOUND -> {
                // A little scallop shell: a fan with ribs.
                val c = end + Offset(0f, s * 0.8f)
                val fan = Path().apply {
                    moveTo(c.x, c.y + s * 0.15f)
                    lineTo(c.x - s, c.y - s * 0.55f)
                    quadraticBezierTo(c.x, c.y - s * 1.55f, c.x + s, c.y - s * 0.55f)
                    close()
                }
                translate(0f, s * 0.2f) {
                    drawPath(fan, look.charm)
                    for (k in -2..2) drawLine(lerp(look.charm, Color(0xFFB4504E), 0.4f), Offset(c.x, c.y + s * 0.1f), Offset(c.x + k * s * 0.42f, c.y - s * 0.75f - (2 - kotlin.math.abs(k)) * s * 0.14f), s * 0.09f, StrokeCap.Round)
                    drawCircle(lerp(look.charm, Color.White, 0.5f), s * 0.18f, Offset(c.x, c.y + s * 0.05f))
                }
            }
            SandBase.RUG -> {
                // A golden bead and a tassel of threads.
                drawCircle(look.charm, s * 0.45f, end + Offset(0f, s * 0.2f))
                drawCircle(Color.White.copy(alpha = 0.6f), s * 0.14f, end + Offset(-s * 0.15f, s * 0.05f))
                val top = end + Offset(0f, s * 0.6f)
                for (k in -3..3) drawLine(lerp(look.charm, look.tie, if (k % 2 == 0) 0f else 0.25f), top, top + Offset(k * s * 0.13f, s * 1.6f), s * 0.12f, StrokeCap.Round)
                drawRoundRect(look.tie, top - Offset(s * 0.35f, 0f), Size(s * 0.7f, s * 0.28f), CornerRadius(s * 0.1f))
            }
        }
    }
}

/** The cork, dropping in from above and seating itself in the mouth as [p] goes from 0 to 1. */
private fun DrawScope.drawCork(l: BottleLayout, p: Float) {
    val w = l.neckWidth * 0.84f
    val h = l.neckHeight * 0.66f
    val seat = l.top - h * 0.36f
    // It bounces as it seats, but never pushes further in than a hair.
    val y = seat - (1f - minOf(p, 1.04f)) * l.size * 0.35f
    val alpha = (p * 3f).coerceIn(0f, 1f)
    val cork = Color(0xFFC99A60).copy(alpha = alpha)
    val shade = Color(0xFF9C6F3E).copy(alpha = alpha)
    val shape = Path().apply {
        moveTo(l.cx - w / 2, y)
        lineTo(l.cx + w / 2, y)
        lineTo(l.cx + w * 0.36f, y + h)
        lineTo(l.cx - w * 0.36f, y + h)
        close()
    }
    drawPath(shape, cork)
    clipPath(shape) {
        drawRect(shade, Offset(l.cx + w * 0.2f, y), Size(w * 0.4f, h))
        for (k in 0 until 9) drawCircle(Color(0xFF7E5530).copy(alpha = 0.5f * alpha), w * (0.025f + 0.02f * noise(k + 40)), Offset(l.cx + (noise(k) - 0.5f) * w * 0.8f, y + noise(k + 20) * h))
    }
    drawOval(Color(0xFFE2BC86).copy(alpha = alpha), Offset(l.cx - w / 2, y - h * 0.12f), Size(w, h * 0.26f))
    drawOval(Color(0xFFF2D6A8).copy(alpha = alpha), Offset(l.cx - w * 0.3f, y - h * 0.06f), Size(w * 0.35f, h * 0.1f))
}

/** The funnel held over the mouth, sliding with the pour and holding a little of the chosen sand. */
private fun DrawScope.drawFunnel(jar: SandColor, l: BottleLayout, m: BottleMotion) {
    val tip = l.spout(m.at)
    val cupW = l.neckWidth * 1.7f
    val cupTop = l.top - l.size * 0.105f
    val coneBottom = l.top - l.neckHeight * 0.05f
    val spoutW = l.neckWidth * 0.18f
    val metal = Color(0xFFDCE3E8)
    val metalDark = Color(0xFF8E9AA4)
    // Its shadow in the neck.
    val cone = Path().apply {
        moveTo(tip.x - cupW / 2, cupTop)
        lineTo(tip.x + cupW / 2, cupTop)
        lineTo(tip.x + spoutW / 2, coneBottom)
        lineTo(tip.x - spoutW / 2, coneBottom)
        close()
    }
    drawRect(Brush.horizontalGradient(listOf(metalDark, metal, metalDark), tip.x - spoutW / 2, tip.x + spoutW / 2), Offset(tip.x - spoutW / 2, coneBottom - 1f), Size(spoutW, tip.y - coneBottom + 1f))
    drawPath(cone, Brush.horizontalGradient(listOf(metalDark, metal, Color.White, metal, metalDark), tip.x - cupW / 2, tip.x + cupW / 2))
    // The sand in it, heaped, sinking a little while it runs.
    val level = 0.35f + 0.08f * (1f - m.stream)
    val sandY = cupTop + (coneBottom - cupTop) * level
    val half = cupW / 2 * (1f - level) + spoutW / 2 * level
    clipPath(cone) {
        drawOval(jar.base, Offset(tip.x - half, sandY - (coneBottom - cupTop) * 0.12f), Size(half * 2, (coneBottom - cupTop) * 0.3f))
        drawRect(jar.base, Offset(tip.x - half, sandY), Size(half * 2, coneBottom - sandY))
        drawOval(jar.light.copy(alpha = 0.6f), Offset(tip.x - half * 0.6f, sandY - (coneBottom - cupTop) * 0.08f), Size(half * 0.8f, (coneBottom - cupTop) * 0.1f))
    }
    drawPath(cone, metalDark.copy(alpha = 0.8f), style = Stroke(l.glassWall * 0.35f))
    // The rolled rim, catching the light.
    drawRoundRect(metal, Offset(tip.x - cupW / 2 - l.glassWall * 0.3f, cupTop - l.glassWall * 0.5f), Size(cupW + l.glassWall * 0.6f, l.glassWall), CornerRadius(l.glassWall * 0.5f))
    drawRoundRect(Color.White.copy(alpha = 0.8f), Offset(tip.x - cupW * 0.38f, cupTop - l.glassWall * 0.35f), Size(cupW * 0.35f, l.glassWall * 0.3f), CornerRadius(l.glassWall))
}

/** What the bottle stands on: a sand mound with a pebble and a tiny starfish, or a woven rug with fringes. */
private fun DrawScope.drawBase(look: SandArtLook, l: BottleLayout) {
    val w = l.bodyWidth * if (look.base == SandBase.RUG) 1.7f else 1.9f
    val h = l.size * if (look.base == SandBase.RUG) 0.085f else 0.07f
    val c = Offset(l.cx, l.bottom + h * 0.15f)
    val colors = look.baseColors
    when (look.base) {
        SandBase.MOUND -> {
            drawOval(Color.Black.copy(alpha = 0.12f), c - Offset(w / 2, h * 0.32f), Size(w, h * 0.95f))
            drawOval(Brush.verticalGradient(listOf(colors[0], colors[1]), c.y - h * 0.5f, c.y + h * 0.5f), c - Offset(w / 2 * 0.94f, h * 0.5f), Size(w * 0.94f, h))
            drawOval(colors[3].copy(alpha = 0.35f), c - Offset(w * 0.3f, h * 0.42f), Size(w * 0.34f, h * 0.22f))
            for (k in 0 until 14) drawCircle(colors[2].copy(alpha = 0.7f), h * 0.04f, c + Offset((noise(k + 60) - 0.5f) * w * 0.8f, (noise(k + 80) - 0.4f) * h * 0.6f))
            drawOval(Color(0xFFB9C3C6), c + Offset(-w * 0.36f, -h * 0.05f), Size(h * 0.42f, h * 0.26f))
        }
        SandBase.RUG -> {
            val top = c.y - h * 0.35f
            val bottom = c.y + h * 0.45f
            val inset = w * 0.08f
            val rug = Path().apply {
                moveTo(c.x - w / 2 + inset, top)
                lineTo(c.x + w / 2 - inset, top)
                lineTo(c.x + w / 2, bottom)
                lineTo(c.x - w / 2, bottom)
                close()
            }
            drawPath(Path().apply { addPath(rug, Offset(0f, h * 0.18f)) }, Color.Black.copy(alpha = 0.16f))
            drawPath(rug, colors[0])
            clipPath(rug) {
                val bandH = (bottom - top) / 7f
                drawRect(colors[3], Offset(c.x - w, top), Size(w * 2, bandH))
                drawRect(colors[1], Offset(c.x - w, top + bandH * 2), Size(w * 2, bandH * 0.6f))
                drawRect(colors[2], Offset(c.x - w, top + bandH * 3.3f), Size(w * 2, bandH * 0.9f))
                drawRect(colors[1], Offset(c.x - w, top + bandH * 4.6f), Size(w * 2, bandH * 0.6f))
                drawRect(colors[3], Offset(c.x - w, bottom - bandH), Size(w * 2, bandH))
                // Little diamonds woven along the middle band.
                for (k in -4..4) {
                    val d = Offset(c.x + k * w * 0.1f, top + bandH * 3.75f)
                    drawPath(Path().apply { moveTo(d.x, d.y - bandH * 0.4f); lineTo(d.x + bandH * 0.4f, d.y); lineTo(d.x, d.y + bandH * 0.4f); lineTo(d.x - bandH * 0.4f, d.y); close() }, colors[1])
                }
            }
            // Fringes at both ends.
            for (k in 0 until 4) {
                val y = top + (bottom - top) * (0.15f + k * 0.23f)
                val dx = inset * (1f - (y - top) / (bottom - top))
                drawLine(colors[1], Offset(c.x - w / 2 + dx, y), Offset(c.x - w / 2 + dx - h * 0.3f, y), h * 0.06f, StrokeCap.Round)
                drawLine(colors[1], Offset(c.x + w / 2 - dx, y), Offset(c.x + w / 2 - dx + h * 0.3f, y), h * 0.06f, StrokeCap.Round)
            }
        }
    }
}

/** The arena's keepsake standing beside the bottle, on the right, as tall as about a third of it. */
private fun DrawScope.drawSideKeepsake(arena: Arena, look: SandArtLook, grade: SceneGrade, l: BottleLayout, t: Float) {
    // Right of the bottle where there is room for it, else partly in front of the bottle's foot.
    val s = minOf(l.size * 0.4f, maxOf(l.size * 0.26f, l.width - l.cx - l.bodyWidth / 2))
    val x = minOf(l.cx + l.bodyWidth / 2 - s * 0.12f, l.width - s)
    val unit = s / 100f
    translate(x, l.bottom + l.size * 0.035f - s) {
        scale(unit, unit, Offset.Zero) {
            drawKeepsake(if (arena == Arena.DESERT) Arena.DESERT else Arena.BEACH, look.stage, (t / 120f) % 1f, grade)
        }
    }
}

/** Sparkles twinkling round the finished bottle. */
private fun DrawScope.drawFinishSparkles(l: BottleLayout, m: BottleMotion) {
    val spots = listOf(-0.62f to 0.25f, 0.6f to 0.42f, -0.5f to 0.7f, 0.18f to 0.05f, 0.66f to 0.85f)
    for ((i, spot) in spots.withIndex()) {
        val (dx, dy) = spot
        val phase = sin((m.time * 1.4f + i * 0.37f) * 2 * PI.toFloat())
        val a = (0.5f + 0.5f * phase) * minOf(1f, m.turn * 3f)
        val c = Offset(l.cx + dx * l.bodyWidth, l.top + dy * l.size)
        drawGlow(c, l.glassWall * 4f, Color(0xFFFFF2B0).copy(alpha = 0.5f * a))
        drawSparkle(c, l.glassWall * (1.4f + 0.6f * a), Color.White.copy(alpha = a))
    }
}

/** The height of one row of grains, in bottle heights. */
private const val GRAIN_STEP = 0.016f
