// The cards of Keepsake memory, each drawn filling its scope: the backs (a woven rug tile in the tent, a riveted
// metal plate on Mars), the faces with their keepsake, and the backdrop they lie on.

/** The corner radius of a card [width] wide. */
private fun cornerOf(width: Float) = width * 0.11f

private fun DrawScope.cardPath(): Path = Path().apply {
    addRoundRect(RoundRect(Rect(Offset.Zero, size), CornerRadius(cornerOf(size.width))))
}

/** The soft shadow a card casts on the backdrop, [lift] (0 to 1) higher off it while hopping. */
internal fun DrawScope.drawCardShadow(lift: Float) {
    val w = size.width
    val h = size.height
    val spread = 1f + 0.08f * lift
    drawRoundRect(
        Color.Black.copy(alpha = 0.2f * (1f - 0.4f * lift)),
        Offset(w * (1f - spread) / 2, h * (0.05f + 0.06f * lift)),
        Size(w * spread, h),
        CornerRadius(cornerOf(w)),
    )
}

/** The back of a card, face down. */
internal fun DrawScope.drawCardBack(look: MemoryLook, t: Float, index: Int) = when (look.style) {
    MemoryStyle.RUG -> rugBack(look)
    MemoryStyle.METAL -> metalBack(look, t, index)
}

/** The face of a card with [face] on it, at scene clock [t]. */
internal fun DrawScope.drawCardFace(look: MemoryLook, face: MemoryFace, grade: SceneGrade, t: Float) {
    when (look.style) {
        MemoryStyle.RUG -> linenFace(look)
        MemoryStyle.METAL -> glassFace(look, t)
    }
    val unit = minOf(size.width, size.height * 0.85f) * 0.8f / 100f
    translate(size.width / 2 - 50f * unit, size.height * 0.54f - 54f * unit) {
        scale(unit, unit, Offset.Zero) { drawKeepsake(face.arena, face.stage, t, grade) }
    }
}

/** A soft glow around a found pair, breathing with [pulse] (0 to 1). Drawn behind the card. */
internal fun DrawScope.drawPairGlow(look: MemoryLook, pulse: Float) {
    val r = size.maxDimension * (0.85f + 0.08f * pulse)
    drawGlow(center, r, look.glow.copy(alpha = 0.8f + 0.2f * pulse))
}

/** A glowing rim on a found card's face, breathing with [pulse] (0 to 1). */
internal fun DrawScope.drawPairRim(look: MemoryLook, pulse: Float) {
    val card = cardPath()
    drawPath(card, look.glow.copy(alpha = 0.45f + 0.35f * pulse), style = Stroke(size.width * (0.07f + 0.02f * pulse)))
    drawPath(card, Color.White.copy(alpha = 0.6f), style = Stroke(size.width * 0.015f))
}

/** A ring around the card the keyboard is on. */
internal fun DrawScope.drawFocusRing(color: Color) {
    val w = size.width
    val inset = -w * 0.045f
    drawRoundRect(
        color,
        Offset(inset, inset),
        Size(size.width - 2 * inset, size.height - 2 * inset),
        CornerRadius(cornerOf(w) - inset),
        style = Stroke(w * 0.035f),
    )
}

// The tent: woven rug tiles on a striped canvas.

private fun DrawScope.rugBack(look: MemoryLook) {
    val w = size.width
    val h = size.height
    fringe(look.faceLight, w, h)
    val card = cardPath()
    drawPath(card, look.back)
    clipPath(card) {
        weave(w, h, dark = 0.1f, light = 0.05f)
        // A woven border: a dark band with a gold line inside it.
        val m = w * 0.07f
        drawRoundRect(look.backDark, Offset(m, m), Size(w - 2 * m, h - 2 * m), CornerRadius(cornerOf(w) * 0.6f), style = Stroke(w * 0.06f))
        drawRoundRect(look.backAccent, Offset(m * 1.9f, m * 1.9f), Size(w - 3.8f * m, h - 3.8f * m), CornerRadius(cornerOf(w) * 0.4f), style = Stroke(w * 0.022f))
        // A row of little stepped teeth along the top and bottom.
        val teeth = 5
        for (row in 0..1) {
            val y = if (row == 0) m * 3.1f else h - m * 3.1f
            val dir = if (row == 0) 1f else -1f
            for (k in 0 until teeth) {
                val cx = m * 2.6f + (w - 5.2f * m) * (k + 0.5f) / teeth
                val half = (w - 5.2f * m) / teeth * 0.36f
                drawPath(diamond(cx, y + dir * half * 0.5f, half, half * 0.9f), look.faceLight.copy(alpha = 0.9f))
            }
        }
        // The medallion: diamonds inside diamonds.
        val c = Offset(w / 2, h / 2)
        drawPath(diamond(c.x, c.y, w * 0.3f, h * 0.27f), look.backAccent)
        drawPath(diamond(c.x, c.y, w * 0.22f, h * 0.2f), look.backTrim)
        drawPath(diamond(c.x, c.y, w * 0.13f, h * 0.12f), look.faceLight)
        drawPath(diamond(c.x, c.y, w * 0.06f, h * 0.055f), look.back)
        // Little hooks on the medallion's sides.
        for (side in listOf(-1f, 1f)) {
            drawPath(diamond(c.x + side * w * 0.36f, c.y, w * 0.05f, h * 0.045f), look.backAccent)
            drawPath(diamond(c.x, c.y + side * h * 0.31f, w * 0.045f, h * 0.035f), look.faceLight)
        }
        // A soft sheen from the top, like light on wool.
        drawRect(Brush.verticalGradient(listOf(Color.White.copy(alpha = 0.22f), Color.Transparent), 0f, h * 0.45f))
        drawRect(Brush.verticalGradient(listOf(Color.Transparent, Color.Black.copy(alpha = 0.16f)), h * 0.6f, h))
    }
}

private fun DrawScope.linenFace(look: MemoryLook) {
    val w = size.width
    val h = size.height
    fringe(look.faceLight, w, h)
    val card = cardPath()
    drawPath(card, Brush.verticalGradient(listOf(look.faceLight, look.face)))
    clipPath(card) {
        weave(w, h, dark = 0.045f, light = 0.08f)
        val m = w * 0.07f
        drawRoundRect(look.faceEdge, Offset(m, m), Size(w - 2 * m, h - 2 * m), CornerRadius(cornerOf(w) * 0.6f), style = Stroke(w * 0.028f))
        drawRoundRect(look.backdropTrim.copy(alpha = 0.7f), Offset(m * 1.6f, m * 1.6f), Size(w - 3.2f * m, h - 3.2f * m), CornerRadius(cornerOf(w) * 0.45f), style = Stroke(w * 0.012f))
        for ((x, y) in listOf(m * 2.6f to m * 2.6f, w - m * 2.6f to m * 2.6f, m * 2.6f to h - m * 2.6f, w - m * 2.6f to h - m * 2.6f)) {
            drawPath(diamond(x, y, w * 0.04f, w * 0.04f), look.backdropTrim.copy(alpha = 0.75f))
        }
        drawRect(Brush.verticalGradient(listOf(Color.Transparent, look.faceEdge.copy(alpha = 0.16f)), h * 0.55f, h))
    }
}

/** Short woolly tassels along the top and bottom of a rug tile, peeking out past its edges. */
private fun DrawScope.fringe(color: Color, w: Float, h: Float) {
    val n = 9
    val len = h * 0.035f
    for (k in 0 until n) {
        val x = w * 0.16f + (w * 0.68f) * k / (n - 1)
        drawLine(color, Offset(x, -len), Offset(x, len), strokeWidth = w * 0.022f)
        drawLine(color, Offset(x, h - len), Offset(x, h + len), strokeWidth = w * 0.022f)
    }
}

/** The fine over-under lines of the weave. */
private fun DrawScope.weave(w: Float, h: Float, dark: Float, light: Float) {
    val step = w / 26f
    var y = step / 2
    while (y < h) {
        drawLine(Color.Black.copy(alpha = dark), Offset(0f, y), Offset(w, y), strokeWidth = step * 0.35f)
        y += step
    }
    var x = step / 2
    while (x < w) {
        drawLine(Color.White.copy(alpha = light), Offset(x, 0f), Offset(x, h), strokeWidth = step * 0.3f)
        x += step * 1.3f
    }
}

private fun diamond(cx: Float, cy: Float, rx: Float, ry: Float): Path = Path().apply {
    moveTo(cx, cy - ry)
    lineTo(cx + rx, cy)
    lineTo(cx, cy + ry)
    lineTo(cx - rx, cy)
    close()
}

// Mars: brushed metal plates with an alien on them, on a starry panel.

private fun DrawScope.metalBack(look: MemoryLook, t: Float, index: Int) {
    val w = size.width
    val h = size.height
    val card = cardPath()
    drawPath(
        card,
        Brush.linearGradient(
            0f to look.backLight,
            0.45f to look.back,
            0.7f to lerp(look.back, look.backLight, 0.5f),
            1f to look.backDark,
            start = Offset.Zero,
            end = Offset(w, h),
        ),
    )
    clipPath(card) {
        // Brushed grain.
        val step = h / 60f
        var y = 0f
        var k = 0
        while (y < h) {
            val a = if (k % 3 == 0) 0.07f else 0.035f
            drawLine((if (k % 2 == 0) Color.White else Color.Black).copy(alpha = a), Offset(0f, y), Offset(w, y), strokeWidth = step * 0.5f)
            y += step
            k++
        }
        // A sheen sweeps across now and then.
        val sweep = ((t * 40f + index * 0.083f) % 1f) * 3f - 1f
        if (sweep in -0.3f..1.3f) {
            val x = sweep * w
            drawRect(
                Brush.linearGradient(
                    listOf(Color.Transparent, Color.White.copy(alpha = 0.35f), Color.Transparent),
                    start = Offset(x - w * 0.25f, 0f),
                    end = Offset(x + w * 0.25f, h * 0.4f),
                ),
            )
        }
        // A bevelled inner plate.
        val m = w * 0.08f
        drawRoundRect(look.backDark.copy(alpha = 0.55f), Offset(m, m), Size(w - 2 * m, h - 2 * m), CornerRadius(cornerOf(w) * 0.6f), style = Stroke(w * 0.02f))
        drawRoundRect(Color.White.copy(alpha = 0.55f), Offset(m + w * 0.015f, m + w * 0.015f), Size(w - 2 * m, h - 2 * m), CornerRadius(cornerOf(w) * 0.6f), style = Stroke(w * 0.012f))
        // Rivets.
        val r = w * 0.035f
        for ((x, y2) in listOf(m * 0.55f to m * 0.55f, w - m * 0.55f to m * 0.55f, m * 0.55f to h - m * 0.55f, w - m * 0.55f to h - m * 0.55f)) {
            drawCircle(look.backDark, r, Offset(x, y2))
            drawCircle(look.backLight, r * 0.55f, Offset(x - r * 0.25f, y2 - r * 0.25f))
        }
        // A scatter of engraved stars around the emblem.
        for ((sx, sy, sr) in backStars) {
            drawSparkle(Offset(w * sx, h * sy), w * sr, Color.White.copy(alpha = 0.75f))
            drawSparkle(Offset(w * sx + w * 0.006f, h * sy + w * 0.008f), w * sr * 0.7f, look.backDark.copy(alpha = 0.25f))
        }
        alienEmblem(look, Offset(w / 2, h / 2), w * 0.25f, t, index)
    }
}

/** Stars on a metal card's back, as fractions of its size: x, y and radius. */
private val backStars = listOf(
    Triple(0.24f, 0.2f, 0.05f),
    Triple(0.78f, 0.25f, 0.035f),
    Triple(0.2f, 0.76f, 0.035f),
    Triple(0.74f, 0.8f, 0.05f),
    Triple(0.52f, 0.15f, 0.025f),
    Triple(0.5f, 0.87f, 0.025f),
)

/** A round plate stamped with a little alien head, its antennae bobbing. */
private fun DrawScope.alienEmblem(look: MemoryLook, c: Offset, r: Float, t: Float, index: Int) {
    drawCircle(look.backDark.copy(alpha = 0.55f), r, c + Offset(0f, r * 0.06f))
    drawCircle(Brush.verticalGradient(listOf(look.backDark, lerp(look.backDark, look.back, 0.5f)), c.y - r, c.y + r), r * 0.94f, c)
    drawCircle(Color.White.copy(alpha = 0.4f), r * 0.94f, c, style = Stroke(r * 0.05f))
    val bob = swing(t, 50, index * 0.13f) * r * 0.06f
    val green = look.backAccent
    val dark = lerp(green, Color.Black, 0.3f)
    // Antennae with pink tips.
    drawLine(dark, c + Offset(-r * 0.2f, -r * 0.25f), c + Offset(-r * 0.42f, -r * 0.62f + bob), strokeWidth = r * 0.08f)
    drawLine(dark, c + Offset(r * 0.2f, -r * 0.25f), c + Offset(r * 0.42f, -r * 0.62f - bob), strokeWidth = r * 0.08f)
    drawCircle(look.backTrim, r * 0.12f, c + Offset(-r * 0.42f, -r * 0.62f + bob))
    drawCircle(look.backTrim, r * 0.12f, c + Offset(r * 0.42f, -r * 0.62f - bob))
    // Head and eyes.
    drawOval(dark, Offset(c.x - r * 0.52f, c.y - r * 0.38f), Size(r * 1.04f, r * 0.84f))
    drawOval(green, Offset(c.x - r * 0.5f, c.y - r * 0.4f), Size(r * 0.98f, r * 0.8f))
    val ink = Color(0xFF26222B)
    drawOval(ink, Offset(c.x - r * 0.3f, c.y - r * 0.15f), Size(r * 0.22f, r * 0.3f))
    drawOval(ink, Offset(c.x + r * 0.08f, c.y - r * 0.15f), Size(r * 0.22f, r * 0.3f))
    drawCircle(Color.White, r * 0.05f, c + Offset(-r * 0.22f, -r * 0.08f))
    drawCircle(Color.White, r * 0.05f, c + Offset(r * 0.16f, -r * 0.08f))
    drawArc(ink, 20f, 140f, false, Offset(c.x - r * 0.12f, c.y + r * 0.08f), Size(r * 0.24f, r * 0.14f), style = Stroke(r * 0.05f))
}

private fun DrawScope.glassFace(look: MemoryLook, t: Float) {
    val w = size.width
    val h = size.height
    val card = cardPath()
    drawPath(card, Brush.verticalGradient(listOf(look.faceLight, look.face)))
    clipPath(card) {
        drawGlow(Offset(w / 2, h * 0.52f), w * 0.55f, Color(0xFFB8A8FF).copy(alpha = 0.32f))
        for (k in 0 until 14) {
            val x = noise(k * 13 + 1) * w
            val y = noise(k * 7 + 5) * h
            val tw = 0.5f + 0.5f * swing(t, 30 + k * 3, k * 0.17f)
            drawCircle(Color.White.copy(alpha = 0.35f + 0.45f * tw), w * (0.008f + 0.008f * noise(k)), Offset(x, y))
        }
        drawRect(Brush.verticalGradient(listOf(Color.White.copy(alpha = 0.14f), Color.Transparent), 0f, h * 0.35f))
    }
    drawPath(card, look.faceEdge, style = Stroke(w * 0.035f))
    drawPath(card, Color.White.copy(alpha = 0.5f), style = Stroke(w * 0.012f))
}

/** The backdrop the cards lie on, filling [bounds] (in this scope's pixels), [corner] rounded. */
internal fun DrawScope.drawMemoryBackdrop(look: MemoryLook, bounds: Rect, corner: Float, t: Float) {
    val shape = Path().apply { addRoundRect(RoundRect(bounds, CornerRadius(corner))) }
    translate(0f, corner * 0.18f) { drawPath(shape, Color.Black.copy(alpha = 0.18f)) }
    when (look.style) {
        MemoryStyle.RUG -> tentCanvas(look, bounds, shape, corner)
        MemoryStyle.METAL -> starPanel(look, bounds, shape, corner, t)
    }
}

private fun DrawScope.tentCanvas(look: MemoryLook, bounds: Rect, shape: Path, corner: Float) {
    drawPath(shape, look.backdrop)
    clipPath(shape) {
        // Wide canvas stripes, as inside a desert tent.
        val stripe = bounds.width / 9f
        for (k in 0 until 9 step 2) {
            drawRect(look.backdropDark.copy(alpha = 0.55f), Offset(bounds.left + k * stripe, bounds.top), Size(stripe, bounds.height))
        }
        drawRect(
            Brush.verticalGradient(listOf(Color.Black.copy(alpha = 0.12f), Color.Transparent, Color.Black.copy(alpha = 0.1f)), bounds.top, bounds.bottom),
            bounds.topLeft,
            bounds.size,
        )
        // A scalloped valance along the top.
        val n = 9
        val sw = bounds.width / n
        val depth = minOf(corner * 0.9f, sw * 0.45f)
        drawRect(look.backdropTrim, bounds.topLeft, Size(bounds.width, depth * 0.55f))
        for (k in 0 until n) {
            drawArc(look.backdropTrim, 0f, 180f, true, Offset(bounds.left + k * sw, bounds.top + depth * 0.55f - depth * 0.5f), Size(sw, depth))
            drawCircle(look.backAccent, depth * 0.14f, Offset(bounds.left + (k + 0.5f) * sw, bounds.top + depth * 0.92f))
        }
        drawRect(look.backAccent, bounds.topLeft + Offset(0f, depth * 0.42f), Size(bounds.width, depth * 0.08f))
    }
    drawPath(shape, look.faceEdge, style = Stroke(corner * 0.12f))
}

private fun DrawScope.starPanel(look: MemoryLook, bounds: Rect, shape: Path, corner: Float, t: Float) {
    drawPath(shape, Brush.verticalGradient(listOf(look.backdropDark, look.backdrop, look.backdropDark), bounds.top, bounds.bottom))
    clipPath(shape) {
        // A faint nebula and a ringed planet in the far corner.
        drawGlow(Offset(bounds.left + bounds.width * 0.2f, bounds.top + bounds.height * 0.7f), bounds.width * 0.6f, Color(0xFFB45AD2).copy(alpha = 0.22f))
        drawGlow(Offset(bounds.right - bounds.width * 0.2f, bounds.top + bounds.height * 0.25f), bounds.width * 0.5f, Color(0xFF4AA8E0).copy(alpha = 0.18f))
        for (k in 0 until 70) {
            val x = bounds.left + noise(k * 17 + 3) * bounds.width
            val y = bounds.top + noise(k * 29 + 11) * bounds.height
            val tw = 0.5f + 0.5f * swing(t, 20 + k % 13 * 4, noise(k * 5))
            val r = corner * (0.03f + 0.05f * noise(k * 3 + 1))
            drawCircle(Color.White.copy(alpha = 0.35f + 0.55f * tw), r, Offset(x, y))
            if (k % 11 == 0) drawSparkle(Offset(x, y), r * 3.2f * (0.6f + 0.4f * tw), Color.White.copy(alpha = 0.8f * tw))
        }
        val pc = Offset(bounds.right - corner * 1.1f, bounds.top + corner * 1.1f)
        val pr = corner * 0.55f
        drawOval(Color(0xFFFFD9A0).copy(alpha = 0.7f), Offset(pc.x - pr * 1.8f, pc.y - pr * 0.35f), Size(pr * 3.6f, pr * 0.7f), style = Stroke(pr * 0.12f))
        drawCircle(Brush.verticalGradient(listOf(Color(0xFFFFC27A), Color(0xFFD86A3C)), pc.y - pr, pc.y + pr), pr, pc)
    }
    drawPath(shape, look.backdropTrim, style = Stroke(corner * 0.1f))
    drawPath(shape, Color.White.copy(alpha = 0.35f), style = Stroke(corner * 0.03f))
}

/** Sparkles flying out from [c] as [b] goes from 0 to 1, reaching [reach] at the end, in [color] and white. */
internal fun DrawScope.drawFlourish(c: Offset, reach: Float, b: Float, color: Color) {
    if (b <= 0f || b >= 1f) return
    drawGlow(c, reach * (0.4f + 0.6f * b), color.copy(alpha = 0.6f * (1f - b)))
    for (k in 0 until 14) {
        val a = k * PI / 7 + 0.2
        val d = reach * (0.25f + 0.75f * b) * (if (k % 2 == 0) 1f else 0.78f)
        val p = c + Offset((cos(a) * d).toFloat(), (sin(a) * d).toFloat())
        drawSparkle(p, reach * (if (k % 3 == 0) 0.06f else 0.04f) * (1f - b * 0.5f), (if (k % 2 == 0) color else Color.White).copy(alpha = 1f - b))
    }
}
