package io.colorsand.ui.fx

import androidx.compose.animation.core.Animatable
import androidx.compose.animation.core.LinearEasing
import androidx.compose.animation.core.tween
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.composed
import androidx.compose.ui.graphics.graphicsLayer
import io.colorsand.ui.RejectedPour
import kotlin.math.PI
import kotlin.math.sin

internal const val SHAKE_MILLIS = 320

/**
 * The shake at [t] (0 to 1 over [SHAKE_MILLIS]), in tube widths sideways: a quick wobble that starts strong and
 * settles, so most of it shows before the paw comes for the tube.
 */
internal fun shakeOffset(t: Float): Float {
    if (t <= 0f || t >= 1f) return 0f
    val fade = (1 - t) * (1 - t)
    return 0.12f * fade * sin(2 * PI.toFloat() * 3f * t)
}

/**
 * Shakes tube [index] side to side for a moment when [rejected] is a new tap on it that couldn't take the sand.
 * A rejection from before this tube was first shown doesn't shake it. Put it before the modifier that reports
 * the tube's place to the paw: the paw picks the rejected tube up at once, and then the tube in its grip shakes.
 */
fun Modifier.rejectShake(rejected: RejectedPour?, index: Int): Modifier = composed {
    val clock = remember { Animatable(1f) }
    val shown = remember { rejected?.id }
    val event = rejected?.takeIf { it.to == index && it.id != shown }
    LaunchedEffect(event?.id) {
        if (event != null) {
            clock.snapTo(0f)
            clock.animateTo(1f, tween(SHAKE_MILLIS, easing = LinearEasing))
        }
    }
    graphicsLayer {
        val s = shakeOffset(clock.value)
        translationX = s * size.width
    }
}
