/**
 * Catch the grains: colored sand drifts down over [arena]'s scenery (blown along by the breeze on the Beach, off a
 * dune crest in the Desert, slow red dust on Mars) and a container slides along the bottom to catch it, where it
 * piles up in layers of color. Drag or tap to move it; Left and Right move it from the keyboard, and Enter, Space or
 * a screen reader's tap turns on a helper that catches by itself. Missed grains just land in the sand. Once the
 * container is full it shimmers and the round calls [onFinished]; [seed] picks how the sand falls.
 */
@Composable
fun CatchTheGrainsGame(arena: Arena, seed: Int, feedback: Feedback, onFinished: () -> Unit, modifier: Modifier = Modifier) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val look = remember(arena, grade) { CatchLook.of(arena, grade) }
    val round = remember(seed, arena) { GrainCatch(GrainFall.of(arena), seed) }
    val splashes = remember(seed) { mutableListOf<Splash>() }
    var frame by remember(seed) { mutableStateOf(0) }
    var caught by remember(seed) { mutableStateOf(0) }
    var auto by remember(seed) { mutableStateOf(false) }
    var full by remember(seed) { mutableStateOf(false) }
    var held by remember(seed) { mutableStateOf(0) }
    val sceneClock = rememberSceneClock()
    val focus = remember { FocusRequester() }
    // Keys go to the game straight away, so Left and Right move the container without tabbing to it first.
    LaunchedEffect(focus) { runCatching { focus.requestFocus() } }
    val sand = remember(palette) { { c: SandColor -> palette.sand(c) } }

    LaunchedEffect(round) {
        var last = -1L
        while (true) {
            withFrameNanos { now ->
                val dt = if (last < 0) 0f else (now - last) / 1_000_000_000f
                last = now
                if (held != 0) round.target = round.bin + held * GrainCatch.NUDGE
                round.auto = auto
                val events = round.step(dt)
                if (CatchEvent.CAUGHT in events) {
                    for (g in round.justCaught) splashes += Splash(g.x, g.at, g.color)
                    caught = round.caught.size
                    feedback.tick()
                    if (caught % 10 == 0 || round.isFull) {
                        feedback.play(Sounds.chime((caught / 10).coerceIn(1, 4) + 1))
                    } else {
                        feedback.play(Sounds.click)
                    }
                }
                if (CatchEvent.FULL in events) {
                    full = true
                    feedback.confirm()
                }
                splashes.removeAll { round.time - it.at > SPLASH_S }
                frame++
            }
        }
    }
    LaunchedEffect(full) {
        if (full) {
            delay((SHIMMER_S * 1000).toLong())
            onFinished()
        }
    }

    val noun = look.catcher.noun
    val status = when {
        full -> look.full
        auto -> "Helper on: catching by itself"
        caught >= 30 -> "Almost full…"
        caught >= 20 -> "Halfway there! Lovely layers."
        caught >= 10 -> "Nice catching! Keep going."
        else -> look.start
    }
    fun toggleAuto() {
        if (full) return
        auto = !auto
        feedback.play(Sounds.click)
    }

    Column(modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        Canvas(
            Modifier
                .weight(1f)
                .fillMaxWidth()
                .clip(RoundedCornerShape(28.dp))
                .semantics {
                    contentDescription = "Sand falling toward a $noun at the bottom"
                    stateDescription = "$caught of ${round.capacity} grains caught" + if (auto) ", helper on" else ""
                    onClick(label = if (auto) "Stop the helper" else "Catch by itself") { toggleAuto(); true }
                    customActions = listOf(
                        CustomAccessibilityAction("Move left") { round.nudge(-1); true },
                        CustomAccessibilityAction("Move right") { round.nudge(1); true },
                    )
                }
                .onKeyEvent { event ->
                    val dir = when (event.key) {
                        Key.DirectionLeft -> -1
                        Key.DirectionRight -> 1
                        else -> 0
                    }
                    when {
                        dir != 0 && event.type == KeyEventType.KeyDown -> { held = dir; round.nudge(dir); true }
                        dir != 0 && event.type == KeyEventType.KeyUp -> { if (held == dir) held = 0; true }
                        (event.key == Key.Enter || event.key == Key.Spacebar) && event.type == KeyEventType.KeyUp -> { toggleAuto(); true }
                        else -> false
                    }
                }
                .focusRequester(focus)
                .focusable()
                .pointerInput(round) {
                    // Wherever a finger presses or drags, the container slides over to it.
                    awaitEachGesture {
                        val down = awaitFirstDown()
                        val width = size.width.toFloat()
                        round.target = down.position.x / width
                        auto = false
                        while (true) {
                            val event = awaitPointerEvent()
                            val change = event.changes.firstOrNull { it.id == down.id } ?: break
                            if (!change.pressed) break
                            round.target = change.position.x / width
                            change.consume()
                        }
                    }
                },
        ) {
            if (frame < 0) return@Canvas
            val layout = CatchLayout(size.width, size.height)
            drawCatchScenery(look, layout, round.time)
            drawCatchKeepsake(look, layout, grade, sceneClock.value)
            drawLanded(layout, round, sand)
            drawGrains(look, layout, round, sand)
            val shimmer = round.fullAt?.let { ((round.time - it) / SHIMMER_S).coerceIn(0f, 1f) }
            drawContainer(look, layout, round, splashes, sand, shimmer)
        }
        Spacer(Modifier.height(12.dp))
        Row(
            Modifier
                .widthIn(max = 460.dp)
                .frosted(palette, RoundedCornerShape(50), elevation = 4.dp)
                .padding(horizontal = 18.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(12.dp),
        ) {
            Text(
                status,
                color = palette.text,
                fontSize = 16.sp,
                fontWeight = FontWeight.Bold,
                textAlign = TextAlign.Center,
                maxLines = 1,
                modifier = Modifier.weight(1f, fill = false).semantics { liveRegion = LiveRegionMode.Polite },
            )
            Text(
                "$caught/${round.capacity}",
                color = palette.accent,
                fontSize = 16.sp,
                fontWeight = FontWeight.Black,
                maxLines = 1,
            )
        }
    }
}
