package io.colorsand.ui.minigame

import kotlin.random.Random

/**
 * A round of Keepsake memory: [faces] lists, card by card in reading order, which of the pairs (0 until [pairs])
 * each card shows. Turning a first card shows it; turning a second shows it too, and either the two make a pair
 * and stay up ([matched]) or they are a [miss] and turn back down at the next [settle] (or the next turn). There is
 * no move limit and no way to lose: every pair is found in the end. The state is immutable; [turn] and [settle]
 * return the next one.
 */
data class KeepsakeMemory(
    val faces: List<Int>,
    /** The cards found in pairs, face up for good. */
    val matched: Set<Int> = emptySet(),
    /** The first card of a pair being looked for, face up, or null. */
    val first: Int? = null,
    /** The two cards just turned that are not a pair, face up until they [settle]. */
    val miss: Pair<Int, Int>? = null,
    /** How many pairs of cards have been turned so far. Only for show: there is no limit. */
    val tries: Int = 0,
) {
    val cards: Int get() = faces.size

    val pairs: Int get() = faces.size / 2

    val pairsFound: Int get() = matched.size / 2

    val isDone: Boolean get() = matched.size == faces.size

    /** Whether [card] shows its face now: matched, the first of a pair, or half of a miss. */
    fun isFaceUp(card: Int): Boolean =
        card in matched || card == first || (miss != null && (card == miss.first || card == miss.second))

    /** The card with the same face as [card]. */
    fun twinOf(card: Int): Int = faces.indices.first { it != card && faces[it] == faces[card] }

    /** This round once a [miss] has turned back down. */
    fun settle(): KeepsakeMemory = if (miss == null) this else copy(miss = null)

    /**
     * This round after turning [card]. A miss still showing turns back down first. Turning a card that is already up,
     * off the table, or after the last pair does nothing (the same state comes back).
     */
    fun turn(card: Int): KeepsakeMemory {
        if (isDone || card !in faces.indices || card in matched || card == first) return this
        val base = settle()
        val open = base.first ?: return base.copy(first = card)
        return if (faces[open] == faces[card]) {
            base.copy(matched = matched + open + card, first = null, tries = tries + 1)
        } else {
            base.copy(first = null, miss = open to card, tries = tries + 1)
        }
    }

    companion object {
        /** A new round of [pairs] pairs, shuffled the same way for the same [seed]. */
        fun start(seed: Int, pairs: Int = 6): KeepsakeMemory {
            require(pairs >= 1) { "A round needs at least one pair" }
            val faces = (0 until pairs).flatMap { listOf(it, it) }.shuffled(Random(seed))
            return KeepsakeMemory(faces)
        }
    }
}
