package io.colorsand.ui.minigame

import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Rect
import androidx.compose.ui.graphics.drawscope.DrawScope
import io.colorsand.core.Arena
import io.colorsand.core.KeepsakeGame
import io.colorsand.core.Minigame
import io.colorsand.ui.arena.SceneGrade

// The Hide and seek scenes are drawn on a stage STAGE_W x STAGE_H units big, y down, which SeekFrame fits into the
// play area above the tray. The scenery around it (sky, water, ground) runs on past the stage to the play area's
// edges.

internal const val STAGE_W = 100f
internal const val STAGE_H = 120f

/** How a prop moves when tapped in vain: a bush shakes, kelp sways, a rock or a box wobbles. */
internal enum class Rustle { SHAKE, SWAY, WOBBLE }

/**
 * A prop in a Hide and seek scene: what it is called ("the slide"), where a tap counts as touching it ([hit], in
 * stage units), the point it rustles around ([pivot]) and how ([rustle]).
 */
internal class SeekProp(val name: String, val hit: Rect, val pivot: Offset, val rustle: Rustle)

/**
 * A hiding spot by prop [prop]: a thing hiding there stands with the middle of its foot at ([x], [y]), [size] units
 * at its tallest or widest, leaning [tilt] degrees. Its prop's back is drawn behind it and its front over it, so it
 * peeks out partly hidden. Behind a prop that hides its foot anyway ([peek]), a flat thing is lifted until its top is
 * as high as a tall one's would be, so everything shows about as much over the prop.
 */
internal class SeekSpot(
    val prop: Int,
    val x: Float,
    val y: Float,
    val size: Float,
    val tilt: Float = 0f,
    val peek: Boolean = false,
) {
    /** About the middle of whatever hides here, in stage units. */
    val center: Offset get() = Offset(x, y - size * 0.5f)
}

/**
 * A Hide and seek scene: its [props] in back-to-front order, each with the spots behind or in it, and how to draw
 * it. [drawScenery] paints everything that never hides anything (sky, ground, far-off things) over the visible
 * [view] (stage units, past the stage's edges); [drawBack] and [drawFront] paint a prop behind and in front of
 * what hides in it, in stage units with the prop's rustle already applied.
 */
internal abstract class SeekScene {
    abstract val props: List<SeekProp>
    abstract val spots: List<SeekSpot>

    abstract fun DrawScope.drawScenery(view: Rect, t: Float)
    abstract fun DrawScope.drawBack(prop: Int, t: Float)
    abstract fun DrawScope.drawFront(prop: Int, t: Float)
}

/**
 * The look of Hide and seek in [arena]: the [scene], the keepsake that hides ([keepsake], its stage) and the four
 * friends hiding with it ([friends], their stages), all drawn with the keepsakes' own art.
 */
internal class SeekLook(val arena: Arena, val scene: SeekScene, val keepsake: Int, val friends: List<Int>) {
    /** The stages of everything hiding: the keepsake, then its friends. Thing i of a round is `hiders[i]`. */
    val hiders: List<Int> get() = listOf(keepsake) + friends

    /** Where thing [i]'s painting lies in its keepsake's 100-unit box, shadows and loose bits left out. */
    fun bounds(i: Int): Rect = artBounds(arena, hiders[i])

    /** Where thing [i] lies when it hides at [spot], [scale] times the spot's size: its foot on the spot. */
    fun place(i: Int, spot: SeekSpot, scale: Float): Rect {
        val b = bounds(i)
        val size = spot.size * scale
        val k = size / maxOf(b.width, b.height)
        val top = if (spot.peek) spot.y - size else spot.y - b.height * k
        return Rect(spot.x - b.width * k / 2, top, spot.x + b.width * k / 2, top + b.height * k)
    }

    /** What thing [i] is called in a sentence ("teddy", "the ball"). */
    fun name(i: Int): String {
        val name = KeepsakeGame.of(arena, hiders[i]).keepsake
        return if (name == "teddy") name else "the $name"
    }

    companion object {
        /** [arena]'s Hide and seek, its colors through [g]. Arenas without one get the Playground's scene. */
        fun of(arena: Arena, g: SceneGrade): SeekLook {
            val keepsake = (1..Arena.LEVELS).firstOrNull { KeepsakeGame.of(arena, it).game == Minigame.HIDE_AND_SEEK } ?: 1
            val friends = (1..Arena.LEVELS).filter { it != keepsake }
            val scene = when (arena) {
                Arena.SEA_FLOOR -> SeaSeekScene(g)
                else -> PlaygroundSeekScene(g)
            }
            return SeekLook(arena, scene, keepsake, friends)
        }
    }
}

/** Where the painting of [arena]'s keepsake for [stage] lies in its 100-unit box (see KeepsakeArt.kt). */
private fun artBounds(arena: Arena, stage: Int): Rect = when (arena) {
    Arena.SEA_FLOOR -> when (stage) {
        1 -> Rect(26f, 44f, 76f, 75f)
        2 -> Rect(34f, 12f, 76f, 91f)
        3 -> Rect(24f, 25f, 76f, 94f)
        4 -> Rect(17f, 38f, 92f, 84f)
        else -> Rect(22f, 32f, 78f, 96f)
    }
    else -> when (stage) {
        1 -> Rect(28f, 51f, 72f, 96f)
        2 -> Rect(24f, 39f, 88f, 96f)
        3 -> Rect(10f, 49f, 90f, 96f)
        4 -> Rect(22f, 21f, 78f, 96f)
        // The kite without its string and peg.
        else -> Rect(36f, 3f, 80f, 62f)
    }
}

/**
 * Where the stage sits in a play area [width] x [height] pixels big, with [reserve] pixels kept free at the bottom
 * for the tray: as large as fits, centered across, resting on the tray.
 */
internal class SeekFrame(val width: Float, val height: Float, reserve: Float) {
    /** Pixels per stage unit. */
    val unit: Float = minOf(width / STAGE_W, (height - reserve) / STAGE_H).coerceAtLeast(0.01f)
    val origin: Offset = Offset((width - STAGE_W * unit) / 2, height - reserve - STAGE_H * unit)

    /** The play area in stage units. */
    val view: Rect get() = Rect(toStage(Offset.Zero), toStage(Offset(width, height)))

    fun toStage(p: Offset): Offset = (p - origin) / unit
    fun toPx(p: Offset): Offset = origin + p * unit
}
