/**
 * Sand art bottle: a tall glass bottle over a row of jars of [arena]'s colored sand (sea and sunset colors on the
 * Beach, ochres, terracotta, indigo and saffron in the Desert). Pick a jar, then press and hold on the bottle: the
 * sand runs in from a funnel at the top in a thin stream and heaps up where it lands, so sliding the finger from
 * side to side lays wavy bands (see [SandArt]). Once the bottle is full a cork pops in, it rocks gently with a shine
 * and [onFinished] is called. Nothing can go wrong; [seed] only picks the jar chosen at the start.
 */
@Composable
fun SandArtGame(arena: Arena, seed: Int, feedback: Feedback, onFinished: () -> Unit, modifier: Modifier = Modifier) {
    val palette = LocalPalette.current
    val grade = remember(palette) { SceneGrade.of(palette) }
    val look = remember(arena, grade) { SandArtLook.of(arena, grade) }
    var art by remember(seed) { mutableStateOf(SandArt.empty()) }
    var color by remember(seed) { mutableIntStateOf(((seed % look.jars.size) + look.jars.size) % look.jars.size) }
    var canvas by remember { mutableStateOf(IntSize.Zero) }
    // The finger on the bottle, in pixels, while it is held there.
    var finger by remember(seed) { mutableStateOf<Float?>(null) }
    var fresh by remember(seed) { mutableStateOf(false) }
    // A whole layer poured by keyboard or screen reader: how much of it is still to run in, and where.
    var auto by remember(seed) { mutableFloatStateOf(0f) }
    var autoAt by remember(seed) { mutableFloatStateOf(0.5f) }
    var at by remember(seed) { mutableFloatStateOf(0.5f) }
    var stream by remember(seed) { mutableFloatStateOf(0f) }
    var time by remember { mutableFloatStateOf(0f) }
    val cork = remember(seed) { Animatable(0f) }
    val turn = remember(seed) { Animatable(0f) }
    val finished by rememberUpdatedState(onFinished)
    // The bottle takes the keyboard focus straight away, so Enter or Space pours without hunting for it first.
    val focus = remember { FocusRequester() }
    LaunchedEffect(Unit) { runCatching { focus.requestFocus() } }

    LaunchedEffect(seed) {
        var last = 0L
        var sinceSound = 1f
        while (true) {
            withFrameNanos { now ->
                val dt = if (last == 0L) 0f else ((now - last) / 1e9f).coerceAtMost(0.1f)
                last = now
                time += dt
                val held = finger
                val running = !art.isFull && (held != null || auto > 0f)
                if (running) {
                    val target = if (held != null) BottleLayout(canvas.width.toFloat(), canvas.height.toFloat()).at(held) else autoAt
                    at += (target - at) * (dt * 10f).coerceAtMost(1f)
                    val amount = if (held != null) POUR_RATE * dt else minOf(auto, SandArt.LAYER / LAYER_SECONDS * dt)
                    if (held == null) auto -= amount
                    art = art.pour(color, at, amount, fresh)
                    if (amount > 0f) fresh = false
                    sinceSound += dt
                    if (sinceSound > SOUND_EVERY) {
                        feedback.play(Sounds.pour)
                        sinceSound = 0f
                    }
                } else {
                    sinceSound = 1f
                }
                stream += ((if (running) 1f else 0f) - stream) * (dt * 9f).coerceAtMost(1f)
            }
        }
    }
    LaunchedEffect(art.isFull) {
        if (!art.isFull) return@LaunchedEffect
        finger = null
        auto = 0f
        delay(250)
        feedback.play(Sounds.land)
        cork.animateTo(1f, spring(dampingRatio = 0.5f, stiffness = Spring.StiffnessMediumLow))
        feedback.play(Sounds.chime(5))
        feedback.confirm()
        launch { turn.animateTo(1f, tween(TURN_MS, easing = FastOutSlowInEasing)) }
        delay(SAND_FINISH_DELAY_MS)
        finished()
    }
    fun pourLayer() {
        if (art.isFull) return
        if (auto <= 0f) {
            autoAt = SandArt.layerSpot(art.layers.size)
            fresh = true
        }
        auto += SandArt.LAYER
        feedback.tick()
    }

    Column(modifier, horizontalAlignment = Alignment.CenterHorizontally) {
        Canvas(
            Modifier
                .weight(1f)
                .fillMaxWidth()
                .onSizeChanged { canvas = it }
                .semantics {
                    contentDescription = "Sand art bottle, ${art.percent} percent full"
                    stateDescription = "${look.jars[color].name} sand chosen"
                    onClick(label = "Pour a layer") { pourLayer(); true }
                }
                .onKeyEvent { event ->
                    val press = event.type == KeyEventType.KeyUp && (event.key == Key.Enter || event.key == Key.Spacebar)
                    if (press) pourLayer()
                    press
                }
                .focusRequester(focus)
                .focusable()
                .pointerInput(seed) {
                    awaitEachGesture {
                        val down = awaitFirstDown()
                        down.consume()
                        runCatching { focus.requestFocus() }
                        if (art.isFull) return@awaitEachGesture
                        finger = down.position.x
                        fresh = true
                        // Start the stream right over the finger, rather than gliding there from the last pour.
                        at = BottleLayout(size.width.toFloat(), size.height.toFloat()).at(down.position.x)
                        feedback.tick()
                        while (true) {
                            val event = awaitPointerEvent()
                            val change = event.changes.firstOrNull { it.id == down.id } ?: break
                            change.consume()
                            if (!change.pressed) break
                            finger = change.position.x
                        }
                        finger = null
                    }
                },
        ) {
            val layout = BottleLayout(size.width, size.height)
            val motion = BottleMotion(time, at, stream, cork.value, turn.value)
            drawSandBottle(arena, look, grade, layout, art, color, motion)
        }
        Spacer(Modifier.height(10.dp))
        SandJars(look, color, enabled = !art.isFull) {
            if (it != color) {
                color = it
                fresh = true
                feedback.play(Sounds.pick)
                feedback.tick()
            }
        }
        Spacer(Modifier.height(10.dp))
        val status = when {
            art.isFull -> "All corked up! What a beautiful bottle!"
            art.fill <= 0f -> "Pick a color, then hold the bottle to pour"
            finger != null && art.layers.size <= 2 -> "Slide side to side to make waves"
            art.fill > 0.78f -> "Nearly full, a little more!"
            else -> "Pick another color and keep pouring"
        }
        Text(
            status,
            color = palette.text,
            fontSize = 16.sp,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center,
            maxLines = 1,
            modifier = Modifier
                .widthIn(max = 420.dp)
                .frosted(palette, RoundedCornerShape(50), elevation = 4.dp)
                .padding(horizontal = 18.dp, vertical = 8.dp)
                .semantics { liveRegion = LiveRegionMode.Polite },
        )
    }
}

/** The jars of sand in a row: tap one to pour its color next. The chosen jar stands lifted with a glow. */
@Composable
private fun SandJars(look: SandArtLook, chosen: Int, enabled: Boolean, onPick: (Int) -> Unit) {
    val palette = LocalPalette.current
    Row(
        Modifier
            .frosted(palette, RoundedCornerShape(24.dp), elevation = 5.dp)
            .padding(horizontal = 8.dp, vertical = 6.dp),
        horizontalArrangement = Arrangement.spacedBy(4.dp),
    ) {
        look.jars.forEachIndexed { i, jar ->
            val lift by animateFloatAsState(if (i == chosen) 1f else 0f, spring(dampingRatio = 0.55f, stiffness = Spring.StiffnessMedium), label = "jar")
            Box(
                Modifier
                    .size(width = 52.dp, height = 64.dp)
                    .clickable(remember { MutableInteractionSource() }, indication = null, enabled = enabled, role = Role.Button) { onPick(i) }
                    .semantics {
                        contentDescription = "${jar.name} sand"
                        selected = i == chosen
                    },
            ) {
                Canvas(Modifier.fillMaxSize().graphicsLayer { translationY = -lift * 5.dp.toPx() }) { drawJar(jar, lift) }
            }
        }
    }
}

/** One little jar of sand, its lid on, a glow behind it when [chosen] (0 to 1). */
private fun DrawScope.drawJar(jar: SandColor, chosen: Float) {
    val w = size.width * 0.66f
    val h = size.height * 0.7f
    val left = (size.width - w) / 2
    val top = size.height * 0.2f
    if (chosen > 0.01f) drawGlow(Offset(size.width / 2, top + h * 0.55f), size.width * 0.62f, Color(0xFFFFF2B0).copy(alpha = 0.85f * chosen))
    val r = CornerRadius(w * 0.24f)
    val body = Path().apply { addRoundRect(androidx.compose.ui.geometry.RoundRect(left, top, left + w, top + h, r)) }
    drawRoundRect(Color.Black.copy(alpha = 0.14f), Offset(left + w * 0.06f, top + h * 0.06f), Size(w, h), r)
    drawPath(body, Color.White.copy(alpha = 0.45f))
    clipPath(body) {
        val sandTop = top + h * 0.3f
        drawRect(jar.base, Offset(left, sandTop), Size(w, top + h - sandTop))
        drawOval(jar.base, Offset(left, sandTop - h * 0.08f), Size(w, h * 0.16f))
        drawOval(jar.light.copy(alpha = 0.7f), Offset(left + w * 0.2f, sandTop - h * 0.05f), Size(w * 0.4f, h * 0.07f))
        for (k in 0 until 10) {
            val p = Offset(left + w * (0.1f + 0.8f * noise(k * 7 + jar.name.length)), sandTop + h * 0.08f + (h * 0.6f) * noise(k * 3 + 17))
            drawCircle(if (k % 2 == 0) jar.dark.copy(alpha = 0.6f) else jar.light, w * 0.035f, p)
        }
        drawRect(Brush.horizontalGradient(listOf(Color.Black.copy(alpha = 0.16f), Color.Transparent, Color.Black.copy(alpha = 0.2f)), left, left + w), Offset(left, top), Size(w, h))
    }
    drawRoundRect(Color.White.copy(alpha = 0.6f), Offset(left + w * 0.12f, top + h * 0.16f), Size(w * 0.12f, h * 0.6f), CornerRadius(w * 0.06f))
    drawPath(body, lerp(jar.dark, Color.White, 0.3f).copy(alpha = 0.55f), style = Stroke(w * 0.05f))
    // The lid: a rounded cap in the jar's color, a shade darker, with a lit band.
    val lidH = h * 0.16f
    val lid = jar.dark
    drawRoundRect(lid, Offset(left - w * 0.04f, top - lidH * 0.7f), Size(w * 1.08f, lidH), CornerRadius(lidH * 0.4f))
    drawRoundRect(Color.White.copy(alpha = 0.35f), Offset(left + w * 0.08f, top - lidH * 0.55f), Size(w * 0.5f, lidH * 0.25f), CornerRadius(lidH))
    if (chosen > 0.5f) drawRoundRect(Color.White.copy(alpha = chosen), Offset(left - w * 0.1f, top - lidH), Size(w * 1.2f, h + lidH * 1.3f), CornerRadius(w * 0.3f), style = Stroke(w * 0.06f))
}

/** How fast sand runs while the bottle is held: a share of the bottle per second (about half a minute to fill). */
private const val POUR_RATE = 0.034f

/** How long one whole layer takes to run in when poured by keyboard or screen reader, in seconds. */
private const val LAYER_SECONDS = 1.1f

/** How often the pouring hiss starts again while sand runs, in seconds. */
private const val SOUND_EVERY = 0.42f

/** How long the full bottle rocks and shines, in milliseconds. */
private const val TURN_MS = 2600

/** How long the corked bottle shows off before the round ends, in milliseconds (after the cork is in). */
private const val SAND_FINISH_DELAY_MS = 2200L
